        private void StartElvenBranchedSpearPersistence()
        {
            UnitEntityData[] party = Game.Instance.Player.Party.Where(value =>
                value != null && value.Descriptor != null).ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before Elven Branched Spear persistence qualification.");

            ElvenBranchedSpearBlueprintSet set =
                BlueprintBootstrap.ElvenBranchedSpears;
            BlueprintItemWeapon[] items = set == null || set.Named == null
                ? null : set.Entries.Select(value => value.Item).Concat(
                    set.Named.Entries.Select(value => value.Item)).ToArray();
            if (items == null || items.Length != 12 ||
                items.Any(value => value == null) ||
                items.Distinct().Count() != 12)
                throw new InvalidOperationException(
                    "The exact 12-item Elven Branched Spear registry is unavailable.");

            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveElvenBranchedSpearPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveElvenBranchedSpearVerifyCleanup;
            bool active = _context.FeatureModules.Active.ElvenBranchedSpears;
            int[] before = items.Select(value =>
                Game.Instance.Player.Inventory.Count(value)).ToArray();
            int finesseBefore = party.Count(value =>
                value.Descriptor.HasFact(set.FinesseTraining));

            if (prepare)
            {
                if (!active) throw new InvalidOperationException(
                    "Elven Branched Spear prepare requires the module to be active.");
                if (before.Any(value => value != 0))
                    throw new InvalidOperationException(
                        "The disposable working save already contains an Elven Branched Spear; prepare refused to mutate it.");
                if (finesseBefore != 0)
                    throw new InvalidOperationException(
                        "The disposable working save already contains Elven Branched Spear Finesse Training; prepare refused to mutate it.");
                DevelopmentActionResult grant =
                    DevelopmentControls.AddElvenBranchedSpearSet();
                _elvenBranchedSpearPersistenceGrantValid = grant.Succeeded;
                if (!grant.Succeeded) throw new InvalidOperationException(
                    "The development-only spear-set grant failed: " +
                    grant.Message);
                if (party[0].Descriptor.AddFact(set.FinesseTraining) == null)
                    throw new InvalidOperationException(
                        "The spear Finesse Training fact could not be added to the disposable working-save owner.");
            }
            else
                _elvenBranchedSpearPersistenceGrantValid = true;

            int[] observed = items.Select(value =>
                Game.Instance.Player.Inventory.Count(value)).ToArray();
            int expectedCount = prepare || verifyCleanup ? 1 : 0;
            _elvenBranchedSpearPersistenceIdentityValid =
                observed.All(value => value == expectedCount) &&
                items.All(value => BlueprintBootstrap.Library
                    .GetAllBlueprints().Count(candidate =>
                        ReferenceEquals(candidate, value)) == 1);
            ItemEntityWeapon[] instances = EnumerateRuntimeInventory(
                Game.Instance.Player.Inventory).OfType<ItemEntityWeapon>()
                .Where(value => items.Contains(value.Blueprint)).ToArray();
            _elvenBranchedSpearPersistenceCategoryValid =
                items.All(value => ReferenceEquals(value.Type,
                    set.WeaponType)) &&
                (expectedCount == 0 ? instances.Length == 0 :
                    instances.Length == 12 && items.All(item =>
                         instances.Count(instance => ReferenceEquals(
                             instance.Blueprint, item) && ReferenceEquals(
                             instance.Blueprint.Type, set.WeaponType)) == 1));
            int observedFinesse = party.Count(value =>
                value.Descriptor.HasFact(set.FinesseTraining));
            _elvenBranchedSpearPersistenceFinesseTrainingValid =
                observedFinesse == expectedCount &&
                (expectedCount == 0 ||
                    party[0].Descriptor.HasFact(set.FinesseTraining));

            if (verifyCleanup)
            {
                if (!_elvenBranchedSpearPersistenceIdentityValid ||
                    !_elvenBranchedSpearPersistenceCategoryValid ||
                    !_elvenBranchedSpearPersistenceFinesseTrainingValid)
                    throw new InvalidOperationException(
                        "Fresh-load spear identities, category, or Finesse Training selection did not survive before cleanup.");
                foreach (BlueprintItemWeapon item in items)
                    Game.Instance.Player.Inventory.Remove(item, 1);
                party[0].Descriptor.RemoveFact(set.FinesseTraining);
                _elvenBranchedSpearPersistenceCleanupValid = items.All(value =>
                    Game.Instance.Player.Inventory.Count(value) == 0) &&
                    party.All(value => !value.Descriptor.HasFact(
                        set.FinesseTraining));
            }
            else
                _elvenBranchedSpearPersistenceCleanupValid = prepare
                    ? observed.All(value => value == 1) && observedFinesse == 1
                    : observed.All(value => value == 0) && observedFinesse == 0;

            _elvenBranchedSpearPersistenceDetail = "active=" + active +
                ";phase=" + (prepare ? "prepare" : verifyCleanup
                    ? "verify-cleanup" : "verify-absent") +
                ";before=" + string.Join(",", before.Select(value =>
                    value.ToString()).ToArray()) + ";observed=" +
                string.Join(",", observed.Select(value => value.ToString())
                    .ToArray()) + ";instances=" + instances.Length +
                ";finesseBefore=" + finesseBefore + ";finesseObserved=" +
                observedFinesse + ";finesse=" +
                _elvenBranchedSpearPersistenceFinesseTrainingValid +
                ";identity=" + _elvenBranchedSpearPersistenceIdentityValid +
                ";category=" + _elvenBranchedSpearPersistenceCategoryValid +
                ";grant=" + _elvenBranchedSpearPersistenceGrantValid +
                ";cleanup=" + _elvenBranchedSpearPersistenceCleanupValid;
            if (!_elvenBranchedSpearPersistenceIdentityValid ||
                !_elvenBranchedSpearPersistenceCategoryValid ||
                !_elvenBranchedSpearPersistenceFinesseTrainingValid ||
                !_elvenBranchedSpearPersistenceGrantValid ||
                !_elvenBranchedSpearPersistenceCleanupValid)
                throw new InvalidOperationException(
                    "Elven Branched Spear persistence phase assertions failed: " +
                    _elvenBranchedSpearPersistenceDetail);

            if (!prepare && !verifyCleanup)
            {
                CompleteElvenBranchedSpearPersistence(
                    RuntimeTestStatuses.Pass, "");
                return;
            }
            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Game).GetMethods(
                BindingFlags.Instance | BindingFlags.Public |
                BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" &&
                    value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _elvenBranchedSpearPersistenceSaveStarted = true;
            _elvenBranchedSpearPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() =>
                    _elvenBranchedSpearPersistenceSaveCompleted = true)
            });
        }

        private void CompleteElvenBranchedSpearPersistence(string status,
            string warning)
        {
            WorkingSaveSmokeEvidence evidence = _workingSaveSmoke.Stop();
            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveElvenBranchedSpearPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveElvenBranchedSpearVerifyCleanup;
            bool writes = prepare || verifyCleanup;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("exact-working-load",
                    "one correlated working descriptor; baseline distinct",
                    "working=" + evidence.WorkingMatchCount + ";baseline=" +
                        evidence.BaselineMatchCount + ";correlated=" +
                        evidence.DescriptorReferenceCorrelated,
                    evidence.WorkingMatchCount == 1 &&
                        evidence.BaselineMatchCount == 1 &&
                        evidence.DescriptorReferenceCorrelated,
                    "object-reference-correlated guarded load path"),
                Assertion("elven-branched-spear-persistent-identities",
                    writes ? "one exact instance of each of 12 blueprints" :
                        "zero instances after cleanup",
                    _elvenBranchedSpearPersistenceDetail,
                    _elvenBranchedSpearPersistenceIdentityValid,
                    "fresh-load inventory blueprint reference equality and cardinality"),
                Assertion("elven-branched-spear-persistent-category",
                    "all registered and owned variants use category 0x004b4d47",
                    _elvenBranchedSpearPersistenceDetail,
                    _elvenBranchedSpearPersistenceCategoryValid,
                    "BlueprintItemWeapon.Type and deserialized ItemEntityWeapon.Blueprint"),
                Assertion("elven-branched-spear-persistent-finesse-training",
                    writes ? "one exact selected category feature on the deterministic owner" :
                        "no selected category feature after cleanup",
                    _elvenBranchedSpearPersistenceDetail,
                    _elvenBranchedSpearPersistenceFinesseTrainingValid,
                    "fresh-load UnitDescriptor fact ownership for the ordinary Finesse Training child"),
                Assertion("elven-branched-spear-development-grant",
                    prepare ? "one exact copy of all 12 variants" :
                        "not invoked outside prepare",
                    _elvenBranchedSpearPersistenceDetail,
                    _elvenBranchedSpearPersistenceGrantValid,
                    "existing development bridge with inventory cardinality checks"),
                Assertion(verifyCleanup || !writes ?
                        "elven-branched-spear-cleaned" :
                        "elven-branched-spear-prepared",
                    verifyCleanup || !writes ? "all 12 absent" :
                        "all 12 present exactly once",
                    _elvenBranchedSpearPersistenceDetail,
                    _elvenBranchedSpearPersistenceCleanupValid,
                    "exact per-blueprint inventory counts"),
                Assertion("exact-working-save-write",
                    writes ? "one SaveRoutine on exact captured SaveInfo" :
                        "none during final verification",
                    "count=" + evidence.ExpectedWorkingSaveRoutineCount +
                        ";stashedAreas=" +
                        evidence.ExpectedWorkingStashedAreaCount +
                        ";unexpected=" + evidence.SaveWritingApiObserved,
                    writes ? evidence.ExpectedWorkingSaveRoutineCount == 1 &&
                        evidence.ExpectedWorkingStashedAreaCount >= 1 &&
                        !evidence.SaveWritingApiObserved :
                        evidence.ExpectedWorkingSaveRoutineCount == 0 &&
                        !evidence.SaveWritingApiObserved,
                    "request-scoped exact native save sentinel"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _context.ModEntry.Info.Version ==
                        _request.ExpectedModVersion,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            RuntimeTestResult result = CreateResult(status, assertions, null);
            result.WorkingSaveSmoke = evidence;
            if (!string.IsNullOrWhiteSpace(warning))
                result.Warnings.Add(warning);
            Complete(result);
        }

        private void StartEasternWeaponsPersistence()
        {
            UnitEntityData[] party = Game.Instance.Player.Party.Where(value =>
                value != null && value.Descriptor != null).ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before Eastern Weapons persistence qualification.");

            EasternWeaponBlueprintSet set = BlueprintBootstrap.EasternWeapons;
            BlueprintItemWeapon[] items = set == null || set.Named == null ?
                null : set.Entries.Select(value => value.Item).Concat(
                    set.Named.Entries.Select(value => value.Item)).ToArray();
            if (items == null || items.Length != 30 ||
                items.Any(value => value == null) ||
                items.Distinct().Count() != 30)
                throw new InvalidOperationException(
                    "The exact 30-item Eastern Weapons registry is unavailable.");

            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveEasternWeaponsPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveEasternWeaponsVerifyCleanup;
            bool active = _context.FeatureModules.Active.EasternWeapons;
            int[] before = items.Select(value =>
                Game.Instance.Player.Inventory.Count(value)).ToArray();
            int wakizashiBefore = party.Count(value => value.Descriptor.HasFact(
                set.WakizashiProficiency));
            int katanaBefore = party.Count(value => value.Descriptor.HasFact(
                set.KatanaProficiency));

            if (prepare)
            {
                if (!active) throw new InvalidOperationException(
                    "Eastern Weapons prepare requires the module to be active.");
                if (before.Any(value => value != 0))
                    throw new InvalidOperationException(
                        "The disposable working save already contains an Eastern Weapon; prepare refused to mutate it.");
                if (wakizashiBefore != 0 || katanaBefore != 0)
                    throw new InvalidOperationException(
                        "The disposable working save already contains an exact Eastern Weapon proficiency fixture; prepare refused to mutate it.");
                DevelopmentActionResult grant =
                    DevelopmentControls.AddEasternWeaponSet();
                _easternWeaponsPersistenceGrantValid = grant.Succeeded;
                if (!grant.Succeeded) throw new InvalidOperationException(
                    "The development-only Eastern set grant failed: " +
                    grant.Message);
                if (party[0].Descriptor.AddFact(set.WakizashiProficiency) == null ||
                    party[1].Descriptor.AddFact(set.KatanaProficiency) == null)
                    throw new InvalidOperationException(
                        "The exact Eastern proficiency facts could not be added to their deterministic disposable owners.");
            }
            else
                _easternWeaponsPersistenceGrantValid = true;

            int expectedCount = prepare || verifyCleanup ? 1 : 0;
            int[] observed = items.Select(value =>
                Game.Instance.Player.Inventory.Count(value)).ToArray();
            _easternWeaponsPersistenceIdentityValid =
                observed.All(value => value == expectedCount) &&
                items.All(value => BlueprintBootstrap.Library.GetAllBlueprints()
                    .Count(candidate => ReferenceEquals(candidate, value)) == 1) &&
                BlueprintBootstrap.Library.GetAllBlueprints().Count(value =>
                    ReferenceEquals(value, set.WakizashiProficiency)) == 1 &&
                BlueprintBootstrap.Library.GetAllBlueprints().Count(value =>
                    ReferenceEquals(value, set.KatanaProficiency)) == 1;
            ItemEntityWeapon[] instances = EnumerateRuntimeInventory(
                Game.Instance.Player.Inventory).OfType<ItemEntityWeapon>()
                .Where(value => items.Contains(value.Blueprint)).ToArray();
            _easternWeaponsPersistenceCategoryValid = set.Families.Length == 3 &&
                set.Families.All(family => family.Entries.All(entry =>
                    ReferenceEquals(entry.Item.Type, family.WeaponType)) &&
                    set.Named.Entries.Where(entry => entry.Spec.Family ==
                        family.Family).All(entry => ReferenceEquals(
                            entry.Item.Type, family.WeaponType))) &&
                (expectedCount == 0 ? instances.Length == 0 :
                    instances.Length == 30 && items.All(item =>
                        instances.Count(instance => ReferenceEquals(
                            instance.Blueprint, item) && ReferenceEquals(
                            instance.Blueprint.Type, item.Type)) == 1));
            int wakizashiObserved = party.Count(value =>
                value.Descriptor.HasFact(set.WakizashiProficiency));
            int katanaObserved = party.Count(value =>
                value.Descriptor.HasFact(set.KatanaProficiency));
            _easternWeaponsPersistenceProficiencyValid =
                wakizashiObserved == expectedCount &&
                katanaObserved == expectedCount &&
                (expectedCount == 0 ||
                    (party[0].Descriptor.HasFact(set.WakizashiProficiency) &&
                     party[1].Descriptor.HasFact(set.KatanaProficiency)));

            BlueprintFeatureSelection ewp = BlueprintLibraryLookup.RequireExact<
                BlueprintFeatureSelection>(BlueprintBootstrap.Library,
                    EasternWeaponBlueprints
                        .NativeExoticWeaponProficiencySelectionGuid,
                    "native Exotic Weapon Proficiency selection");
            BlueprintFeatureSelection finesse = BlueprintLibraryLookup
                .RequireExact<BlueprintFeatureSelection>(
                    BlueprintBootstrap.Library, EasternWeaponBlueprints
                        .NativeFinesseTrainingSelectionGuid,
                    "native Rogue Finesse Training selection");
            int publicCount = ewp.AllFeatures.Count(value => ReferenceEquals(
                    value, set.WakizashiProficiency) || ReferenceEquals(value,
                        set.KatanaProficiency)) + finesse.AllFeatures.Count(
                    value => ReferenceEquals(value,
                        set.WakizashiFinesseTraining));
            _easternWeaponsPersistencePublicationValid = active ?
                publicCount == 3 && set.Campaign != null &&
                    EasternWeaponCategoryRuntime.PresentationEnabled :
                publicCount == 0 && set.Campaign == null &&
                    !EasternWeaponCategoryRuntime.PresentationEnabled;

            if (verifyCleanup)
            {
                if (active) throw new InvalidOperationException(
                    "Eastern verify/cleanup requires the module-disabled fresh process.");
                if (!_easternWeaponsPersistenceIdentityValid ||
                    !_easternWeaponsPersistenceCategoryValid ||
                    !_easternWeaponsPersistenceProficiencyValid ||
                    !_easternWeaponsPersistencePublicationValid)
                    throw new InvalidOperationException(
                        "Fresh-load Eastern identities, categories, proficiency facts, or module-disabled publication did not survive before cleanup.");
                foreach (BlueprintItemWeapon item in items)
                    Game.Instance.Player.Inventory.Remove(item, 1);
                party[0].Descriptor.RemoveFact(set.WakizashiProficiency);
                party[1].Descriptor.RemoveFact(set.KatanaProficiency);
                _easternWeaponsPersistenceCleanupValid = items.All(value =>
                    Game.Instance.Player.Inventory.Count(value) == 0) &&
                    party.All(value => !value.Descriptor.HasFact(
                        set.WakizashiProficiency) && !value.Descriptor.HasFact(
                            set.KatanaProficiency));
            }
            else
                _easternWeaponsPersistenceCleanupValid = prepare ?
                    observed.All(value => value == 1) &&
                        wakizashiObserved == 1 && katanaObserved == 1 :
                    observed.All(value => value == 0) &&
                        wakizashiObserved == 0 && katanaObserved == 0;

            _easternWeaponsPersistenceDetail = "active=" + active +
                ";phase=" + (prepare ? "prepare" : verifyCleanup ?
                    "verify-cleanup" : "verify-absent") + ";before=" +
                string.Join(",", before.Select(value => value.ToString())
                    .ToArray()) + ";observed=" + string.Join(",", observed
                    .Select(value => value.ToString()).ToArray()) +
                ";instances=" + instances.Length + ";proficiencies=" +
                wakizashiBefore + "/" + katanaBefore + "->" +
                wakizashiObserved + "/" + katanaObserved +
                ";publicCount=" + publicCount + ";identity=" +
                _easternWeaponsPersistenceIdentityValid + ";category=" +
                _easternWeaponsPersistenceCategoryValid + ";proficiency=" +
                _easternWeaponsPersistenceProficiencyValid + ";publication=" +
                _easternWeaponsPersistencePublicationValid + ";grant=" +
                _easternWeaponsPersistenceGrantValid + ";cleanup=" +
                _easternWeaponsPersistenceCleanupValid;
            if (!_easternWeaponsPersistenceIdentityValid ||
                !_easternWeaponsPersistenceCategoryValid ||
                !_easternWeaponsPersistenceProficiencyValid ||
                !_easternWeaponsPersistencePublicationValid ||
                !_easternWeaponsPersistenceGrantValid ||
                !_easternWeaponsPersistenceCleanupValid)
                throw new InvalidOperationException(
                    "Eastern Weapons persistence phase assertions failed: " +
                    _easternWeaponsPersistenceDetail);

            if (!prepare && !verifyCleanup)
            {
                CompleteEasternWeaponsPersistence(RuntimeTestStatuses.Pass, "");
                return;
            }
            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Game).GetMethods(
                BindingFlags.Instance | BindingFlags.Public |
                BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" && value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _easternWeaponsPersistenceSaveStarted = true;
            _easternWeaponsPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() => _easternWeaponsPersistenceSaveCompleted = true)
            });
        }

        private void CompleteEasternWeaponsPersistence(string status,
            string warning)
        {
            WorkingSaveSmokeEvidence evidence = _workingSaveSmoke.Stop();
            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveEasternWeaponsPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveEasternWeaponsVerifyCleanup;
            bool writes = prepare || verifyCleanup;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("exact-working-load",
                    "one correlated working descriptor; baseline distinct",
                    "working=" + evidence.WorkingMatchCount + ";baseline=" +
                        evidence.BaselineMatchCount + ";correlated=" +
                        evidence.DescriptorReferenceCorrelated,
                    evidence.WorkingMatchCount == 1 &&
                        evidence.BaselineMatchCount == 1 &&
                        evidence.DescriptorReferenceCorrelated,
                    "object-reference-correlated guarded load path"),
                Assertion("eastern-weapons-persistent-identities",
                    writes ? "one exact instance of each of 30 blueprints" :
                        "zero instances after cleanup",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistenceIdentityValid,
                    "fresh-load item and fact blueprint reference equality"),
                Assertion("eastern-weapons-persistent-categories",
                    "all saved items retain one of the three exact stable family weapon types",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistenceCategoryValid,
                    "BlueprintItemWeapon.Type and deserialized ItemEntityWeapon.Blueprint"),
                Assertion("eastern-weapons-persistent-proficiencies",
                    writes ? "one exact Wakizashi and Katana proficiency fact on deterministic owners" :
                        "zero exact test proficiency facts after cleanup",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistenceProficiencyValid,
                    "fresh-load UnitDescriptor fact ownership"),
                Assertion("eastern-weapons-module-publication",
                    verifyCleanup ? "module OFF has zero new selector, commerce, loot, and custom presentation publication" :
                        "module ON public surfaces are singular",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistencePublicationValid,
                    "immutable feature snapshot, selector arrays, campaign attachment, and presentation gate"),
                Assertion("eastern-weapons-development-grant",
                    prepare ? "one exact copy of all 30 variants" :
                        "not invoked outside prepare",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistenceGrantValid,
                    "development inventory bridge with exact count changes"),
                Assertion(verifyCleanup || !writes ?
                        "eastern-weapons-cleaned" : "eastern-weapons-prepared",
                    verifyCleanup || !writes ?
                        "all 30 items and two facts absent" :
                        "all 30 items and two facts present exactly once",
                    _easternWeaponsPersistenceDetail,
                    _easternWeaponsPersistenceCleanupValid,
                    "exact feature-owned inventory and fact removal"),
                Assertion("exact-working-save-write",
                    writes ? "one SaveRoutine on exact captured SaveInfo" :
                        "none during final verification",
                    "count=" + evidence.ExpectedWorkingSaveRoutineCount +
                        ";stashedAreas=" +
                        evidence.ExpectedWorkingStashedAreaCount +
                        ";unexpected=" + evidence.SaveWritingApiObserved,
                    writes ? evidence.ExpectedWorkingSaveRoutineCount == 1 &&
                        evidence.ExpectedWorkingStashedAreaCount >= 1 &&
                        !evidence.SaveWritingApiObserved :
                        evidence.ExpectedWorkingSaveRoutineCount == 0 &&
                        !evidence.SaveWritingApiObserved,
                    "request-scoped exact native save sentinel"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _context.ModEntry.Info.Version ==
                        _request.ExpectedModVersion,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            RuntimeTestResult result = CreateResult(status,
                assertions, null);
            result.WorkingSaveSmoke = evidence;
            if (!string.IsNullOrWhiteSpace(warning))
                result.Warnings.Add(warning);
            Complete(result);
        }

        private void StartExpandedSummoningPersistence()
        {
            UnitEntityData[] party = Game.Instance.Player.Party.Where(value =>
                value != null && value.Descriptor != null).ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before Expanded Summoning persistence qualification.");
            UnitEntityData caster = party.FirstOrDefault(value =>
                value.HoldingState != null);
            if (caster == null) throw new InvalidOperationException(
                "The loaded working save has no party member in an active area state.");
            object gameState = ReadExactMember(Game.Instance, "State");
            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveExpandedSummoningPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveExpandedSummoningVerifyCleanup;
            bool active = _context.FeatureModules.Active.ExpandedSummoning;
            int publishedReferences;
            _expandedSummoningPersistencePublicationValid =
                ExpandedSummoningPublisher.RequiredBasePublicationIsExact(
                    BlueprintBootstrap.Library, active,
                    out publishedReferences);

            if (prepare)
            {
                if (!active) throw new InvalidOperationException(
                    "Expanded Summoning prepare requires the module to be active.");
                if (!_expandedSummoningPersistenceFixtureSpawned)
                {
                    foreach (UnitEntityData stale in
                        ExpandedSummoningPersistentUnits(gameState, party))
                        stale.Dispose();
                    if (ExpandedSummoningPersistentUnits(gameState, party).Length != 0)
                        throw new InvalidOperationException(
                            "Stale KMG summons could not be removed before prepare.");
                    _expandedSummoningPersistencePreparedUnits =
                        SpawnExpandedSummoningPersistenceFixture(caster);
                    _expandedSummoningPersistenceFixtureSpawned = true;
                    return;
                }
                if (_expandedSummoningPersistenceSettleUpdates++ < 2) return;
            }

            UnitEntityData[] units = prepare ?
                _expandedSummoningPersistencePreparedUnits :
                ExpandedSummoningPersistentUnits(gameState, party);
            bool cleanupContinuation = verifyCleanup &&
                _expandedSummoningPersistenceCleanupStarted;
            if (!cleanupContinuation)
            {
                _expandedSummoningPersistenceUnitCount = units.Length;
                EvaluateExpandedSummoningPersistentUnits(caster, units,
                    out _expandedSummoningPersistenceIdentityValid,
                    out _expandedSummoningPersistenceContextValid,
                    out _expandedSummoningPersistenceDurationValid,
                    out _expandedSummoningPersistenceControlValid,
                    out _expandedSummoningPersistenceDetail);
            }

            if (verifyCleanup)
            {
                if (!_expandedSummoningPersistenceCleanupStarted)
                {
                    bool exactLifecycle = true;
                    foreach (UnitEntityData unit in units)
                    {
                        Buff[] summoned = unit.Descriptor.Buffs.RawFacts
                            .OfType<Buff>().Where(value => ReferenceEquals(
                                value.Blueprint, BlueprintRoot.Instance
                                    .SystemMechanics.SummonedUnitBuff)).ToArray();
                        exactLifecycle = exactLifecycle && summoned.Length == 1;
                        foreach (Buff buff in summoned) buff.Remove();
                        unit.Destroy();
                    }
                    if (!exactLifecycle) throw new InvalidOperationException(
                        "Fresh summons did not have one exact native lifecycle buff each.");
                    // As with synchronous creation above, the request executes
                    // after Kingmaker's controller tick. Advance the native
                    // destruction queue once so the test models a completed
                    // dismiss/expiration boundary before the follow-up save.
                    Game.Instance.EntityDestroyer.Tick();
                    _expandedSummoningPersistenceCleanupStarted = true;
                    return;
                }
                if (_expandedSummoningPersistenceCleanupSettleUpdates++ < 5)
                    return;
                int liveUnits = units.Count(value => !value.Destroyed ||
                    value.View != null || value.HoldingState != null);
                _expandedSummoningPersistenceCleanupValid = liveUnits == 0;
                _expandedSummoningPersistenceDetail += ";postExpirationRefs=" +
                    units.Length + ";postExpirationLive=" + liveUnits;
            }
            else if (prepare)
                _expandedSummoningPersistenceCleanupValid = units.Length == 2;
            else
            {
                _expandedSummoningPersistenceIdentityValid = units.Length == 0;
                _expandedSummoningPersistenceContextValid = units.Length == 0;
                _expandedSummoningPersistenceDurationValid = units.Length == 0;
                _expandedSummoningPersistenceControlValid = units.Length == 0;
                _expandedSummoningPersistenceCleanupValid = units.Length == 0;
            }

            bool phaseValid = _expandedSummoningPersistencePublicationValid &&
                _expandedSummoningPersistenceIdentityValid &&
                _expandedSummoningPersistenceContextValid &&
                _expandedSummoningPersistenceDurationValid &&
                _expandedSummoningPersistenceControlValid &&
                _expandedSummoningPersistenceCleanupValid &&
                (prepare || verifyCleanup ?
                    _expandedSummoningPersistenceUnitCount == 2 :
                    units.Length == 0);
            _expandedSummoningPersistenceDetail += ";active=" + active +
                ";published=" + publishedReferences + ";phaseValid=" +
                phaseValid;
            if (!phaseValid) throw new InvalidOperationException(
                "Expanded Summoning persistence phase assertions failed: " +
                _expandedSummoningPersistenceDetail);

            if (!prepare && !verifyCleanup)
            {
                CompleteExpandedSummoningPersistence(RuntimeTestStatuses.Pass, "");
                return;
            }
            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Game).GetMethods(BindingFlags.Instance |
                BindingFlags.Public | BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" && value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _expandedSummoningPersistenceSaveStarted = true;
            _expandedSummoningPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() =>
                    _expandedSummoningPersistenceSaveCompleted = true)
            });
        }

        private UnitEntityData[] SpawnExpandedSummoningPersistenceFixture(
            UnitEntityData caster)
        {
            BlueprintScriptableObject[] blueprints = BlueprintBootstrap.Library
                .GetAllBlueprints().Where(value => value != null).ToArray();
            SummonVariantSpec[] variants =
            {
                ExpandedSummoningCatalog.GenerateVariants(SummonFamily.Monster)
                    .Single(value => value.Creature.Key ==
                        "small-air-elemental" && value.ParentTier == 2 &&
                        value.Multiplicity == SummonMultiplicity.One),
                ExpandedSummoningCatalog.GenerateVariants(
                    SummonFamily.NaturesAlly).Single(value =>
                        value.Creature.Key == "wolf" && value.ParentTier == 2 &&
                        value.Multiplicity == SummonMultiplicity.One)
            };
            MethodInfo summonRuleMethod = typeof(RuleSummonUnit).GetMethod(
                "OnTrigger", BindingFlags.Public | BindingFlags.Instance);
            if (summonRuleMethod == null) throw new MissingMethodException(
                typeof(RuleSummonUnit).FullName, "OnTrigger");
            MethodInfo capturePostfix = typeof(RuntimeTestRunner).GetMethod(
                "ExpandedSummoningRuleCapturePostfix", BindingFlags.NonPublic |
                BindingFlags.Static);
            UnitEntityData[] result = null;
            try
            {
                _context.Harmony.Patch(summonRuleMethod, null,
                    new HarmonyMethod(capturePostfix), null);
                _expandedSummoningRuleCaptureActive = true;
                ExpandedSummoningRuleCapture.Clear();
                foreach (SummonVariantSpec variant in variants)
                {
                    BlueprintAbility ability = ResolveExpandedSummoningExecution(
                        blueprints, variant);
                    caster.Descriptor.AddFact(ability);
                    try
                    {
                        ExecuteExpandedSummoningRuntimeAbility(caster, ability,
                            variant.ParentTier);
                    }
                    finally
                    {
                        if (caster.Descriptor.HasFact(ability))
                            caster.Descriptor.RemoveFact(ability);
                    }
                }
                if (ExpandedSummoningRuleCapture.Count != 2)
                    throw new InvalidOperationException(
                        "Persistence prepare did not create exactly two native summons.");
                // The guarded scenario executes the native UnitUseAbility command
                // synchronously from Unity Mod Manager's update callback, after
                // the game's entity-creation controller has already ticked for
                // this frame. Complete that native queued creation boundary before
                // asking SaveGame to serialize the loaded area.
                Game.Instance.EntityCreator.Tick();
                result = ExpandedSummoningRuleCapture.ToArray();
                if (result.Any(value => value.HoldingState == null ||
                    !ReferenceEquals(value.HoldingState, caster.HoldingState)))
                    throw new InvalidOperationException(
                        "Persistence prepare summons did not enter the caster's exact loaded-area state.");
            }
            finally
            {
                _expandedSummoningRuleCaptureActive = false;
                ExpandedSummoningRuleCapture.Clear();
                _context.Harmony.Unpatch(summonRuleMethod,
                    HarmonyPatchType.All, _context.ModId);
            }
            return result;
        }

        private static UnitEntityData[] ExpandedSummoningPersistentUnits(
            object gameState, UnitEntityData[] party)
        {
            var unique = new List<UnitEntityData>();
            CollectExpandedSummoningUnitReferences(
                ReadExactMember(gameState, "AllUnits"), unique, 0);
            const BindingFlags flags = BindingFlags.Instance |
                BindingFlags.Public | BindingFlags.NonPublic;
            foreach (PropertyInfo property in gameState.GetType().GetProperties(flags)
                .Where(value => value.GetIndexParameters().Length == 0 &&
                    typeof(IEnumerable).IsAssignableFrom(value.PropertyType) &&
                    (value.Name.IndexOf("Unit", StringComparison.OrdinalIgnoreCase) >= 0 ||
                     value.Name.IndexOf("Entity", StringComparison.OrdinalIgnoreCase) >= 0)))
            {
                object collection = null;
                try { collection = property.GetValue(gameState, null); }
                catch { }
                CollectExpandedSummoningUnitReferences(collection, unique, 0);
            }
            foreach (FieldInfo field in gameState.GetType().GetFields(flags)
                .Where(value => typeof(IEnumerable).IsAssignableFrom(
                    value.FieldType) &&
                    (value.Name.IndexOf("Unit", StringComparison.OrdinalIgnoreCase) >= 0 ||
                     value.Name.IndexOf("Entity", StringComparison.OrdinalIgnoreCase) >= 0)))
                CollectExpandedSummoningUnitReferences(field.GetValue(gameState),
                    unique, 0);
            foreach (Kingmaker.EntitySystem.SceneEntitiesState state in
                (party ?? Array.Empty<UnitEntityData>()).Where(value =>
                    value != null && value.HoldingState != null).Select(value =>
                        value.HoldingState).Distinct())
                CollectExpandedSummoningUnitReferences(state.AllEntityData,
                    unique, 0);
            return unique
                .Where(value => value.Blueprint != null &&
                    (value.Blueprint.name ==
                        "KMG_Summoning_Unit_SmallAirElemental" ||
                     value.Blueprint.name == "KMG_Summoning_Unit_Wolf"))
                .OrderBy(value => value.Blueprint.name, StringComparer.Ordinal)
                .ToArray();
        }

        private static void CollectExpandedSummoningUnitReferences(
            object value, List<UnitEntityData> units, int depth)
        {
            if (value == null || depth > 3) return;
            UnitEntityData unit = value as UnitEntityData;
            if (unit != null)
            {
                if (!units.Any(candidate => ReferenceEquals(candidate, unit)))
                    units.Add(unit);
                return;
            }
            DictionaryEntry entry = value is DictionaryEntry ?
                (DictionaryEntry)value : new DictionaryEntry();
            if (value is DictionaryEntry)
            {
                CollectExpandedSummoningUnitReferences(entry.Key, units,
                    depth + 1);
                CollectExpandedSummoningUnitReferences(entry.Value, units,
                    depth + 1);
                return;
            }
            Type type = value.GetType();
            if (type.IsGenericType && type.GetGenericTypeDefinition() ==
                typeof(KeyValuePair<,>))
            {
                CollectExpandedSummoningUnitReferences(
                    type.GetProperty("Key").GetValue(value, null), units,
                    depth + 1);
                CollectExpandedSummoningUnitReferences(
                    type.GetProperty("Value").GetValue(value, null), units,
                    depth + 1);
                return;
            }
            if (value is string) return;
            IEnumerable enumerable = value as IEnumerable;
            if (enumerable == null) return;
            foreach (object item in enumerable)
                CollectExpandedSummoningUnitReferences(item, units, depth + 1);
        }

        private static void EvaluateExpandedSummoningPersistentUnits(
            UnitEntityData caster, UnitEntityData[] units, out bool identity,
            out bool context, out bool duration, out bool control,
            out string detail)
        {
            string[] expected = { "KMG_Summoning_Unit_SmallAirElemental",
                "KMG_Summoning_Unit_Wolf" };
            BlueprintUnit[] registered = BlueprintBootstrap.Library
                .GetAllBlueprints().OfType<BlueprintUnit>().Where(value =>
                    expected.Contains(value.name)).OrderBy(value => value.name,
                        StringComparer.Ordinal).ToArray();
            identity = units.Length == 2 && registered.Length == 2 &&
                units.Zip(registered, (unit, blueprint) =>
                    ReferenceEquals(unit.Blueprint, blueprint)).All(value => value);
            var durations = new List<double>();
            context = units.Length == 2;
            duration = units.Length == 2;
            foreach (UnitEntityData unit in units)
            {
                Buff[] lifecycle = unit.Descriptor.Buffs.RawFacts.OfType<Buff>()
                    .Where(value => value.MaybeContext != null &&
                        value.MaybeContext.MaybeCaster == caster &&
                        !value.IsPermanent && value.TimeLeft > TimeSpan.Zero &&
                        value.TimeLeft <= TimeSpan.FromSeconds(121d)).ToArray();
                Buff[] durationLifecycle = lifecycle.Where(value =>
                    value.TimeLeft >= TimeSpan.FromSeconds(30d)).ToArray();
                context = context && lifecycle.Length >= 1;
                duration = duration && durationLifecycle.Any(value =>
                    value.TimeLeft.TotalSeconds > 0d &&
                    value.TimeLeft.TotalSeconds <= 121d);
                durations.AddRange(lifecycle.Select(value =>
                    value.TimeLeft.TotalSeconds));
            }
            object faction = units.Length == 0 ? null :
                ExpandedSummoningFields(units[0].Blueprint.GetType())
                    .Single(value => value.Name == "Faction" ||
                        value.Name == "m_Faction").GetValue(units[0].Blueprint);
            control = units.Length == 2 && faction != null && units.All(value =>
                value.Commands != null && value.View != null &&
                value.View.Data == value &&
                ReferenceEquals(faction, ExpandedSummoningFields(
                    value.Blueprint.GetType()).Single(field =>
                        field.Name == "Faction" || field.Name == "m_Faction")
                    .GetValue(value.Blueprint)));
            detail = "units=" + units.Length + ";registered=" +
                registered.Length + ";durations=" + string.Join(",",
                    durations.Select(value => value.ToString("0.###",
                        System.Globalization.CultureInfo.InvariantCulture))
                    .ToArray()) + ";names=" + string.Join(",",
                    units.Select(value => value.Blueprint == null ? "<null>" :
                        value.Blueprint.name).ToArray()) + ";holding=" +
                    string.Join(",", units.Select(value =>
                        (value.HoldingState != null).ToString()).ToArray()) +
                    ";commands=" + string.Join(",", units.Select(value =>
                        (value.Commands != null).ToString()).ToArray()) +
                    ";views=" + string.Join(",", units.Select(value =>
                        (value.View != null).ToString()).ToArray()) +
                    ";viewData=" + string.Join(",", units.Select(value =>
                        (value.View != null && value.View.Data == value)
                            .ToString()).ToArray()) + ";faction=" +
                    (faction != null) +
                ";identity=" + identity + ";context=" +
                context + ";duration=" + duration + ";control=" + control;
        }

        private void CompleteExpandedSummoningPersistence(string status,
            string warning)
        {
            WorkingSaveSmokeEvidence evidence = _workingSaveSmoke.Stop();
            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveExpandedSummoningPrepare;
            bool verifyCleanup = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveExpandedSummoningVerifyCleanup;
            bool writes = prepare || verifyCleanup;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("exact-working-load",
                    "one correlated working descriptor; baseline distinct",
                    "working=" + evidence.WorkingMatchCount + ";baseline=" +
                        evidence.BaselineMatchCount + ";correlated=" +
                        evidence.DescriptorReferenceCorrelated,
                    evidence.WorkingMatchCount == 1 &&
                        evidence.BaselineMatchCount == 1 &&
                        evidence.DescriptorReferenceCorrelated,
                    "object-reference-correlated guarded load path"),
                Assertion("expanded-summoning-persistent-identities",
                    writes ? "two exact registered KMG units" : "zero KMG units",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistenceIdentityValid,
                    "fresh-load BlueprintUnit reference equality and cardinality"),
                Assertion("expanded-summoning-persistent-context",
                    writes ? "party[0] native summon context" : "not applicable after cleanup",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistenceContextValid,
                    "freshly deserialized nonpermanent summon lifecycle buff"),
                Assertion("expanded-summoning-persistent-duration",
                    writes ? "0 < remaining <= 121 seconds" : "not applicable after cleanup",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistenceDurationValid,
                    "native one-round-per-level lifecycle remaining time"),
                Assertion("expanded-summoning-persistent-control",
                    writes ? "live view, commands, area, and summon faction" : "not applicable after cleanup",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistenceControlValid,
                    "native summoned-unit control surfaces"),
                Assertion("expanded-summoning-publication-state",
                    _context.FeatureModules.Active.ExpandedSummoning ?
                        "681 exact required-parent references" :
                        "zero required-parent references",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistencePublicationValid,
                    "required base parents with always-registered identities"),
                Assertion(verifyCleanup || !writes ?
                        "expanded-summoning-cleaned" :
                        "expanded-summoning-prepared",
                    verifyCleanup ? "two lifecycle-expired, destroyed, detached KMG units" :
                        !writes ? "zero KMG units" :
                        "two active KMG units",
                    _expandedSummoningPersistenceDetail,
                    _expandedSummoningPersistenceCleanupValid,
                    verifyCleanup ? "native SummonedUnitBuff removal and disposal" :
                        !writes ? "fresh-load unit set" :
                        "pre-save active unit set"),
                Assertion("exact-working-save-write",
                    writes ? "one SaveRoutine on exact captured SaveInfo" :
                        "none during final verification",
                    "count=" + evidence.ExpectedWorkingSaveRoutineCount +
                        ";stashedAreas=" +
                        evidence.ExpectedWorkingStashedAreaCount +
                        ";unexpected=" + evidence.SaveWritingApiObserved,
                    writes ? evidence.ExpectedWorkingSaveRoutineCount == 1 &&
                        evidence.ExpectedWorkingStashedAreaCount >= 1 &&
                        !evidence.SaveWritingApiObserved :
                        evidence.ExpectedWorkingSaveRoutineCount == 0 &&
                        !evidence.SaveWritingApiObserved,
                    "request-scoped exact native save sentinel"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _context.ModEntry.Info.Version == _request.ExpectedModVersion,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            RuntimeTestResult result = CreateResult(status, assertions, null);
            result.WorkingSaveSmoke = evidence;
            if (!string.IsNullOrWhiteSpace(warning)) result.Warnings.Add(warning);
            Complete(result);
        }

        private void StartBrownFurPersistence()
        {
            UnitEntityData[] party = Game.Instance.Player.Party.Where(value =>
                value != null && value.Descriptor != null).ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before Brown-Fur persistence qualification.");

            CotwArcanistResolution resolution =
                BrownFurOptionalExtensionCoordinator.Current;
            BrownFurBlueprintSet blueprints =
                BrownFurOptionalExtensionCoordinator.Blueprints;
            if (resolution == null || !resolution.Decision.IsCompatible ||
                resolution.Contract == null || blueprints == null ||
                blueprints.Count != BrownFurIdentityCatalog.IdentityCount)
                throw new InvalidOperationException(
                    "Compatible registered Brown-Fur blueprints are unavailable for persistence qualification.");

            UnitEntityData caster = party[0];
            UnitEntityData subject = party[1];
            BlueprintAbility spell = ResourcesLibrary.TryGetBlueprint<
                BlueprintAbility>("4c3d08935262b6544ae97599b3a9556d");
            BlueprintBuff buffBlueprint = ResourcesLibrary.TryGetBlueprint<
                BlueprintBuff>("b175001b42b1a02479881b72fe132116");
            if (spell == null || buffBlueprint == null)
                throw new InvalidOperationException(
                    "The installed Bull's Strength spell/buff fixture is unavailable.");

            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveBrownFurPrepare;
            Buff[] buffs = subject.Descriptor.Buffs.RawFacts.OfType<Buff>()
                .Where(value => ReferenceEquals(value.Blueprint,
                    buffBlueprint)).ToArray();
            if (prepare)
            {
                if (buffs.Length != 0 || BrownFurPersistenceFeatureCount(
                    caster, blueprints) != 0)
                    throw new InvalidOperationException(
                        "The working save already contains the Brown-Fur persistence fixture; run verify/cleanup first.");
                if (caster.Descriptor.Resources.ContainsResource(
                    resolution.Contract.Reservoir))
                    throw new InvalidOperationException(
                        "The working-save persistence caster already owns the CotW reservoir fixture resource.");
                if (caster.Descriptor.AddFact(blueprints.PowerfulChange) == null ||
                    caster.Descriptor.AddFact(blueprints.ShareTransmutation) == null ||
                    caster.Descriptor.AddFact(
                        blueprints.TransmutationSupremacy) == null)
                    throw new InvalidOperationException(
                        "The Brown-Fur persistence features could not be granted.");
                caster.Descriptor.Resources.Add(
                    resolution.Contract.Reservoir, true);
                if (!caster.Descriptor.Resources.ContainsResource(
                        resolution.Contract.Reservoir) ||
                    caster.Descriptor.Resources.GetResourceAmount(
                        resolution.Contract.Reservoir) < 2)
                    throw new InvalidOperationException(
                        "The Brown-Fur persistence reservoir fixture could not be initialized.");
                ActivatableAbility wisdom =
                    BrownFurPlayerIntentRuntime.Find(caster.Descriptor,
                        blueprints.ScoreActivatables[4]);
                ActivatableAbility share =
                    BrownFurPlayerIntentRuntime.Find(caster.Descriptor,
                        blueprints.ShareTransmutationAbility);
                if (wisdom == null || share == null)
                    throw new InvalidOperationException(
                        "The Brown-Fur persistence toggles could not be resolved.");
                wisdom.IsOn = true;
                share.IsOn = true;

                var context = new MechanicsContext(caster, caster.Descriptor,
                    spell, null, new TargetWrapper(subject));
                context.Params.CasterLevel = 20;
                const string transaction = "working-save-brown-fur-persistence";
                try
                {
                    if (!BrownFurModifierAdjustmentRuntime.Begin(transaction,
                        context, caster, spell,
                        BrownFurAbilityScore.Strength, 2,
                        new[] { "b175001b42b1a02479881b72fe132116" },
                        new[] { "AddStatBonus" }))
                        throw new InvalidOperationException(
                            "The Brown-Fur persistence modifier scope was rejected.");
                    if (subject.Descriptor.Buffs.AddBuff(buffBlueprint, context,
                        TimeSpan.FromHours(5d)) == null)
                        throw new InvalidOperationException(
                            "The enhanced persistence buff could not be applied.");
                }
                finally
                {
                    BrownFurModifierAdjustmentRuntime.Release(transaction);
                }
                buffs = subject.Descriptor.Buffs.RawFacts.OfType<Buff>()
                    .Where(value => ReferenceEquals(value.Blueprint,
                        buffBlueprint)).ToArray();
            }

            BrownFurPlayerIntentDecision ownership =
                BrownFurPlayerIntentRuntime.Observe(caster.Descriptor,
                    blueprints);
            _brownFurPersistenceFeaturesValid = ownership.Valid &&
                ownership.HasPowerfulChange &&
                ownership.HasShareTransmutation &&
                ownership.HasTransmutationSupremacy &&
                BrownFurPersistenceFeatureCount(caster, blueprints) == 3;
            _brownFurPersistencePresentationValid =
                caster.Descriptor.Abilities.GetAbility(
                    blueprints.PowerfulChangeSelection) == null &&
                blueprints.ScoreActivatables.All(score =>
                    caster.Descriptor.ActivatableAbilities.Enumerable.Count(
                        value => value != null && ReferenceEquals(
                            value.Blueprint, score)) == 1) &&
                caster.Descriptor.ActivatableAbilities.Enumerable.Count(value =>
                    value != null && ReferenceEquals(value.Blueprint,
                         blueprints.ShareTransmutationAbility)) == 1;
            ActivatableAbility[] scoreStates = blueprints.ScoreActivatables
                .Select(value => BrownFurPlayerIntentRuntime.Find(
                    caster.Descriptor, value)).ToArray();
            ActivatableAbility persistedShare =
                BrownFurPlayerIntentRuntime.Find(caster.Descriptor,
                    blueprints.ShareTransmutationAbility);
            CotwArcanistContract contract = resolution.Contract;
            int persistedReservoir = caster.Descriptor.Resources
                .ContainsResource(contract.Reservoir) ?
                caster.Descriptor.Resources.GetResourceAmount(
                    contract.Reservoir) : 0;
            _brownFurPersistenceToggleStateValid =
                scoreStates.All(value => value != null) &&
                scoreStates.Count(value => value.IsOn) == 1 &&
                scoreStates[4].IsOn && persistedShare != null &&
                persistedShare.IsOn &&
                caster.Descriptor.HasFact(blueprints.ScoreBuffs[4]) &&
                !blueprints.ScoreBuffs.Where((value, index) => index != 4)
                    .Any(caster.Descriptor.HasFact) &&
                caster.Descriptor.HasFact(
                    blueprints.ShareTransmutationBuff) &&
                persistedReservoir >= 2;

            Buff buff = buffs.Length == 1 ? buffs[0] : null;
            ModifiableValue.Modifier[] modifiers = buff == null
                ? new ModifiableValue.Modifier[0]
                : subject.Descriptor.Stats.Strength.Modifiers.Where(value =>
                    ReferenceEquals(value.Source, buff)).ToArray();
            ModifiableValue.Modifier modifier = modifiers.Length == 1
                ? modifiers[0] : null;
            _brownFurPersistenceBuffValid = buff != null &&
                modifiers.Length == 1 && modifier.ModValue == 6 &&
                modifier.ModDescriptor == ModifierDescriptor.Enhancement &&
                buff.TimeLeft > TimeSpan.Zero;
            _brownFurPersistenceContextValid = buff != null &&
                buff.MaybeContext != null &&
                buff.MaybeContext.MaybeCaster == caster &&
                buff.MaybeContext.MainTarget.Unit == subject &&
                ReferenceEquals(buff.MaybeContext.SourceAbility, spell) &&
                buff.MaybeContext.Params.CasterLevel == 20;
            UnitPartBrownFurModifierPersistence persistencePart =
                subject.Descriptor.Get<
                    UnitPartBrownFurModifierPersistence>();
            int persistedBeforeCleanup = persistencePart == null ? 0 :
                persistencePart.Count;
            _brownFurPersistenceCarrierValid = persistedBeforeCleanup == 1;
            bool expectedActive = _request.Scenario != RuntimeTestScenarioCatalog
                .WorkingSaveBrownFurOffVerifyCleanup;
            int selectorReferences = contract.ArcanistClass.Archetypes == null ? 0 :
                contract.ArcanistClass.Archetypes.Count(value =>
                    ReferenceEquals(value, blueprints.Archetype));
            _brownFurPersistenceModuleStateValid =
                _context.FeatureModules.Active.BrownFurTransmuter ==
                    expectedActive &&
                BrownFurFeatureStatusRegistry.Current.Availability ==
                    BrownFurDependencyAvailability.Available &&
                BrownFurFeatureStatusRegistry.Current.Published ==
                    expectedActive &&
                selectorReferences == (expectedActive ? 1 : 0);

            if (!prepare)
            {
                if (buff != null) buff.Remove();
                BrownFurPlayerIntentRuntime.Clear(caster.Descriptor,
                    blueprints);
                RemoveBrownFurPersistenceFeatures(caster, blueprints);
                caster.Descriptor.Resources.Remove(contract.Reservoir);
                _brownFurPersistenceCleanupValid =
                    !subject.Descriptor.Buffs.RawFacts.OfType<Buff>().Any(
                        value => ReferenceEquals(value.Blueprint,
                            buffBlueprint)) &&
                    BrownFurPersistenceFeatureCount(caster, blueprints) == 0 &&
                    caster.Descriptor.Abilities.GetAbility(
                        blueprints.PowerfulChangeSelection) == null &&
                    !blueprints.ScoreActivatables.Any(score =>
                        caster.Descriptor.ActivatableAbilities.Enumerable.Any(
                            value => value != null && ReferenceEquals(
                                value.Blueprint, score))) &&
                    !caster.Descriptor.ActivatableAbilities.Enumerable.Any(
                        value => value != null && ReferenceEquals(
                            value.Blueprint,
                         blueprints.ShareTransmutationAbility)) &&
                    !blueprints.ScoreBuffs.Any(caster.Descriptor.HasFact) &&
                    !caster.Descriptor.HasFact(
                        blueprints.ShareTransmutationBuff) &&
                    !caster.Descriptor.Resources.ContainsResource(
                        contract.Reservoir) &&
                    persistencePart != null && persistencePart.Count == 0;
            }

            _brownFurPersistenceDetail = "phase=" +
                (prepare ? "prepare" : "verify-cleanup") + ";active=" +
                _context.FeatureModules.Active.BrownFurTransmuter +
                ";identities=" + blueprints.Count + ";features=" +
                _brownFurPersistenceFeaturesValid + ";presentation=" +
                _brownFurPersistencePresentationValid + ";toggleState=" +
                _brownFurPersistenceToggleStateValid + ";buffs=" +
                buffs.Length + ";modifier=" + (modifier == null ? "missing" :
                    modifier.ModValue + "/" + modifier.ModDescriptor) +
                ";timeLeftSeconds=" + (buff == null ? 0d :
                    buff.TimeLeft.TotalSeconds) + ";context=" +
                _brownFurPersistenceContextValid + ";cleanup=" +
                _brownFurPersistenceCleanupValid + ";persistedBefore=" +
                persistedBeforeCleanup + ";persistedAfter=" +
                (persistencePart == null ? 0 : persistencePart.Count) +
                ";expectedActive=" + expectedActive + ";selectorRefs=" +
                selectorReferences + ";moduleState=" +
                _brownFurPersistenceModuleStateValid + ";reservoir=" +
                persistedReservoir + ";scopes=" +
                BrownFurModifierAdjustmentRuntime.ActiveScopeCount;

            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Game).GetMethods(
                BindingFlags.Instance | BindingFlags.Public |
                BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" &&
                    value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _brownFurPersistenceSaveStarted = true;
            _brownFurPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() => _brownFurPersistenceSaveCompleted = true)
            });
        }

        private static int BrownFurPersistenceFeatureCount(
            UnitEntityData caster, BrownFurBlueprintSet blueprints)
        {
            return new[] { blueprints.PowerfulChange,
                blueprints.ShareTransmutation,
                blueprints.TransmutationSupremacy }.Count(value =>
                    caster.Descriptor.HasFact(value));
        }

        private static void RemoveBrownFurPersistenceFeatures(
            UnitEntityData caster, BrownFurBlueprintSet blueprints)
        {
            if (caster.Descriptor.HasFact(blueprints.TransmutationSupremacy))
                caster.Descriptor.RemoveFact(
                    blueprints.TransmutationSupremacy);
            if (caster.Descriptor.HasFact(blueprints.ShareTransmutation))
                caster.Descriptor.RemoveFact(blueprints.ShareTransmutation);
            if (caster.Descriptor.HasFact(blueprints.PowerfulChange))
                caster.Descriptor.RemoveFact(blueprints.PowerfulChange);
        }

        private void CompleteBrownFurPersistence(string status,
            string warning)
        {
            WorkingSaveSmokeEvidence evidence = _workingSaveSmoke.Stop();
            bool verify = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveBrownFurVerifyCleanup ||
                _request.Scenario == RuntimeTestScenarioCatalog
                    .WorkingSaveBrownFurOffVerifyCleanup;
            bool phaseValid = _brownFurPersistenceModuleStateValid &&
                _brownFurPersistenceFeaturesValid &&
                _brownFurPersistencePresentationValid &&
                _brownFurPersistenceToggleStateValid &&
                _brownFurPersistenceBuffValid &&
                _brownFurPersistenceContextValid &&
                _brownFurPersistenceCarrierValid &&
                (!verify || _brownFurPersistenceCleanupValid) &&
                BrownFurModifierAdjustmentRuntime.ActiveScopeCount == 0;
            if (status == RuntimeTestStatuses.Pass && !phaseValid)
                status = RuntimeTestStatuses.Fail;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("exact-working-load",
                    "one correlated working descriptor; baseline distinct",
                    "working=" + evidence.WorkingMatchCount + ";baseline=" +
                        evidence.BaselineMatchCount + ";correlated=" +
                        evidence.DescriptorReferenceCorrelated,
                    evidence.WorkingMatchCount == 1 &&
                        evidence.BaselineMatchCount == 1 &&
                        evidence.DescriptorReferenceCorrelated,
                    "object-reference-correlated guarded load path"),
                Assertion("brown-fur-persistence-features",
                    "all three stable features owned",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceFeaturesValid,
                    verify ? "freshly deserialized registered feature facts" :
                        "pre-save registered feature facts"),
                Assertion("brown-fur-persistence-presentation",
                    "six score activatables and one Share activatable; no legacy selector",
                    _brownFurPersistenceDetail,
                    _brownFurPersistencePresentationValid,
                    verify ? "freshly deserialized AddFacts grants" :
                        "pre-save AddFacts grants"),
                Assertion("brown-fur-persistence-toggle-state",
                    "exactly Wisdom and Share remain synchronized ON across save/load",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceToggleStateValid,
                    verify ? "freshly deserialized native IsOn states and marker buffs" :
                        "pre-save native IsOn states and marker buffs"),
                Assertion("brown-fur-persistence-enhanced-buff",
                    "one +6 Enhancement Bull's Strength with positive duration",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceBuffValid,
                    verify ? "freshly deserialized native stat modifier" :
                        "pre-save native stat modifier"),
                Assertion("brown-fur-persistence-context",
                    "caster=party[0];target=party[1];spell exact;CL=20",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceContextValid,
                    verify ? "freshly deserialized buff MechanicsContext" :
                        "pre-save buff MechanicsContext"),
                Assertion("brown-fur-persistence-owner-record",
                    "one exact target-owned adjustment record before cleanup",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceCarrierValid,
                    verify ? "freshly deserialized UnitPart record" :
                        "pre-save UnitPart record"),
                Assertion("brown-fur-persistence-module-state",
                    _request.Scenario == RuntimeTestScenarioCatalog
                        .WorkingSaveBrownFurOffVerifyCleanup ?
                        "saved OFF; dependency available; selector hidden" :
                        "saved ON; dependency available; selector published",
                    _brownFurPersistenceDetail,
                    _brownFurPersistenceModuleStateValid,
                    "immutable active settings, effective dependency status, and exact Arcanist archetype array"),
                Assertion("brown-fur-persistence-cleanup",
                    verify ? "features, grants, and buff absent before cleanup save" :
                        "not-applicable",
                    verify ? _brownFurPersistenceCleanupValid.ToString() :
                        "not-applicable",
                    !verify || _brownFurPersistenceCleanupValid,
                    "exact working-save fixture cleanup"),
                Assertion("brown-fur-persistence-scope-cleanup", "zero",
                    BrownFurModifierAdjustmentRuntime.ActiveScopeCount.ToString(),
                    BrownFurModifierAdjustmentRuntime.ActiveScopeCount == 0,
                    "execution-local modifier scope tracker"),
                Assertion("exact-working-save-write",
                    "one SaveRoutine on exact captured SaveInfo",
                    "count=" + evidence.ExpectedWorkingSaveRoutineCount +
                        ";stashedAreas=" +
                        evidence.ExpectedWorkingStashedAreaCount +
                        ";unexpected=" + evidence.SaveWritingApiObserved,
                    evidence.ExpectedWorkingSaveRoutineCount == 1 &&
                        evidence.ExpectedWorkingStashedAreaCount >= 1 &&
                        !evidence.SaveWritingApiObserved,
                    "request-scoped exact native save sentinel"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _context.ModEntry.Info.Version ==
                        _request.ExpectedModVersion,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            RuntimeTestResult result = CreateResult(status, assertions, null);
            result.WorkingSaveSmoke = evidence;
            result.Diagnostics.Add(_brownFurPersistenceDetail);
            if (!string.IsNullOrWhiteSpace(warning))
                result.Warnings.Add(warning);
            Complete(result);
        }

        private void StartUrbanBarbarianPersistence()
        {
            UnitEntityData[] party = Game.Instance.Player.Party.Where(value =>
                value != null && value.Descriptor != null).ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before Urban Barbarian persistence qualification.");
            UrbanBarbarianBlueprintSet set = BlueprintBootstrap.UrbanBarbarian;
            UnitEntityData owner = party[0];
            BlueprintFeature nativeRage = ResourcesLibrary.TryGetBlueprint<
                BlueprintFeature>("2479395977cfeeb46b482bc3385f4647");
            if (set == null || set.Count !=
                    UrbanBarbarianIdentityCatalog.IdentityCount ||
                nativeRage == null)
                throw new InvalidOperationException(
                    "The complete registered Urban Barbarian persistence graph is unavailable.");
            bool prepare = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveUrbanBarbarianPrepare;
            BlueprintFeature[] fixtureFeatures = { nativeRage,
                set.Proficiency, set.CrowdControl, set.ControlledRage };
            if (prepare)
            {
                if (fixtureFeatures.Any(owner.Descriptor.HasFact) ||
                    set.SelectionFacts.Any(owner.Descriptor.HasFact) ||
                    set.TierSelectors.Any(owner.Descriptor.HasFact) ||
                    owner.Descriptor.HasFact(set.LegacySelector) ||
                    owner.Descriptor.Get<UnitPartControlledRageSelection>() != null ||
                    owner.Descriptor.HasFact(set.RageBuff) ||
                    owner.Descriptor.HasFact(set.NativeRageBuff))
                    throw new InvalidOperationException(
                        "The working save already contains the Urban Barbarian persistence fixture; run verify/cleanup first.");
                foreach (BlueprintFeature feature in fixtureFeatures)
                    if (owner.Descriptor.AddFact(feature) == null)
                        throw new InvalidOperationException(
                            "An Urban Barbarian persistence feature could not be granted: " + feature.name);
                ControlledRageAllocation con =
                    ControlledRageAllocationPolicy.Generate(
                        ControlledRageTier.Ordinary).Single(value =>
                            value.Strength == 0 && value.Dexterity == 0 &&
                            value.Constitution == 4);
                if (!ControlledRageRuntime.TrySelect(owner.Descriptor, con))
                    throw new InvalidOperationException(
                        "The Urban Barbarian persisted CON +4 allocation could not be selected.");
                var context = new MechanicsContext(owner, owner.Descriptor,
                    set.ControlledRage, null, new TargetWrapper(owner));
                Buff rage = owner.Descriptor.Buffs.AddBuff(
                    set.NativeRageBuff, context, null);
                if (rage == null || !ReferenceEquals(rage.Blueprint,
                        set.RageBuff))
                    throw new InvalidOperationException(
                        "The active Urban Rage persistence fixture did not substitute owner-scoped Rage.");
            }

            ControlledRageAllocation selection =
                ControlledRageRuntime.ResolveSelection(owner.Descriptor, false);
            UnitPartControlledRageSelection selectionPart = owner.Descriptor.Get<
                UnitPartControlledRageSelection>();
            Buff[] urbanRages = owner.Descriptor.Buffs.RawFacts.OfType<Buff>()
                .Where(value => ReferenceEquals(value.Blueprint,
                    set.RageBuff)).ToArray();
            Buff persistedRage = urbanRages.Length == 1 ? urbanRages[0] : null;
            ModifiableValue.Modifier[] constitutionModifiers = persistedRage ==
                null ? new ModifiableValue.Modifier[0] : owner.Descriptor.Stats
                    .Constitution.Modifiers.Where(value => ReferenceEquals(
                        value.Source, persistedRage)).ToArray();
            _urbanBarbarianPersistenceFactsValid = fixtureFeatures.All(
                owner.Descriptor.HasFact) &&
                owner.Descriptor.Abilities.GetAbility(set.OrdinarySelector) !=
                    null && owner.Descriptor.Abilities.GetAbility(
                        set.LegacySelector) == null &&
                owner.Descriptor.Abilities.GetAbility(set.GreaterSelector) ==
                    null && owner.Descriptor.Abilities.GetAbility(
                        set.MightySelector) == null;
            _urbanBarbarianPersistenceSelectionValid = selection != null &&
                selection.Strength == 0 && selection.Dexterity == 0 &&
                selection.Constitution == 4 &&
                selectionPart != null && Equals(selectionPart.SelectionFor(
                    ControlledRageTier.Ordinary), selection) &&
                set.SelectionFacts.Count(owner.Descriptor.HasFact) == 1;
            _urbanBarbarianPersistenceRageValid = persistedRage != null &&
                !owner.Descriptor.HasFact(set.NativeRageBuff) &&
                constitutionModifiers.Length == 1 &&
                constitutionModifiers[0].ModValue == 4 &&
                constitutionModifiers[0].ModDescriptor ==
                    ModifierDescriptor.Morale &&
                !owner.Descriptor.Stats.Strength.Modifiers.Any(value =>
                    ReferenceEquals(value.Source, persistedRage)) &&
                !owner.Descriptor.Stats.Dexterity.Modifiers.Any(value =>
                    ReferenceEquals(value.Source, persistedRage)) &&
                !owner.Descriptor.Stats.TemporaryHitPoints.Modifiers.Any(value =>
                    ReferenceEquals(value.Source, persistedRage));
            bool expectedActive = prepare;
            BlueprintArchetype[] archetypes = set.BarbarianClass.Archetypes ??
                Array.Empty<BlueprintArchetype>();
            int archetypeReferences = archetypes.Count(value =>
                ReferenceEquals(value, set.Archetype));
            int archetypeGuids = archetypes.Count(value => value != null &&
                string.Equals(value.AssetGuid, set.Archetype.AssetGuid,
                    StringComparison.Ordinal));
            _urbanBarbarianPersistenceModuleStateValid =
                _context.FeatureModules.Active.UrbanBarbarian == expectedActive &&
                archetypeReferences == (expectedActive ? 1 : 0) &&
                archetypeGuids == (expectedActive ? 1 : 0) &&
                set.Count == UrbanBarbarianIdentityCatalog.IdentityCount;

            string cleanupDetail = "not-applicable";
            if (!prepare)
            {
                if (owner.Descriptor.HasFact(set.RageBuff))
                    owner.Descriptor.RemoveFact(set.RageBuff);
                if (owner.Descriptor.HasFact(set.NativeRageBuff))
                    owner.Descriptor.RemoveFact(set.NativeRageBuff);
                foreach (BlueprintFeature feature in set.SelectionFacts)
                    if (owner.Descriptor.HasFact(feature))
                        owner.Descriptor.RemoveFact(feature);
                foreach (BlueprintFeature feature in fixtureFeatures.Reverse())
                    if (owner.Descriptor.HasFact(feature))
                        owner.Descriptor.RemoveFact(feature);
                foreach (BlueprintAbility selector in set.TierSelectors)
                    if (owner.Descriptor.Abilities.GetAbility(selector) != null)
                        owner.Descriptor.RemoveFact(selector);
                if (owner.Descriptor.Abilities.GetAbility(
                        set.LegacySelector) != null)
                    owner.Descriptor.RemoveFact(set.LegacySelector);
                foreach (BlueprintFeature feature in set.SelectionFacts)
                    if (owner.Descriptor.HasFact(feature))
                        owner.Descriptor.RemoveFact(feature);
                owner.Descriptor.Remove<UnitPartControlledRageSelection>();
                bool featuresAbsent = !fixtureFeatures.Any(
                    owner.Descriptor.HasFact);
                bool selectionsAbsent = !set.SelectionFacts.Any(
                    owner.Descriptor.HasFact);
                bool partAbsent = owner.Descriptor.Get<
                    UnitPartControlledRageSelection>() == null;
                bool selectorAbsent = set.TierSelectors.All(value =>
                    owner.Descriptor.Abilities.GetAbility(value) == null) &&
                    owner.Descriptor.Abilities.GetAbility(
                        set.LegacySelector) == null;
                bool urbanRageAbsent = !owner.Descriptor.HasFact(set.RageBuff);
                bool nativeRageAbsent = !owner.Descriptor.HasFact(
                    set.NativeRageBuff);
                _urbanBarbarianPersistenceCleanupValid = featuresAbsent &&
                    selectionsAbsent && partAbsent && selectorAbsent &&
                    urbanRageAbsent && nativeRageAbsent;
                cleanupDetail = "features=" + featuresAbsent +
                    ";selections=" + selectionsAbsent + ";part=" +
                    partAbsent + ";selector=" + selectorAbsent +
                    ";urbanRage=" + urbanRageAbsent + ";nativeRage=" +
                    nativeRageAbsent;
            }

            _urbanBarbarianPersistenceDetail = "phase=" +
                (prepare ? "prepare" : "off-verify-cleanup") +
                ";active=" + _context.FeatureModules.Active.UrbanBarbarian +
                ";identities=" + set.Count + ";archetypeRefs=" +
                archetypeReferences + ";archetypeGuids=" + archetypeGuids +
                ";facts=" + _urbanBarbarianPersistenceFactsValid +
                ";selection=" + (selection == null ? "missing" :
                    selection.ToString()) + ";rageCount=" + urbanRages.Length +
                ";selectionPart=" + (selectionPart != null) +
                ";conModifiers=" + constitutionModifiers.Length +
                ";rage=" + _urbanBarbarianPersistenceRageValid +
                ";module=" + _urbanBarbarianPersistenceModuleStateValid +
                ";cleanup=" + _urbanBarbarianPersistenceCleanupValid +
                ";cleanupDetail=" + cleanupDetail;

            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Game).GetMethods(
                BindingFlags.Instance | BindingFlags.Public |
                BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" && value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _urbanBarbarianPersistenceSaveStarted = true;
            _urbanBarbarianPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() =>
                    _urbanBarbarianPersistenceSaveCompleted = true)
            });
        }

        private void CompleteUrbanBarbarianPersistence(string status,
            string warning)
        {
            WorkingSaveSmokeEvidence evidence = _workingSaveSmoke.Stop();
            bool verify = _request.Scenario == RuntimeTestScenarioCatalog
                .WorkingSaveUrbanBarbarianOffVerifyCleanup;
            bool phaseValid = _urbanBarbarianPersistenceFactsValid &&
                _urbanBarbarianPersistenceSelectionValid &&
                _urbanBarbarianPersistenceRageValid &&
                _urbanBarbarianPersistenceModuleStateValid &&
                (!verify || _urbanBarbarianPersistenceCleanupValid);
            if (status == RuntimeTestStatuses.Pass && !phaseValid)
                status = RuntimeTestStatuses.Fail;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("exact-working-load",
                    "one correlated working descriptor; baseline distinct",
                    "working=" + evidence.WorkingMatchCount + ";baseline=" +
                        evidence.BaselineMatchCount + ";correlated=" +
                        evidence.DescriptorReferenceCorrelated,
                    evidence.WorkingMatchCount == 1 &&
                        evidence.BaselineMatchCount == 1 &&
                        evidence.DescriptorReferenceCorrelated,
                    "object-reference-correlated guarded load path"),
                Assertion("urban-persistence-features",
                    "native Rage and all three level-1 Urban features remain owned",
                    _urbanBarbarianPersistenceDetail,
                    _urbanBarbarianPersistenceFactsValid,
                    verify ? "freshly deserialized registered facts" :
                        "pre-save registered facts"),
                Assertion("urban-persistence-selection",
                    "exactly one ordinary CON +4 allocation remains selected",
                    _urbanBarbarianPersistenceDetail,
                    _urbanBarbarianPersistenceSelectionValid,
                    verify ? "freshly deserialized selection fact" :
                        "pre-save selection fact"),
                Assertion("urban-persistence-active-rage",
                    "one substituted Urban Rage buff retains one +4 morale Constitution modifier and no native or temporary-HP fact",
                    _urbanBarbarianPersistenceDetail,
                    _urbanBarbarianPersistenceRageValid,
                    verify ? "freshly deserialized active buff and stat modifier" :
                        "pre-save active buff and stat modifier"),
                Assertion("urban-persistence-module-off",
                    verify ? "module OFF, archetype hidden, 73 identities and owner facts retained" :
                        "module ON, archetype published once, 73 identities retained",
                    _urbanBarbarianPersistenceDetail,
                    _urbanBarbarianPersistenceModuleStateValid,
                    "immutable active setting and exact native Barbarian archetype array"),
                Assertion("urban-persistence-cleanup",
                    verify ? "all request-local Urban facts and active buffs removed before cleanup save" :
                        "not-applicable",
                    verify ? _urbanBarbarianPersistenceDetail :
                        "not-applicable",
                    !verify || _urbanBarbarianPersistenceCleanupValid,
                    "exact working-save fixture cleanup"),
                Assertion("exact-working-save-write",
                    "one SaveRoutine on exact captured SaveInfo",
                    "count=" + evidence.ExpectedWorkingSaveRoutineCount +
                        ";stashedAreas=" +
                        evidence.ExpectedWorkingStashedAreaCount +
                        ";unexpected=" + evidence.SaveWritingApiObserved,
                    evidence.ExpectedWorkingSaveRoutineCount == 1 &&
                        evidence.ExpectedWorkingStashedAreaCount >= 1 &&
                        !evidence.SaveWritingApiObserved,
                    "request-scoped exact native save sentinel"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _context.ModEntry.Info.Version == _request.ExpectedModVersion,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            RuntimeTestResult result = CreateResult(status, assertions, null);
            result.WorkingSaveSmoke = evidence;
            result.Diagnostics.Add(_urbanBarbarianPersistenceDetail);
            if (!string.IsNullOrWhiteSpace(warning))
                result.Warnings.Add(warning);
            Complete(result);
        }

        private void StartShieldOtherPersistenceSave()
        {
            UnitEntityData[] party = Kingmaker.Game.Instance.Player.Party
                .Where(value => value != null && value.Descriptor != null)
                .ToArray();
            if (party.Length != WorkingSaveSmokeScenario.ExpectedPartyCount)
                throw new InvalidOperationException(
                    "The loaded working-save party fingerprint changed before persistence qualification.");
            UnitEntityData caster = party[0];
            UnitEntityData subject = party[1];
            Buff[] links = subject.Descriptor.Buffs.RawFacts.OfType<Buff>()
                .Where(value => ReferenceEquals(value.Blueprint,
                    BlueprintBootstrap.ShieldOther.TargetBuff)).ToArray();
            if (_request.Scenario ==
                RuntimeTestScenarioCatalog.WorkingSaveShieldOtherPrepare)
            {
                foreach (Buff existing in links) existing.Remove();
                var context = new MechanicsContext(caster, caster.Descriptor,
                    BlueprintBootstrap.ShieldOther.Ability, null,
                    new TargetWrapper(subject));
                context.Params.CasterLevel = 5;
                Buff link = subject.Descriptor.Buffs.AddBuff(
                    BlueprintBootstrap.ShieldOther.TargetBuff, context,
                    TimeSpan.FromHours(5d));
                _shieldOtherPersistenceContextValid = link != null &&
                    link.MaybeContext != null &&
                    link.MaybeContext.MaybeCaster == caster &&
                    link.MaybeContext.Params.CasterLevel == 5 &&
                    link.MaybeContext.MainTarget.Unit == subject;
                _shieldOtherPersistenceLinkStateValid =
                    subject.Descriptor.Buffs.RawFacts.OfType<Buff>().Count(value =>
                        ReferenceEquals(value.Blueprint,
                            BlueprintBootstrap.ShieldOther.TargetBuff)) == 1;
            }
            else
            {
                _shieldOtherPersistenceLinkStateValid = links.Length == 1;
                Buff link = links.Length == 1 ? links[0] : null;
                _shieldOtherPersistenceContextValid = link != null &&
                    link.MaybeContext != null &&
                    link.MaybeContext.MaybeCaster == caster &&
                    link.MaybeContext.Params.CasterLevel == 5 &&
                    link.MaybeContext.MainTarget.Unit == subject;
                int casterDamage = caster.Descriptor.Damage;
                int subjectDamage = subject.Descriptor.Damage;
                int casterBefore = caster.HPLeft;
                int subjectBefore = subject.HPLeft;
                Rulebook.Trigger(new RuleDealDamage(caster, subject,
                    new DamageBundle(new DirectDamage(
                        new DiceFormula(0, DiceType.D6), 3)))
                    {
                        DisablePrecisionDamage = true,
                        IgnoreDamageReduction = true
                    });
                _shieldOtherPersistenceDamageValid =
                    subjectBefore - subject.HPLeft == 1 &&
                    casterBefore - caster.HPLeft == 2;
                caster.Descriptor.Damage = casterDamage;
                subject.Descriptor.Damage = subjectDamage;
                if (link != null) link.Remove();
                _shieldOtherPersistenceLinkStateValid =
                    _shieldOtherPersistenceLinkStateValid &&
                    !subject.Descriptor.HasFact(
                        BlueprintBootstrap.ShieldOther.TargetBuff);
            }
            if (!_shieldOtherPersistenceContextValid ||
                !_shieldOtherPersistenceLinkStateValid ||
                (_request.Scenario ==
                    RuntimeTestScenarioCatalog.WorkingSaveShieldOtherVerifyCleanup &&
                 !_shieldOtherPersistenceDamageValid))
                throw new InvalidOperationException(
                    "Shield Other persistence phase assertions failed before the guarded save.");

            _workingSaveSmoke.ArmExactWorkingSaveWrite();
            MethodInfo saveGame = typeof(Kingmaker.Game).GetMethods(
                BindingFlags.Instance | BindingFlags.Public |
                BindingFlags.NonPublic).Single(value =>
                    value.Name == "SaveGame" &&
                    value.ReturnType == typeof(void) &&
                    value.GetParameters().Length == 2 &&
                    value.GetParameters()[0].ParameterType.FullName ==
                        "Kingmaker.EntitySystem.Persistence.SaveInfo" &&
                    value.GetParameters()[1].ParameterType == typeof(Action));
            _shieldOtherPersistenceSaveStarted = true;
            _shieldOtherPersistenceSaveElapsed = Stopwatch.StartNew();
            saveGame.Invoke(Kingmaker.Game.Instance, new object[]
            {
                _workingSaveSmoke.WorkingDescriptor,
                new Action(() => _shieldOtherPersistenceSaveCompleted = true)
            });
        }

