        }

        private RuntimeTestResult RunModLoadSmoke()
        {
            Assembly assembly = _context.Assembly;
            string expectedVersion = _request.ExpectedModVersion;
            string observedVersion = _context.ModEntry.Info.Version;
            string runtimeIdentity = assembly.FullName +
                "; pid=" + Process.GetCurrentProcess().Id;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion(
                    "loaded-mod-version",
                    expectedVersion,
                    observedVersion,
                    string.Equals(expectedVersion, observedVersion, StringComparison.Ordinal),
                    "Unity Mod Manager ModEntry.Info.Version"),
                Assertion(
                    "runtime-identity",
                    "executing KingmakerGunslinger assembly in current process",
                    runtimeIdentity,
                    assembly == Assembly.GetExecutingAssembly() &&
                        assembly.GetName().Name == "KingmakerGunslinger",
                    "ModContext.Assembly and Process.GetCurrentProcess().Id"),
                Assertion(
                    "core-initialization",
                    "published context with Harmony patches installed",
                    _context.IsReady ? "ready" : "not-ready",
                    _context.IsReady,
                    "ModContext.IsReady")
            };
            bool pass = assertions.TrueForAll(value => value.Status == "PASS");
            RuntimeTestResult result = CreateResult(pass ? "PASS" : "FAIL", assertions, null);
            result.RuntimeIdentity = runtimeIdentity;
            return result;
        }

        private RuntimeTestResult RunFirearmWwiseAudio()
        {
            int before=Audio.FirearmSoundRuntime.AcceptedPosts;
            Audio.FirearmSoundPostResult preview=Audio.FirearmSoundRuntime.TryPostGlobalPistolPreview();
            int afterGlobal=Audio.FirearmSoundRuntime.AcceptedPosts;
            string globalDiagnostics=Audio.FirearmSoundRuntime.Describe();
            BlueprintUnit source=BlueprintRoot.Instance.DefaultPlayerCharacter;
            object state=ReadExactMember(Kingmaker.Game.Instance,"State");
            object allUnits=ReadExactMember(state,"AllUnits");
            object[] unitsBefore=SnapshotReferences(allUnits);
            Kingmaker.EntitySystem.Entities.UnitEntityData attacker=null;
            Kingmaker.EntitySystem.Entities.UnitEntityData target=null;
            Kingmaker.EntitySystem.SceneEntitiesState disposableScene=null;
            ItemEntityWeapon weapon=null;
            Audio.FirearmSoundPostResult selectedPreview=null;
            int afterSelected=-1,afterOrdinary=-1,afterMisfire=-1;
            uint ordinaryPlayingId=0;
            string selectedDiagnostics="<not-run>",ordinaryDiagnostics="<not-run>",
                misfireDiagnostics="<not-run>", ordinaryMisfireDiagnostics="<not-run>",
                forcedMisfireDiagnostics="<not-run>";
            bool cleaned=false;
            try
            {
                disposableScene=new Kingmaker.EntitySystem.SceneEntitiesState(
                    "KMG_Firearm_Wwise_Audio_Fixture");
                attacker=Kingmaker.Game.Instance.EntityCreator.SpawnUnit(
                    source,Vector3.zero,Quaternion.identity,disposableScene);
                target=Kingmaker.Game.Instance.EntityCreator.SpawnUnit(
                    source,new Vector3(1f,0f,0f),Quaternion.identity,disposableScene);
                if(attacker==null||attacker.View==null||target==null||target.View==null)
                    throw new InvalidOperationException("Native entity creation did not produce live unit views.");
                weapon=new ItemEntityWeapon(BlueprintBootstrap.ProductionFirearms.Blunderbuss.Item);
                attacker.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon,new FirearmState(
                    FirearmState.CurrentSchemaVersion,1,
                    FirearmStateTokenCatalog.DiagnosticLeadBall,FirearmCondition.Normal));

                selectedPreview=Audio.FirearmSoundRuntime.TryPostCommittedDischarge(
                    FirearmKind.Blunderbuss,attacker,"development-selected-preview");
                afterSelected=Audio.FirearmSoundRuntime.AcceptedPosts;
                selectedDiagnostics=Audio.FirearmSoundRuntime.Describe();

                FirearmMisfireRuntime.QueueForcedNaturalRoll(19);
                Rulebook.Trigger(new RuleAttackWithWeapon(attacker,target,weapon,0));
                afterOrdinary=Audio.FirearmSoundRuntime.AcceptedPosts;
                ordinaryPlayingId=Audio.FirearmSoundRuntime.LastPlayingId;
                ordinaryDiagnostics=Audio.FirearmSoundRuntime.Describe();
                ordinaryMisfireDiagnostics=FirearmMisfireRuntime.Describe();

                FirearmRuntimeState.Service.Set(weapon,new FirearmState(
                    FirearmState.CurrentSchemaVersion,1,
                    FirearmStateTokenCatalog.DiagnosticLeadBall,FirearmCondition.Normal));
                FirearmMisfireRuntime.QueueForcedNaturalRoll(1);
                Rulebook.Trigger(new RuleAttackWithWeapon(attacker,target,weapon,0));
                afterMisfire=Audio.FirearmSoundRuntime.AcceptedPosts;
                misfireDiagnostics=Audio.FirearmSoundRuntime.Describe();
                forcedMisfireDiagnostics=FirearmMisfireRuntime.Describe();
            }
            finally
            {
                FirearmMisfireRuntime.CancelForcedNaturalRoll();
                if(weapon!=null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if(attacker!=null&&attacker.Body.PrimaryHand.MaybeItem!=null)
                        attacker.Body.PrimaryHand.RemoveItem(false);
                    weapon.Dispose();
                }
                if(target!=null)target.Dispose();
                if(attacker!=null)attacker.Dispose();
                if(disposableScene!=null)disposableScene.Dispose();
                cleaned=SameReferences(unitsBefore,SnapshotReferences(allUnits))&&
                    (attacker==null||!ContainsReference(allUnits,attacker))&&
                    (target==null||!ContainsReference(allUnits,target));
            }
            var assertions=new List<RuntimeTestAssertion>
            {
                Assertion("firearm-wwise-ready","state=Ready",globalDiagnostics,globalDiagnostics.Contains("state=Ready"),"FirearmSoundRuntime state machine"),
                Assertion("global-pistol-event-accepted","one valid nonzero playing ID",globalDiagnostics,preview.Accepted&&preview.PlayingId!=0&&afterGlobal==before+1&&preview.EventName==Audio.FirearmSoundEventCatalog.Resolve(FirearmKind.Pistol),"AkSoundEngine.PostEvent global technical preview"),
                Assertion("unit-emitter-blunderbuss-event-accepted","one valid nonzero playing ID from live disposable unit view",selectedDiagnostics,selectedPreview!=null&&selectedPreview.Accepted&&selectedPreview.PlayingId!=0&&afterSelected==afterGlobal+1&&selectedPreview.EventName==Audio.FirearmSoundEventCatalog.Resolve(FirearmKind.Blunderbuss)&&selectedPreview.Source=="development-selected-preview","AkSoundEngine.PostEvent live unit emitter preview"),
                Assertion("ordinary-discharge-event-accepted","accepted count +1; exact Blunderbuss event; ordinary-attack",ordinaryDiagnostics,afterOrdinary==afterSelected+1&&ordinaryPlayingId!=0&&Audio.FirearmSoundEventCatalog.Resolve(FirearmKind.Blunderbuss)==Audio.FirearmSoundRuntime.LastEventName&&ordinaryDiagnostics.Contains("lastSource=ordinary-attack"),"RuleAttackWithWeapon committed non-misfire discharge"),
                Assertion("blunderbuss-misfire-no-normal-event","accepted count unchanged; live misfire available for inherited-release listening",misfireDiagnostics,afterMisfire==afterOrdinary,"forced Blunderbuss natural 1 through RuleAttackWithWeapon"),
                Assertion("save-free-audio-scenario","no save/inventory mutation and detached fixtures cleaned","cleaned="+cleaned,cleaned,"disposable SceneEntitiesState and exact global-unit snapshot")
            };
            bool pass=assertions.TrueForAll(value=>value.Status=="PASS");
            RuntimeTestResult result=CreateResult(pass?"PASS":"FAIL",assertions,null);
            result.Diagnostics.Add(globalDiagnostics);
            result.Diagnostics.Add(selectedDiagnostics);
            result.Diagnostics.Add(ordinaryDiagnostics);
            result.Diagnostics.Add(ordinaryMisfireDiagnostics);
            result.Diagnostics.Add(misfireDiagnostics);
            result.Diagnostics.Add(forcedMisfireDiagnostics);
            result.Warnings.Add("A valid Wwise playing ID proves event acceptance, not audible speaker output.");
            return result;
        }

        private RuntimeTestResult RunGunslingerPresentationObservation()
        {
            GunslingerClassBlueprintSet set = BlueprintBootstrap.GunslingerClass;
            BlueprintCharacterClass characterClass = set.CharacterClass;
            BlueprintProgression progression = set.Progression;
            var visited = new HashSet<BlueprintUnitFact>();
            var pending = new Stack<BlueprintUnitFact>();
            foreach (LevelEntry entry in progression.LevelEntries)
                foreach (BlueprintFeatureBase feature in entry.Features)
                    if (feature != null) pending.Push(feature);
            int visible = 0, hidden = 0, incomplete = 0, tooltipIncomplete = 0;
            while (pending.Count > 0)
            {
                BlueprintUnitFact fact = pending.Pop();
                if (fact == null || !visited.Add(fact)) continue;
                var feature = fact as BlueprintFeature;
                var ability = fact as BlueprintAbility;
                bool isHidden = (feature != null && feature.HideInUI) ||
                    (ability != null && ability.Hidden);
                bool project = fact.name != null && fact.name.StartsWith("KMG_",
                    StringComparison.Ordinal);
                if (project && isHidden) hidden++;
                if (project && !isHidden)
                {
                    visible++;
                    if (string.IsNullOrWhiteSpace(fact.Name) ||
                        string.IsNullOrWhiteSpace(fact.Description) ||
                        fact.Icon == null) incomplete++;
                    if (ability != null &&
                        (ability.LocalizedDuration == null ||
                         ability.LocalizedSavingThrow == null ||
                         string.IsNullOrWhiteSpace(ability.LocalizedDuration.ToString()) ||
                         string.IsNullOrWhiteSpace(ability.LocalizedSavingThrow.ToString()) ||
                         ability.LocalizedDuration.ToString().IndexOf("<null>",
                             StringComparison.OrdinalIgnoreCase) >= 0 ||
                         ability.LocalizedSavingThrow.ToString().IndexOf("<null>",
                             StringComparison.OrdinalIgnoreCase) >= 0))
                        tooltipIncomplete++;
                }
                var selection = fact as BlueprintFeatureSelection;
                if (selection != null && selection.AllFeatures != null)
                    foreach (BlueprintFeature child in selection.AllFeatures)
                        if (child != null) pending.Push(child);
                if (fact.ComponentsArray == null) continue;
                foreach (AddFacts grant in fact.ComponentsArray.OfType<AddFacts>())
                    if (grant.Facts != null)
                        foreach (BlueprintUnitFact child in grant.Facts)
                            if (child != null) pending.Push(child);
            }
            bool classMetadata = !string.IsNullOrWhiteSpace(characterClass.Name) &&
                !string.IsNullOrWhiteSpace(characterClass.Description) &&
                characterClass.Icon != null;
            bool progressionMetadata = !string.IsNullOrWhiteSpace(progression.Name) &&
                !string.IsNullOrWhiteSpace(progression.Description) &&
                progression.Icon != null;
            BlueprintFeature deedPackage = progression.LevelEntries
                .SelectMany(entry => entry.Features)
                .OfType<BlueprintFeature>()
                .FirstOrDefault(value => value.name != null &&
                    value.name.IndexOf("Deed", StringComparison.OrdinalIgnoreCase) >= 0 &&
                    !value.HideInUI);
            BlueprintUnitFact[] semanticFacts = {
                set.Proficiencies, set.Gunsmithing, set.Grit.Feature,
                deedPackage, set.Nimble.Features[0], set.GunTraining.Selection,
                set.TrueGrit.Selection, set.QuickClear.Feature,
                BlueprintBootstrap.ReloadTestMusketAbility,
                BlueprintBootstrap.RepairTestMusketAbility,
                BlueprintBootstrap.OverhaulTestMusketAbility };
            int semanticIconCount = semanticFacts.Where(value => value != null &&
                    value.Icon != null).Select(value => value.Icon).Distinct().Count();
            string semanticMap = string.Join("|", semanticFacts.Select(value =>
                value == null ? "<missing>" : value.name + "=" +
                    (value.Icon == null ? "<null>" : value.Icon.name)).ToArray());

            BlueprintFeatureSelection rapidReload =
                BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                    BlueprintBootstrap.Library,
                    "85103137b2f54b7dacd98d51e856d8c3", "Rapid Reload selection");
            BlueprintFeature[] rapidChoices = rapidReload.AllFeatures ??
                Array.Empty<BlueprintFeature>();
            BlueprintFeatureSelection basicFeats =
                BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                    BlueprintBootstrap.Library,
                    "247a4068296e8be42890143f451b4b45", "native basic feat selection");
            BlueprintFeatureSelection fighterFeats =
                BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                    BlueprintBootstrap.Library,
                    "41c8486641f7d6d4283ca9dae4147a9f", "native Fighter feat selection");
            bool rapidPresentation = rapidChoices.Length == 5 &&
                rapidReload.Icon != null && rapidReload.Icon.name ==
                    "KMG_Icon_rapid-reload" && rapidChoices.All(value =>
                        value != null && value.Icon == rapidReload.Icon) &&
                (basicFeats.AllFeatures ?? Array.Empty<BlueprintFeature>())
                    .Count(value => ReferenceEquals(value, rapidReload)) == 1 &&
                (fighterFeats.AllFeatures ?? Array.Empty<BlueprintFeature>())
                    .Count(value => ReferenceEquals(value, rapidReload)) == 1;
            bool rapidKindIsolation = true;
            Kingmaker.EntitySystem.Entities.UnitEntityData rapidUnit = null;
            try
            {
                rapidUnit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                for (int index = 0; index < rapidChoices.Length; index++)
                {
                    rapidUnit.Descriptor.AddFact(rapidChoices[index]);
                    for (int kind = 0; kind < FirearmFeatBlueprints.Kinds.Length; kind++)
                        rapidKindIsolation = rapidKindIsolation &&
                            Reloading.RapidReloadRuntime.HasMatchingChoice(
                                rapidUnit.Descriptor,
                                FirearmFeatBlueprints.Kinds[kind]) == (kind == index);
                    rapidUnit.Descriptor.RemoveFact(rapidChoices[index]);
                }
            }
            finally
            {
                if (rapidUnit != null)
                {
                    foreach (BlueprintFeature choice in rapidChoices)
                        if (rapidUnit.Descriptor.HasFact(choice))
                            rapidUnit.Descriptor.RemoveFact(choice);
                    rapidUnit.Dispose();
                }
            }
            int grouped = progression.UIGroups == null ? 0 :
                progression.UIGroups.Sum(group => group == null ||
                    group.Features == null ? 0 : group.Features.Count);
            int topLevelVisible = progression.LevelEntries.Sum(entry =>
                entry.Features.OfType<BlueprintFeature>().Count(feature =>
                    !feature.HideInUI));
            BlueprintAbility reload = BlueprintBootstrap.ReloadTestMusketAbility;
            BlueprintAbility overhaul = BlueprintBootstrap.OverhaulTestMusketAbility;
            BlueprintAbility repair = BlueprintBootstrap.RepairTestMusketAbility;
            bool productionActions = reload != null && overhaul != null && repair != null &&
                reload.Name == "Reload Firearm" &&
                overhaul.Name == "Overhaul Firearm" &&
                repair.Name == "Repair Firearm" &&
                !reload.Description.Contains("Test Musket") &&
                !overhaul.Description.Contains("Test Musket") &&
                !repair.Description.Contains("Test Musket");
            string observed = "levels=" + progression.LevelEntries.Length +
                ";visible=" + visible + ";hidden=" + hidden +
                ";topLevelVisible=" + topLevelVisible +
                ";incomplete=" + incomplete +
                ";tooltipIncomplete=" + tooltipIncomplete + ";groups=" +
                (progression.UIGroups == null ? 0 : progression.UIGroups.Length) +
                ";grouped=" + grouped + ";class=" + classMetadata +
                ";progression=" + progressionMetadata +
                ";semanticIcons=" + semanticIconCount + ";semanticMap=" + semanticMap +
                ";rapidPresentation=" + rapidPresentation +
                ";rapidIsolation=" + rapidKindIsolation +
                ";actions=" + (reload == null ? "<null>" : reload.Name) + "," +
                    (overhaul == null ? "<null>" : overhaul.Name) + "," +
                    (repair == null ? "<null>" : repair.Name);
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("gunslinger-class-presentation",
                    "readable class and progression metadata with icons", observed,
                    classMetadata && progressionMetadata,
                    "registered BlueprintCharacterClass and BlueprintProgression"),
                Assertion("gunslinger-visible-fact-presentation",
                    "all reachable visible project facts have complete names, descriptions, icons, and tooltip metadata",
                    observed, visible > 0 && incomplete == 0 && tooltipIncomplete == 0,
                    "registered progression, selections, and AddFacts graph"),
                Assertion("gunslinger-hidden-fact-exclusion",
                    "hidden implementation facts remain reachable but excluded from visible count",
                    observed, hidden > 0,
                    "HideInUI and Hidden flags"),
                Assertion("gunslinger-progression-ui-groups",
                    "twenty unchanged level entries and nonempty native UI groups",
                    observed, progression.LevelEntries.Length == 20 &&
                        progression.UIGroups != null &&
                        progression.UIGroups.Length > 0 && grouped > 0,
                    "LevelEntries and UIGroups"),
                Assertion("gunslinger-semantic-icon-family",
                    "eleven distinct native-style concepts for core, deed, training, capstone, and maintenance facts",
                    semanticMap, semanticFacts.All(value => value != null &&
                        value.Icon != null) && semanticIconCount == semanticFacts.Length,
                    "exact registered fact icon references"),
                Assertion("rapid-reload-presentation-and-kind-isolation",
                    "one top-level selection; five choices; one native-style icon; each choice matches only its firearm kind",
                    "presentation=" + rapidPresentation + ";isolation=" +
                        rapidKindIsolation + ";choices=" + rapidChoices.Length,
                    rapidPresentation && rapidKindIsolation,
                    "native feat catalogs, exact icon references, and disposable fact grants"),
                Assertion("production-firearm-actions-presentation",
                    "Reload Firearm, Overhaul Firearm, Repair Firearm; no Test Musket descriptions",
                    observed, productionActions,
                    "Firearm Proficiency AddFacts reachable stable ability blueprints"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail,
                assertions, null);
        }

        private RuntimeTestResult RunNativeWeaponFeatContractObservation()
        {
            string[] terms = { "WeaponFocus", "WeaponSpecialization",
                "ImprovedCritical" };
            var matches = BlueprintBootstrap.Library.BlueprintsByAssetId
                .Where(pair => pair.Value != null && terms.Any(term =>
                    pair.Value.name.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0))
                .OrderBy(pair => pair.Value.name, StringComparer.Ordinal)
                .Select(pair => pair.Value.name + "|" + pair.Key + "|" +
                    pair.Value.GetType().FullName + "|components=" +
                    string.Join(",", pair.Value.ComponentsArray.Select(component =>
                        component == null ? "<null>" : component.GetType().FullName)))
                .ToArray();
            string observed = string.Join(";", matches);
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("native-weapon-feat-contracts",
                    "native focus, specialization, and improved-critical blueprints are discoverable",
                    observed, matches.Length >= 4,
                    "live LibraryScriptableObject dictionary names, GUIDs, types, and components"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail,
                assertions, null);
        }

        private RuntimeTestResult RunDisposableFirearmDependentFeats()
        {
            string[] choiceGuids = {
                "71747ea144af4c12922d800f3e9dfa7d",
                "9bc027cd2bba4fcba753b67e9ecaaca5",
                "568543cec0ed434e94dc9c453077473f",
                "c50fd779d2744043ad53f623f21463f0" };
            string[] selectionGuids = {
                "c86f79bc910e46c8846bfdef5b296cbd",
                "ad68031670bd4a67829062b5b39b468e",
                "9218b10aab644225bd8bbe4fd1b47fbe",
                "0de5bfcca6bc486fb16f6fb4d5bf7170" };
            BlueprintFeature[] choices = choiceGuids.Select((guid, index) =>
                BlueprintLibraryLookup.RequireExact<BlueprintFeature>(
                    BlueprintBootstrap.Library, guid, "firearm dependent feat " + index))
                .ToArray();
            BlueprintFeatureSelection[] selections = selectionGuids.Select((guid, index) =>
                BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                    BlueprintBootstrap.Library, guid, "firearm dependent selection " + index))
                .ToArray();
            BlueprintFeature legacy = BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                BlueprintBootstrap.Library, "0061053ca1104e19b7aa77e34c3a442c",
                "legacy firearm Weapon Focus");
            BlueprintFeature legacyProficiency = BlueprintLibraryLookup.RequireExact<
                BlueprintFeature>(BlueprintBootstrap.Library,
                "b1a58cfdbf004f04ade7765373484c29",
                "legacy Exotic Weapon Proficiency (Firearms)");
            BlueprintFeatureSelection basic = BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                BlueprintBootstrap.Library, "247a4068296e8be42890143f451b4b45",
                "basic feat selection");
            BlueprintFeatureSelection fighter = BlueprintLibraryLookup.RequireExact<BlueprintFeatureSelection>(
                BlueprintBootstrap.Library, "41c8486641f7d6d4283ca9dae4147a9f",
                "Fighter feat selection");
            string[] nativeGuids = {
                "1e1f627d26ad36f43bbd26cc2bf8ac7e",
                "09c9e82965fb4334b984a1e9df3bd088",
                "31470b17e8446ae4ea0dacd6c5817d86",
                "7cf5edc65e785a24f9cf93af987d66b3",
                "f4201c85a991369408740c6888362e20" };
            BlueprintParametrizedFeature[] native = nativeGuids.Select((guid, index) =>
                BlueprintLibraryLookup.RequireExact<BlueprintParametrizedFeature>(
                    BlueprintBootstrap.Library, guid, "native weapon feat " + index))
                .ToArray();
            bool catalog = selections.All(selection => selection.HideInUI &&
                !basic.AllFeatures.Contains(selection) &&
                !fighter.AllFeatures.Contains(selection));
            BlueprintFeatureSelection[] allSelections = BlueprintBootstrap.Library
                .GetAllBlueprints().OfType<BlueprintFeatureSelection>().ToArray();
            bool proficiencyCatalog = allSelections.All(selection =>
                    !(selection.Features ?? Array.Empty<BlueprintFeature>()).Any(value =>
                        ReferenceEquals(value, legacyProficiency) || value != null &&
                        value.AssetGuid == legacyProficiency.AssetGuid) &&
                    !(selection.AllFeatures ?? Array.Empty<BlueprintFeature>()).Any(value =>
                        ReferenceEquals(value, legacyProficiency) || value != null &&
                        value.AssetGuid == legacyProficiency.AssetGuid)) &&
                (legacyProficiency.Groups ?? Array.Empty<FeatureGroup>()).Length == 0 &&
                !legacyProficiency.HideInUI;
            AddFacts[] compatibilityGrants =
                (legacyProficiency.ComponentsArray ??
                    Array.Empty<BlueprintComponent>()).OfType<AddFacts>().ToArray();
            bool compatibilityBlueprint = compatibilityGrants.Length == 1 &&
                compatibilityGrants[0].Facts != null &&
                compatibilityGrants[0].Facts.Length == 1 &&
                ReferenceEquals(compatibilityGrants[0].Facts[0],
                    BlueprintBootstrap.FirearmProficiency);
            string[] expectedFirearmNames = { "Blunderbuss", "Musket", "Pistol",
                "Revolver", "Rifle" };
            BlueprintUnit source = BlueprintRoot.Instance.DefaultPlayerCharacter;
            var legacyUnit = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
            bool ordinaryCannotAcquire = false, legacyOwnerRetained = false,
                legacyActionsExact = false;
            try
            {
                UnitDescriptor descriptor = legacyUnit.Descriptor;
                ordinaryCannotAcquire = !descriptor.HasFact(legacyProficiency) &&
                    !descriptor.HasFact(BlueprintBootstrap.FirearmProficiency) &&
                    proficiencyCatalog;
                if (descriptor.AddFact(legacyProficiency) == null)
                    throw new InvalidOperationException(
                        "Detached legacy owner could not receive its preserved wrapper.");
                AddFacts actionGrant = (BlueprintBootstrap.FirearmProficiency
                    .ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<AddFacts>().Single();
                legacyOwnerRetained = descriptor.HasFact(legacyProficiency) &&
                    descriptor.HasFact(BlueprintBootstrap.FirearmProficiency);
                legacyActionsExact = actionGrant.Facts != null &&
                    actionGrant.Facts.Length == 3 &&
                    actionGrant.Facts.Distinct().Count() == 3 &&
                    actionGrant.Facts.All(fact => descriptor.HasFact(fact));
            }
            finally { legacyUnit.Dispose(); }
            var menuUnit = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
            bool levelUpMenus;
            bool levelUpCommit;
            try
            {
                if (menuUnit.Descriptor.AddFact(
                        BlueprintBootstrap.FirearmProficiency) == null)
                    throw new InvalidOperationException(
                        "Detached firearm-feat menu owner could not receive full proficiency.");
                levelUpMenus = native.All(feature =>
                {
                    FeatureUIData[] menu = feature.ExtractSelectionItems(
                            menuUnit.Descriptor, menuUnit.Descriptor)
                        .OfType<FeatureUIData>().ToArray();
                    string[] firearmNames = menu.Where(item => item != null &&
                            item.Param.Blueprint != null && item.Param.Blueprint.name.StartsWith(
                                "KMG_WeaponFocus_", StringComparison.Ordinal))
                        .Select(item => item.Name).ToArray();
                    return firearmNames.SequenceEqual(expectedFirearmNames);
                });
                BlueprintParametrizedFeature weaponFocus = native[0];
                FeatureUIData pistolChoice = weaponFocus.ExtractSelectionItems(
                        menuUnit.Descriptor, menuUnit.Descriptor)
                    .OfType<FeatureUIData>().Single(item => item.Name == "Pistol");
                var selectionState = new Kingmaker.UnitLogic.Class.LevelUp.FeatureSelectionState(
                    null, weaponFocus, weaponFocus, 0, 0);
                selectionState.Select(pistolChoice, null);
                levelUpCommit = ReferenceEquals(selectionState.SelectedItem, pistolChoice) &&
                    pistolChoice.Param.Blueprint != null && string.Equals(
                        pistolChoice.Param.Blueprint.name, "KMG_WeaponFocus_Pistol",
                        StringComparison.Ordinal);
            }
            finally { menuUnit.Dispose(); }
            bool nativeMenus = native.All(feature =>
            {
                FeatureUIData[] menu = feature.GetFullSelectionItems().ToArray();
                string[] names = menu.Select(item => item == null
                    ? string.Empty : item.Name).ToArray();
                string[] firearmNames = menu.Where(item => item != null &&
                        item.Param.Blueprint != null && item.Param.Blueprint.name.StartsWith(
                            "KMG_WeaponFocus_", StringComparison.Ordinal))
                    .Select(item => item.Name).ToArray();
                return names.SequenceEqual(names.OrderBy(name => name,
                           StringComparer.CurrentCultureIgnoreCase)) &&
                    firearmNames.SequenceEqual(expectedFirearmNames);
            });
            bool prerequisites = choices[0].ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteClassLevel>().Any() &&
                choices[1].ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteClassLevel>().Any() &&
                choices[2].ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteClassLevel>().Any() &&
                choices[3].ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteStatValue>().Any() &&
                choices.Take(2).All(choice => choice.ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteFeature>().Count() == 1) &&
                choices[2].ComponentsArray.OfType<
                    Kingmaker.Blueprints.Classes.Prerequisites.PrerequisiteFeature>().Count() == 2;

            var attacker = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
            var target = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
            ItemEntityWeapon pistol = null, musket = null, crossbow = null;
            bool effects = false, isolation = false;
            try
            {
                pistol = new ItemEntityWeapon(BlueprintBootstrap.ProductionFirearms.Pistol.Item);
                musket = new ItemEntityWeapon(BlueprintBootstrap.ProductionFirearms.Musket.Item);
                BlueprintItemWeapon nativeCrossbow = BlueprintLibraryLookup.RequireExact<BlueprintItemWeapon>(
                    BlueprintBootstrap.Library,
                    TestMusketBlueprints.NativeStandardHeavyCrossbowItemGuid,
                    "native heavy crossbow isolation fixture");
                crossbow = new ItemEntityWeapon(nativeCrossbow);
                var greaterFocus = choices[0].ComponentsArray.OfType<
                    KingmakerGunslinger.Feats.FirearmWeaponFeatBonus>().Single();
                var specialization = choices[1].ComponentsArray.OfType<
                    KingmakerGunslinger.Feats.FirearmWeaponFeatBonus>().Single();
                var greaterSpecialization = choices[2].ComponentsArray.OfType<
                    KingmakerGunslinger.Feats.FirearmWeaponFeatBonus>().Single();
                var improvedCritical = choices[3].ComponentsArray.OfType<
                    KingmakerGunslinger.Feats.FirearmWeaponFeatBonus>().Single();
                var pistolRoll = new RuleAttackRoll(attacker, target, pistol, 0);
                greaterFocus.OnEventAboutToTrigger(pistolRoll);
                var pistolStats = new RuleCalculateWeaponStats(attacker, pistol, null);
                specialization.OnEventAboutToTrigger(pistolStats);
                greaterSpecialization.OnEventAboutToTrigger(pistolStats);
                improvedCritical.OnEventAboutToTrigger(pistolStats);
                effects = pistolRoll.AttackBonusPenalty == -1 &&
                    pistolStats.BonusDamage == 4 && pistolStats.DoubleCriticalEdge;

                var musketRoll = new RuleAttackRoll(attacker, target, musket, 0);
                greaterFocus.OnEventAboutToTrigger(musketRoll);
                var musketStats = new RuleCalculateWeaponStats(attacker, musket, null);
                specialization.OnEventAboutToTrigger(musketStats);
                greaterSpecialization.OnEventAboutToTrigger(musketStats);
                improvedCritical.OnEventAboutToTrigger(musketStats);
                var crossbowRoll = new RuleAttackRoll(attacker, target, crossbow, 0);
                greaterFocus.OnEventAboutToTrigger(crossbowRoll);
                var crossbowStats = new RuleCalculateWeaponStats(attacker, crossbow, null);
                specialization.OnEventAboutToTrigger(crossbowStats);
                greaterSpecialization.OnEventAboutToTrigger(crossbowStats);
                improvedCritical.OnEventAboutToTrigger(crossbowStats);
                isolation = musketRoll.AttackBonusPenalty == 0 &&
                    musketStats.BonusDamage == 0 && !musketStats.DoubleCriticalEdge &&
                    crossbowRoll.AttackBonusPenalty == 0 &&
                    crossbowStats.BonusDamage == 0 && !crossbowStats.DoubleCriticalEdge;
            }
            finally
            {
                if (crossbow != null) crossbow.Dispose();
                if (musket != null) musket.Dispose();
                if (pistol != null) pistol.Dispose();
                target.Dispose();
                attacker.Dispose();
            }
            string observed = "catalog=" + catalog + ";prerequisites=" + prerequisites +
                ";effects=" + effects + ";isolation=" + isolation +
                ";nativeMenus=" + nativeMenus + ";levelUpMenus=" + levelUpMenus +
                ";levelUpCommit=" + levelUpCommit +
                ";legacyHidden=" + legacy.HideInUI +
                ";proficiencyCatalog=" + proficiencyCatalog +
                ";compatibilityBlueprint=" + compatibilityBlueprint +
                ";ordinaryCannotAcquire=" + ordinaryCannotAcquire +
                ";legacyOwnerRetained=" + legacyOwnerRetained +
                ";legacyActionsExact=" + legacyActionsExact;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("dependent-feat-catalog", "obsolete wrappers hidden and absent from native catalogs", observed,
                    catalog, "live basic and Fighter feat catalogs"),
                Assertion("native-firearm-parameter-menus",
                    "Blunderbuss, Musket, Pistol, Revolver, and Rifle alphabetically inside each native feat submenu",
                    observed, nativeMenus,
                    "BlueprintParametrizedFeature.GetFullSelectionItems"),
                Assertion("native-firearm-level-up-parameter-menus",
                    "all five firearms appear through the actual unit-aware native level-up enumeration path",
                    observed, levelUpMenus,
                    "BlueprintParametrizedFeature.ExtractSelectionItems(beforeLevelUpUnit, previewUnit)"),
                Assertion("native-weapon-focus-level-up-commit",
                    "the native Weapon Focus selection state commits the Pistol parameter",
                    observed, levelUpCommit,
                    "FeatureSelectionState.Select with the unit-aware native menu item"),
                Assertion("dependent-feat-prerequisites", "native level/BAB shapes plus exact firearm dependency", observed,
                    prerequisites, "cloned native prerequisites and project feature dependency"),
                Assertion("dependent-feat-effects", "+1 attack, +4 combined specialization damage, doubled critical edge", observed,
                    effects, "production firearm feat rule components"),
                Assertion("dependent-feat-isolation", "wrong firearm kind and native crossbow unchanged", observed,
                    isolation, "exact FirearmDefinition.Kind matching"),
                Assertion("legacy-weapon-focus-compatibility", "legacy selection retained and hidden", observed,
                    legacy.HideInUI, "preserved 0.0.61 GUID and facts"),
                Assertion("firearm-proficiency-acquisition-policy",
                    "no selection or FeatureGroup route for a new ordinary character",
                    observed, ordinaryCannotAcquire && proficiencyCatalog,
                    "all live selection Features/AllFeatures and detached ordinary descriptor"),
                Assertion("legacy-firearm-proficiency-compatibility",
                    "stable wrapper grants the stable full proficiency and three distinct action facts",
                    observed, compatibilityBlueprint && legacyOwnerRetained &&
                        legacyActionsExact,
                    "real AddFact propagation on a detached legacy owner"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposableEmptyFirearmCommand()
        {
            BlueprintItemWeapon pistol = BlueprintBootstrap.ProductionFirearms.Pistol.Item;
            BlueprintItem powder = BlueprintBootstrap.BasicAmmunition.BlackPowder;
            BlueprintItem ball = BlueprintBootstrap.BasicAmmunition.LeadBall;
            BlueprintAbility standard = BlueprintBootstrap.ReloadTestMusketAbility;
            Player player = Game.Instance.Player;
            int powderBefore = player.Inventory.Count(powder);
            int ballBefore = player.Inventory.Count(ball);
            var attacker = new Kingmaker.UI.LevelUp.ChargenUnit(
                BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
            var target = new Kingmaker.UI.LevelUp.ChargenUnit(
                BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
            ItemEntityWeapon weapon = null;
            long rejectedBefore = EmptyFirearmAttackCommandPatch.Rejected;
            long autoBefore = EmptyFirearmAttackCommandPatch.AutoReloadReplacements;
            long evaluatedBefore = EmptyFirearmAttackCommandPatch.EvaluatedAttacks;
            long rulesBefore = FirearmDischargeRuntimeDiagnostics.Observed;
            bool rejectedOnce = false, noRule = false, autoReplacement = false,
                statePreserved = false, resolverReady = false;
            try
            {
                weapon = new ItemEntityWeapon(pistol);
                attacker.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Normal));
                ExactEquippedFirearmContext resolved;
                string resolutionReason;
                resolverReady = ExactEquippedFirearmResolver.TryResolve(
                    attacker.Descriptor, out resolved, out resolutionReason);
                UnitCommand rejected = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(attacker, target);
                rejectedOnce = rejected == null &&
                    EmptyFirearmAttackCommandPatch.Rejected == rejectedBefore + 1 &&
                    EmptyFirearmAttackCommandPatch.AutoReloadReplacements == autoBefore;
                noRule = FirearmDischargeRuntimeDiagnostics.Observed == rulesBefore;
                statePreserved = FirearmRuntimeState.Service.GetOrCreate(weapon)
                    .Repository.State.LoadedRounds == 0;

                object ignored;
                string method;
                if (!ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                    new[] { new object[] { powder }, new object[] { powder, 1 } },
                    out ignored, out method) ||
                    !ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                    new[] { new object[] { ball }, new object[] { ball, 1 } },
                    out ignored, out method))
                    throw new InvalidOperationException("Temporary auto-reload ammunition could not be added.");
                var combat = new Kingmaker.Controllers.Combat.UnitCombatState(attacker);
                SetExactProperty(attacker, "CombatState", combat);
                var data = new Kingmaker.UnitLogic.Abilities.AbilityData(
                    standard, attacker.Descriptor);
                attacker.AutoUseAbility = data;
                UnitCommand replacement = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(attacker, target);
                autoReplacement = replacement is Kingmaker.UnitLogic.Commands.UnitUseAbility &&
                    EmptyFirearmAttackCommandPatch.Rejected == rejectedBefore + 2 &&
                    EmptyFirearmAttackCommandPatch.AutoReloadReplacements == autoBefore + 1 &&
                    EmptyFirearmAttackCommandPatch.EvaluatedAttacks == evaluatedBefore + 2;
                noRule = noRule && FirearmDischargeRuntimeDiagnostics.Observed == rulesBefore;
            }
            finally
            {
                attacker.AutoUseAbility = null;
                SetExactProperty(attacker, "CombatState", null);
                if (weapon != null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if (attacker.Body.PrimaryHand.MaybeItem != null)
                        attacker.Body.PrimaryHand.RemoveItem(false);
                    weapon.Dispose();
                }
                int powderExtra = player.Inventory.Count(powder) - powderBefore;
                int ballExtra = player.Inventory.Count(ball) - ballBefore;
                if (powderExtra > 0) player.Inventory.Remove(powder, powderExtra);
                if (ballExtra > 0) player.Inventory.Remove(ball, ballExtra);
                target.Dispose();
                attacker.Dispose();
            }
            string observed = "resolver=" + resolverReady + ";evaluated=" +
                (EmptyFirearmAttackCommandPatch.EvaluatedAttacks - evaluatedBefore) +
                ";rejectedOnce=" + rejectedOnce + ";auto=" + autoReplacement +
                ";noRule=" + noRule + ";state=" + statePreserved;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("empty-command-pre-rule-rejection",
                    "no attack command is constructed for one unloaded request", observed,
                    resolverReady && rejectedOnce,
                    "exact equipped resolver and UnitAttack.CreateAttackCommand patch"),
                Assertion("empty-command-no-attack-rule",
                    "no RuleAttackRoll discharge observation", observed, noRule,
                    "FirearmDischargeRuntimeDiagnostics observed counter"),
                Assertion("empty-command-no-mutation",
                    "empty state remains empty", observed, statePreserved,
                    "item-owned firearm state"),
                Assertion("empty-command-auto-reload-replacement",
                    "attack construction replaced by one native reload command", observed,
                    autoReplacement, "native UnitUseAbility auto-use command"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposableReloadAutocast()
        {
            BlueprintAbility parent = BlueprintBootstrap.ReloadTestMusketAbility;
            BlueprintAbility[] variants = parent.ComponentsArray
                .OfType<AbilityVariants>().SelectMany(value => value.Variants).ToArray();
            BlueprintAbility standard = parent;
            ReloadTestMusketAbilityLogic logic = standard.ComponentsArray
                .OfType<ReloadTestMusketAbilityLogic>().Single();
            BlueprintItemWeapon pistol = BlueprintBootstrap.ProductionFirearms.Pistol.Item;
            BlueprintItem powder = BlueprintBootstrap.BasicAmmunition.BlackPowder;
            BlueprintItem ball = BlueprintBootstrap.BasicAmmunition.LeadBall;
            Player player = Game.Instance == null ? null : Game.Instance.Player;
            if (player == null || player.Inventory == null)
                throw new InvalidOperationException("The save-free player inventory is unavailable.");
            int powderBefore = player.Inventory.Count(powder);
            int ballBefore = player.Inventory.Count(ball);
            Kingmaker.EntitySystem.Entities.UnitEntityData unit = null;
            Kingmaker.EntitySystem.Entities.UnitEntityData target = null;
            ItemEntityWeapon weapon = null;
            ItemEntityWeapon switchedWeapon = null;
            bool nativeSelected = false, oneTransaction = false,
                resumedTargetAttack = false, noRetryWhenFull = false,
                switchedWeaponCanceled = false, interruptedCanceled = false,
                wreckedRejected = false, turnBasedPolicy = false,
                noAmmoLoop = false, cleaned = false;
            int powderAfter = -1, ballAfter = -1, roundsAfter = -1;
            try
            {
                object ignored;
                string method;
                if (!ReflectionAccess.TryInvokeAny(player.Inventory,
                    new[] { "Add" }, new[] { new object[] { powder, 2 },
                        new object[] { powder } }, out ignored, out method) ||
                    !ReflectionAccess.TryInvokeAny(player.Inventory,
                    new[] { "Add" }, new[] { new object[] { ball, 2 },
                        new object[] { ball } }, out ignored, out method))
                    throw new InvalidOperationException("Temporary ammunition could not be added.");
                unit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                target = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                weapon = new ItemEntityWeapon(pistol);
                unit.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Normal));
                var combat = new Kingmaker.Controllers.Combat.UnitCombatState(unit);
                SetExactProperty(unit, "CombatState", combat);
                unit.Descriptor.AddFact(standard);
                Kingmaker.UnitLogic.Abilities.Ability granted =
                    unit.Descriptor.Abilities.GetAbility(standard);
                if (granted == null)
                    throw new InvalidOperationException(
                        "Kingmaker did not retain the granted Reload Firearm fact.");
                var data = new Kingmaker.UnitLogic.Abilities.AbilityData(granted);
                unit.AutoUseAbility = data;
                Kingmaker.UnitLogic.Abilities.AbilityData selected =
                    unit.GetAvailableAutoUseAbility();
                nativeSelected = ReferenceEquals(selected, data) &&
                    data.IsSuitableForAutoUse && data.IsAvailable;
                UnitCommand replacement = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(unit, target);
                var reloadCommand = replacement as
                    Kingmaker.UnitLogic.Commands.UnitUseAbility;
                if (reloadCommand == null)
                    throw new InvalidOperationException(
                        "Empty exact firearm attack did not produce a native reload command.");
                nativeSelected = nativeSelected && reloadCommand != null &&
                    ReferenceEquals(reloadCommand.Spell.Blueprint, standard);
                var context = new Kingmaker.UnitLogic.Abilities.AbilityExecutionContext(
                    selected, new Kingmaker.UnitLogic.Abilities.AbilityParams(),
                    new TargetWrapper(unit), null);
                IEnumerator<AbilityDeliveryTarget> delivery = logic.Deliver(
                    context, new TargetWrapper(unit));
                while (delivery.MoveNext()) { }
                roundsAfter = FirearmRuntimeState.Service.GetOrCreate(weapon)
                    .Repository.State.LoadedRounds;
                powderAfter = player.Inventory.Count(powder);
                ballAfter = player.Inventory.Count(ball);
                oneTransaction = roundsAfter == 1 &&
                    powderAfter == powderBefore + 1 &&
                    ballAfter == ballBefore + 1;
                UnitCommand resumed = EmptyFirearmAttackCommandPatch
                    .CompletePendingForRuntimeTest(
                    reloadCommand, false);
                var resumedAttack = resumed as Kingmaker.UnitLogic.Commands.UnitAttack;
                resumedTargetAttack = resumedAttack != null &&
                    ReferenceEquals(resumedAttack.Target, target) &&
                    unit.Commands.Contains(resumedAttack);
                noRetryWhenFull = unit.GetAvailableAutoUseAbility() == null;

                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Normal));
                var switchedPending = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(unit, target) as
                    Kingmaker.UnitLogic.Commands.UnitUseAbility;
                switchedWeapon = new ItemEntityWeapon(pistol);
                unit.Body.PrimaryHand.RemoveItem(false);
                unit.Body.PrimaryHand.InsertItem(switchedWeapon);
                    FirearmRuntimeState.Service.Set(switchedWeapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 1,
                    BlueprintBootstrap.ProductionFirearms.Pistol.Spec.Definition
                        .Reload.Ammunition,
                    FirearmCondition.Normal));
                switchedWeaponCanceled = switchedPending != null &&
                    EmptyFirearmAttackCommandPatch.CompletePendingForRuntimeTest(
                        switchedPending, false) == null;
                unit.Body.PrimaryHand.RemoveItem(false);
                FirearmRuntimeState.Service.Forget(switchedWeapon);
                switchedWeapon.Dispose();
                switchedWeapon = null;
                unit.Body.PrimaryHand.InsertItem(weapon);

                var interruptedPending = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(unit, target) as
                    Kingmaker.UnitLogic.Commands.UnitUseAbility;
                interruptedCanceled = interruptedPending != null &&
                    EmptyFirearmAttackCommandPatch.CompletePendingForRuntimeTest(
                        interruptedPending, true) == null;

                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Wrecked));
                long replacementsBeforeWrecked =
                    EmptyFirearmAttackCommandPatch.AutoReloadReplacements;
                UnitCommand wrecked = Kingmaker.UnitLogic.Commands.UnitAttack
                    .CreateAttackCommand(unit, target);
                wreckedRejected = wrecked == null &&
                    EmptyFirearmAttackCommandPatch.AutoReloadReplacements ==
                        replacementsBeforeWrecked;
                turnBasedPolicy =
                    EmptyFirearmAttackCommandPatch.TurnBasedAllowsStandardAttack(
                        false, false, false) &&
                    EmptyFirearmAttackCommandPatch.TurnBasedAllowsStandardAttack(
                        true, true, true) &&
                    !EmptyFirearmAttackCommandPatch.TurnBasedAllowsStandardAttack(
                        true, true, false) &&
                    !EmptyFirearmAttackCommandPatch.TurnBasedAllowsStandardAttack(
                        true, false, true);

                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Normal));
                player.Inventory.Remove(powder, player.Inventory.Count(powder) - powderBefore);
                player.Inventory.Remove(ball, player.Inventory.Count(ball) - ballBefore);
                noAmmoLoop = unit.GetAvailableAutoUseAbility() == null &&
                    unit.GetAvailableAutoUseAbility() == null &&
                    FirearmRuntimeState.Service.GetOrCreate(weapon)
                        .Repository.State.LoadedRounds == 0;
            }
            finally
            {
                if (unit != null)
                {
                    unit.AutoUseAbility = null;
                    SetExactProperty(unit, "CombatState", null);
                }
                if (weapon != null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if (unit != null && unit.Body.PrimaryHand.MaybeItem != null)
                        unit.Body.PrimaryHand.RemoveItem(false);
                }
                if (switchedWeapon != null)
                {
                    FirearmRuntimeState.Service.Forget(switchedWeapon);
                    if (unit != null && ReferenceEquals(
                        unit.Body.PrimaryHand.MaybeItem, switchedWeapon))
                        unit.Body.PrimaryHand.RemoveItem(false);
                    switchedWeapon.Dispose();
                }
                int powderExcess = player.Inventory.Count(powder) - powderBefore;
                int ballExcess = player.Inventory.Count(ball) - ballBefore;
                if (powderExcess > 0) player.Inventory.Remove(powder, powderExcess);
                if (ballExcess > 0) player.Inventory.Remove(ball, ballExcess);
                if (unit != null) unit.Dispose();
                if (target != null) target.Dispose();
                cleaned = player.Inventory.Count(powder) == powderBefore &&
                    player.Inventory.Count(ball) == ballBefore;
            }
            string observed = "publicVariants=" + variants.Length + ";selected=" +
                nativeSelected + ";rounds=" + roundsAfter + ";powder=" +
                powderBefore + "->" + powderAfter + ";ball=" + ballBefore +
                "->" + ballAfter + ";fullRetry=" + !noRetryWhenFull +
                ";resumedTarget=" + resumedTargetAttack +
                ";switchCanceled=" + switchedWeaponCanceled +
                ";interruptedCanceled=" + interruptedCanceled +
                ";wreckedRejected=" + wreckedRejected +
                ";turnBasedPolicy=" + turnBasedPolicy +
                ";noAmmoLoop=" + noAmmoLoop + ";cleaned=" + cleaned;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("reload-single-player-action",
                    "one visible dynamic ability; no public variants",
                    observed, !parent.Hidden && variants.Length == 0 &&
                        parent.ComponentsArray.OfType<ReloadTestMusketAbilityLogic>()
                            .Count() == 1,
                    "single public reload blueprint presentation"),
                Assertion("native-reload-autocast-selection",
                    "native right-click selection resolves the single Reload Firearm ability",
                    observed, nativeSelected,
                    "UnitEntityData.AutoUseAbility/GetAvailableAutoUseAbility"),
                Assertion("automatic-reload-single-transaction",
                    "one round and one powder/ball pair consumed exactly once",
                    observed, oneTransaction && noRetryWhenFull,
                    "the same ReloadTestMusketAbilityLogic delivery used by manual reload"),
                Assertion("automatic-reload-rtwp-target-resume",
                    "successful exact-item reload queues one native attack against the original target",
                    observed, resumedTargetAttack,
                    "UnitUseAbility completion continuation plus UnitCommands.AddToQueue"),
                Assertion("automatic-reload-stale-context-cancellation",
                    "weapon switch and interrupted reload cancel; Wrecked never queues reload",
                    observed, switchedWeaponCanceled && interruptedCanceled &&
                        wreckedRejected,
                    "exact weapon reference re-resolution, completion result, and Wrecked policy"),
                Assertion("automatic-reload-turn-based-action-policy",
                    "RTwP resumes; turn-based resumes only with a current turn and unused standard action",
                    observed, turnBasedPolicy,
                    "fail-closed turn-based standard-action continuation gate"),
                Assertion("automatic-reload-no-ammunition-loop",
                    "two consecutive native polls reject without mutation",
                    observed, noAmmoLoop,
                    "availability provider plus empty exact firearm state"),
                Assertion("request-local-cleanup", "ammunition and unit fixture restored",
                    observed, cleaned,
                    "guaranteed finally cleanup; no save API"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail,
                assertions, null);
        }

        private RuntimeTestResult RunDisposablePaperCartridgeReload()
        {
            Player player = Game.Instance == null ? null : Game.Instance.Player;
            if (player == null || player.Inventory == null)
                throw new InvalidOperationException("The save-free player inventory is unavailable.");
            BasicAmmunitionBlueprintSet ammunition = BlueprintBootstrap.BasicAmmunition;
            PaperCartridgeModeBlueprintSet mode = BlueprintBootstrap.PaperCartridgeMode;
            BlueprintItemWeapon pistol = BlueprintBootstrap.ProductionFirearms.Pistol.Item;
            BlueprintItemWeapon rifle = BlueprintBootstrap.ProductionFirearms.AdvancedRifle.Item;
            MagicFirearmBlueprintEntry namedEntry = BlueprintBootstrap.MagicFirearms.Entries[3];
            BlueprintItemWeapon named = namedEntry.Item;
            int powderBefore = player.Inventory.Count(ammunition.BlackPowder);
            int ballBefore = player.Inventory.Count(ammunition.LeadBall);
            int paperBefore = player.Inventory.Count(ammunition.PaperCartridge);
            UnitEntityData unit = null, secondUnit = null;
            ItemEntityWeapon weapon = null;
            Buff marker = null;
            ActivatableAbility nativeMode = null, secondMode = null;
            bool modeGranted = false, offByDefault = false, pistolLoaded = false,
                actionExact = false, noLooseConsumption = false,
                magicCompatible = false, staticPreserved = false,
                advancedRejected = false, brokenRetained = false,
                modeIsolated = false, exhaustionRetainsMode = false, cleaned = false;
            string observed = null;
            try
            {
                object ignored; string method;
                if (!ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                    new[] { new object[] { ammunition.PaperCartridge, 3 },
                        new object[] { ammunition.PaperCartridge } },
                    out ignored, out method))
                    throw new InvalidOperationException("Temporary Paper Cartridges could not be added.");
                unit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                unit.Descriptor.AddFact(BlueprintBootstrap.FirearmProficiency);
                nativeMode = unit.Descriptor.ActivatableAbilities.Enumerable
                    .SingleOrDefault(value => value != null &&
                        ReferenceEquals(value.Blueprint, mode.Ability));
                modeGranted = nativeMode != null;
                offByDefault = nativeMode != null && !nativeMode.IsOn &&
                    !PaperCartridgeModeRuntime.IsActive(unit.Descriptor, mode.Marker);
                if (nativeMode != null) nativeMode.IsOn = true;
                marker = unit.Descriptor.Buffs.RawFacts.OfType<Buff>()
                    .SingleOrDefault(value => ReferenceEquals(value.Blueprint, mode.Marker));
                if (marker == null || !PaperCartridgeModeRuntime.IsActive(unit.Descriptor, mode.Marker))
                    throw new InvalidOperationException("The request-local paper mode marker was rejected.");
                secondUnit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                secondUnit.Descriptor.AddFact(BlueprintBootstrap.FirearmProficiency);
                secondMode = secondUnit.Descriptor.ActivatableAbilities.Enumerable
                    .Single(value => ReferenceEquals(value.Blueprint, mode.Ability));
                modeIsolated = !secondMode.IsOn &&
                    !PaperCartridgeModeRuntime.IsActive(secondUnit.Descriptor, mode.Marker) &&
                    PaperCartridgeModeRuntime.IsActive(unit.Descriptor, mode.Marker);
                weapon = new ItemEntityWeapon(pistol);
                unit.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                ReloadTestMusketAvailability plan = ReloadTestMusketRuntime.Evaluate(
                    unit.Descriptor, pistol, ammunition.BlackPowder, ammunition.LeadBall);
                actionExact = plan.IsAvailable && plan.Plan.Action == EffectiveReloadAction.Move &&
                    ReferenceEquals(plan.Plan.ExactItem, weapon) &&
                    plan.Plan.Profile == ReloadAmmunitionProfileCatalog.PaperCartridge;
                FirearmReloadResult reload = ReloadTestMusketRuntime.Execute(unit.Descriptor,
                    pistol, ammunition.BlackPowder, ammunition.LeadBall);
                FirearmState loaded = FirearmRuntimeState.Service.GetOrCreate(weapon).Repository.State;
                pistolLoaded = reload.Succeeded && loaded.LoadedAmmunition ==
                    ReloadAmmunitionProfileCatalog.PaperCartridge.LoadedAmmunition;
                noLooseConsumption = player.Inventory.Count(ammunition.BlackPowder) == powderBefore &&
                    player.Inventory.Count(ammunition.LeadBall) == ballBefore;

                FirearmRuntimeState.Service.Forget(weapon);
                unit.Body.PrimaryHand.RemoveItem(false);
                weapon.Dispose();
                weapon = new ItemEntityWeapon(named);
                unit.Body.PrimaryHand.InsertItem(weapon);
                int staticBefore = weapon.Enchantments.Count(value => value != null &&
                    namedEntry.Spec.Enchantments.Contains(value.Blueprint as BlueprintWeaponEnchantment));
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                ReloadTestMusketAvailability namedPlan = ReloadTestMusketRuntime.Evaluate(
                    unit.Descriptor, named, ammunition.BlackPowder, ammunition.LeadBall);
                FirearmReloadResult namedReload = ReloadTestMusketRuntime.Execute(unit.Descriptor,
                    named, ammunition.BlackPowder, ammunition.LeadBall);
                int staticAfter = weapon.Enchantments.Count(value => value != null &&
                    namedEntry.Spec.Enchantments.Contains(value.Blueprint as BlueprintWeaponEnchantment));
                magicCompatible = namedPlan.IsAvailable && namedReload.Succeeded;
                staticPreserved = staticBefore == staticAfter && staticBefore == 2;

                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null, FirearmCondition.Broken));
                ReloadTestMusketRuntime.Execute(unit.Descriptor, named,
                    ammunition.BlackPowder, ammunition.LeadBall);
                brokenRetained = FirearmRuntimeState.Service.GetOrCreate(weapon)
                    .Repository.State.Condition == FirearmCondition.Broken;

                FirearmRuntimeState.Service.Forget(weapon);
                unit.Body.PrimaryHand.RemoveItem(false);
                weapon.Dispose();
                weapon = new ItemEntityWeapon(rifle);
                unit.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                ReloadTestMusketAvailability rejected = ReloadTestMusketRuntime.Evaluate(
                    unit.Descriptor, rifle, ammunition.BlackPowder, ammunition.LeadBall);
                advancedRejected = !rejected.IsAvailable && rejected.Plan != null &&
                    rejected.Plan.Status == FirearmReloadPlanStatus.IncompatibleAmmunition;
                int remainingPaper = player.Inventory.Count(ammunition.PaperCartridge);
                if (remainingPaper > 0)
                    player.Inventory.Remove(ammunition.PaperCartridge, remainingPaper);
                exhaustionRetainsMode = nativeMode.IsOn &&
                    PaperCartridgeModeRuntime.IsActive(unit.Descriptor, mode.Marker);
                observed = "modeGranted=" + modeGranted + ";offDefault=" + offByDefault +
                    ";action=" + actionExact + ";pistol=" + pistolLoaded +
                    ";looseUntouched=" + noLooseConsumption + ";magic=" + magicCompatible +
                    ";static=" + staticPreserved + ";broken=" + brokenRetained +
                    ";advancedRejected=" + advancedRejected +
                    ";modeIsolated=" + modeIsolated +
                    ";exhaustionRetainsMode=" + exhaustionRetainsMode;
            }
            finally
            {
                if (nativeMode != null && nativeMode.IsOn) nativeMode.IsOn = false;
                if (secondMode != null && secondMode.IsOn) secondMode.IsOn = false;
                if (unit != null && marker != null && unit.Descriptor.Buffs.RawFacts.Contains(marker))
                    unit.Descriptor.Buffs.RemoveFact(marker);
                if (weapon != null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if (unit != null && unit.Body.PrimaryHand.MaybeItem != null)
                        unit.Body.PrimaryHand.RemoveItem(false);
                    weapon.Dispose();
                }
                int excess = player.Inventory.Count(ammunition.PaperCartridge) - paperBefore;
                if (excess > 0) player.Inventory.Remove(ammunition.PaperCartridge, excess);
                int deficit = paperBefore - player.Inventory.Count(ammunition.PaperCartridge);
                if (deficit > 0)
                {
                    object ignored; string method;
                    ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                        new[] { new object[] { ammunition.PaperCartridge, deficit } },
                        out ignored, out method);
                }
                if (unit != null) unit.Dispose();
                if (secondUnit != null) secondUnit.Dispose();
                cleaned = player.Inventory.Count(ammunition.PaperCartridge) == paperBefore &&
                    player.Inventory.Count(ammunition.BlackPowder) == powderBefore &&
                    player.Inventory.Count(ammunition.LeadBall) == ballBefore;
            }
            observed = (observed ?? "fixture-failed-before-observation") + ";cleaned=" + cleaned;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("paper-mode-native-grant", "granted exactly through proficiency and off by default",
                    observed, modeGranted && offByDefault,
                    "native AddFacts plus absence of hidden marker"),
                Assertion("paper-manual-reload", "Move-action Pistol plan loads exact paper identity",
                    observed, actionExact && pistolLoaded && noLooseConsumption,
                    "authoritative plan and atomic manual reload transaction"),
                Assertion("paper-magic-family-state", "named Reliable Pistol shares compatibility and retains two static enchantments",
                    observed, magicCompatible && staticPreserved && brokenRetained,
                    "canonical family definition and item-token replacement"),
                Assertion("paper-mode-unit-isolation",
                    "a second unit remains independently off while the first is active",
                    observed, modeIsolated, "two native activatable facts and marker buffs"),
                Assertion("paper-mode-stock-exhaustion",
                    "zero Paper Cartridge stock does not deactivate the selected mode",
                    observed, exhaustionRetainsMode, "native activatable state independent of inventory"),
                Assertion("paper-advanced-rejection", "Advanced Rifle rejects paper without fallback",
                    observed, advancedRejected,
                    "definition-driven profile compatibility"),
                Assertion("request-local-cleanup", "temporary cartridges, unit, facts, and items restored",
                    observed, cleaned, "guaranteed finally cleanup; no save API"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposablePaperCartridgeModeViewLifecycle()
        {
            Player player = Game.Instance == null ? null : Game.Instance.Player;
            if (player == null || player.Inventory == null)
                throw new InvalidOperationException("The save-free player is unavailable.");
            object party = ReadExactMember(player, "Party");
            object allUnits = ReadExactMember(ReadExactMember(Game.Instance, "State"),
                "AllUnits");
            object[] partyBefore = SnapshotReferences(party);
            object[] unitsBefore = SnapshotReferences(allUnits);
            int paperBefore = player.Inventory.Count(
                BlueprintBootstrap.BasicAmmunition.PaperCartridge);
            UnitEntityData unit = null;
            Kingmaker.EntitySystem.SceneEntitiesState scene = null;
            ActivatableAbility mode = null;
            Buff firstMarker = null, secondMarker = null;
            bool attachedView = false, exactOne = false, firstNoFx = false,
                deactivated = false, reactivated = false, secondNoFx = false,
                stateUnchanged = false, inventoryUnchanged = false, cleaned = false;
            string stage = "spawn-view-backed-unit";
            try
            {
                scene = new Kingmaker.EntitySystem.SceneEntitiesState(
                    "KMG_Paper_Mode_View_Lifecycle");
                unit = Game.Instance.EntityCreator.SpawnUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter, Vector3.zero,
                    Quaternion.identity, scene);
                attachedView = unit != null && unit.View != null && unit.View.Data != null;
                if (!attachedView)
                    throw new InvalidOperationException("Native spawn did not attach a live unit view.");
                unit.Descriptor.AddFact(BlueprintBootstrap.FirearmProficiency);
                mode = unit.Descriptor.ActivatableAbilities.Enumerable.Single(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Ability));

                stage = "activate-and-spawn";
                mode.IsOn = true;
                firstMarker = unit.Descriptor.Buffs.RawFacts.OfType<Buff>().Single(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Marker));
                exactOne = unit.Descriptor.Buffs.RawFacts.OfType<Buff>().Count(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Marker)) == 1;
                firstMarker.SpawnParticleEffect();
                firstMarker.SpawnParticleEffect();
                FieldInfo particle = typeof(Buff).GetField("m_ParticleEffect",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (particle == null) throw new MissingFieldException(
                    typeof(Buff).FullName, "m_ParticleEffect");
                firstNoFx = particle.GetValue(firstMarker) == null;

                stage = "deactivate-reactivate";
                mode.IsOn = false;
                // The blueprint deliberately does not force immediate deactivation;
                // drive the public native stop boundary so this synchronous fixture
                // observes Buff.OnRemove before reactivation.
                mode.Stop(true);
                deactivated = !unit.Descriptor.Buffs.RawFacts.OfType<Buff>().Any(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Marker));
                mode.IsOn = true;
                secondMarker = unit.Descriptor.Buffs.RawFacts.OfType<Buff>().Single(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Marker));
                secondMarker.SpawnParticleEffect();
                reactivated = mode.IsOn && !ReferenceEquals(firstMarker, secondMarker);
                secondNoFx = particle.GetValue(secondMarker) == null;
                stateUnchanged = unit.Body.PrimaryHand.MaybeItem == null &&
                    unit.Body.SecondaryHand.MaybeItem == null;
                inventoryUnchanged = player.Inventory.Count(
                    BlueprintBootstrap.BasicAmmunition.PaperCartridge) == paperBefore;
            }
            catch (Exception exception)
            {
                throw new InvalidOperationException(
                    "Paper mode view lifecycle failed at stage " + stage + ".", exception);
            }
            finally
            {
                if (mode != null && mode.IsOn) mode.IsOn = false;
                if (unit != null) unit.Dispose();
                if (scene != null) scene.Dispose();
                cleaned = SameReferences(partyBefore, SnapshotReferences(party)) &&
                    SameReferences(unitsBefore, SnapshotReferences(allUnits)) &&
                    (unit == null || !ContainsReference(allUnits, unit)) &&
                    player.Inventory.Count(BlueprintBootstrap.BasicAmmunition.PaperCartridge) ==
                        paperBefore;
            }
            string observed = "view=" + attachedView + ";one=" + exactOne +
                ";firstNoFx=" + firstNoFx + ";off=" + deactivated +
                ";reactivated=" + reactivated + ";secondNoFx=" + secondNoFx +
                ";state=" + stateUnchanged + ";inventory=" + inventoryUnchanged +
                ";cleaned=" + cleaned;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("paper-mode-attached-view", "live native UnitEntityView with Data",
                    observed, attachedView, "EntityCreator.SpawnUnit in disposable scene"),
                Assertion("paper-mode-native-particle-lifecycle",
                    "exact marker invokes SpawnParticleEffect twice without exception or FX",
                    observed, exactOne && firstNoFx,
                    "native Buff.SpawnParticleEffect on an attached view"),
                Assertion("paper-mode-reactivation-lifecycle",
                    "deactivation/removal and reactivation remain no-FX and selected",
                    observed, deactivated && reactivated && secondNoFx,
                    "native activatable ownership and Buff removal/spawn paths"),
                Assertion("paper-mode-lifecycle-isolation",
                    "inventory and firearm state unchanged; fixture restored",
                    observed, stateUnchanged && inventoryUnchanged && cleaned,
                    "no save API; disposable scene cleanup"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposablePaperCartridgeFullAttack()
        {
            Player player = Game.Instance == null ? null : Game.Instance.Player;
            if (player == null || player.Inventory == null)
                throw new InvalidOperationException("The save-free player inventory is unavailable.");
            BasicAmmunitionBlueprintSet ammunition = BlueprintBootstrap.BasicAmmunition;
            BlueprintItemWeapon pistol = BlueprintBootstrap.ProductionFirearms.Pistol.Item;
            BlueprintFeature rapidPistol = BlueprintLibraryLookup.RequireExact<BlueprintFeature>(
                BlueprintBootstrap.Library, "070f4f07b5164d8a82d647a93539746d",
                "Rapid Reload (Pistol)");
            var inventory = new KingmakerReloadAmmunitionInventory(player.Inventory,
                ammunition.BlackPowder, ammunition.LeadBall, ammunition.PaperCartridge);
            ReloadAmmunitionInventorySnapshot before =
                ReloadAmmunitionInventorySnapshot.Capture(inventory);
            UnitEntityData unit = null, target = null;
            ItemEntityWeapon weapon = null;
            ActivatableAbility mode = null;
            bool repeated = false, autoOff = false, exhausted = false, cleaned = false;
            string observed = null;
            try
            {
                inventory.Add(ReloadInventoryComponent.PaperCartridge, 3);
                unit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                target = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                unit.Descriptor.AddFact(BlueprintBootstrap.FirearmProficiency);
                unit.Descriptor.AddFact(rapidPistol);
                Kingmaker.UnitLogic.Abilities.Ability reload = unit.Descriptor.Abilities
                    .GetAbility(BlueprintBootstrap.ReloadTestMusketAbility);
                if (reload == null) throw new InvalidOperationException(
                    "The native Reload Firearm auto-use fact was not granted.");
                unit.AutoUseAbility = new AbilityData(reload);
                mode = unit.Descriptor.ActivatableAbilities.Enumerable.Single(value =>
                    ReferenceEquals(value.Blueprint,
                        BlueprintBootstrap.PaperCartridgeMode.Ability));
                mode.IsOn = true;
                weapon = new ItemEntityWeapon(pistol);
                unit.Body.PrimaryHand.InsertItem(weapon);
                var command = new UnitAttack(unit);
                SetDeclaredProperty(command, typeof(UnitCommand), "Executor", unit);
                SetDeclaredProperty(command, typeof(UnitAttack), "IsFullAttack", true);
                SetDeclaredProperty(command, typeof(UnitAttack), "Target", target);
                SetDeclaredProperty(command, typeof(UnitAttack), "LastAttackRule",
                    new RuleAttackWithWeapon(unit, target, weapon, 0));
                var nativeAttacks = new List<AttackHandInfo>
                {
                    new AttackHandInfo(unit.Body.PrimaryHand, 0, 1) { Target = target }
                };
                SetExactField(command, "m_AllAttacks", nativeAttacks);
                SetExactField(command, "m_AttackIndex", 0);
                RuleAttackWithWeapon observedPrevious = command.LastAttackRule;
                AttackHandInfo observedPlanned = command.PlannedAttack;
                ExactEquippedFirearmContext observedFirearm;
                string observedReason;
                bool observedExact = ExactEquippedFirearmResolver.TryResolve(
                    unit.Descriptor, out observedFirearm, out observedReason);
                string nativeBoundary = "isFull=" + command.IsFullAttack +
                    ";executor=" + ReferenceEquals(command.Executor, unit) +
                    ";previous=" + (observedPrevious != null) +
                    ";previousWeapon=" + (observedPrevious != null &&
                        ReferenceEquals(observedPrevious.Weapon, weapon)) +
                    ";planned=" + (observedPlanned != null) +
                    ";plannedWeapon=" + (observedPlanned != null &&
                        ReferenceEquals(observedPlanned.Weapon, weapon)) +
                    ";exact=" + observedExact +
                    ";exactWeapon=" + (observedExact &&
                        ReferenceEquals(observedFirearm.Weapon, weapon)) +
                    ";auto=" + (unit.AutoUseAbility != null &&
                        ReferenceEquals(unit.AutoUseAbility.Blueprint,
                            BlueprintBootstrap.ReloadTestMusketAbility)) +
                    ";reason=" + observedReason;
                int paperStart = inventory.Count(ReloadInventoryComponent.PaperCartridge);
                UnitCommand.ResultType result;
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                bool firstContinues = FreeActionFullAttackReloadPatch.ApplyForRuntimeTest(
                    command, out result);
                bool firstLoaded = FirearmRuntimeState.Service.GetOrCreate(weapon)
                    .Repository.State.LoadedAmmunition ==
                    ReloadAmmunitionProfileCatalog.PaperCartridge.LoadedAmmunition;
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                bool secondContinues = FreeActionFullAttackReloadPatch.ApplyForRuntimeTest(
                    command, out result);
                repeated = firstContinues && secondContinues && firstLoaded &&
                    inventory.Count(ReloadInventoryComponent.PaperCartridge) == paperStart - 2;

                unit.AutoUseAbility = null;
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                int beforeOff = inventory.Count(ReloadInventoryComponent.PaperCartridge);
                bool offContinues = FreeActionFullAttackReloadPatch.ApplyForRuntimeTest(
                    command, out result);
                autoOff = !offContinues && result == UnitCommand.ResultType.Success &&
                    inventory.Count(ReloadInventoryComponent.PaperCartridge) == beforeOff;

                unit.AutoUseAbility = new AbilityData(reload);
                int remaining = inventory.Count(ReloadInventoryComponent.PaperCartridge);
                if (remaining > 0) inventory.Remove(
                    ReloadInventoryComponent.PaperCartridge, remaining);
                FirearmRuntimeState.Service.Set(weapon, FirearmState.CreateEmpty());
                bool exhaustedContinues = FreeActionFullAttackReloadPatch.ApplyForRuntimeTest(
                    command, out result);
                exhausted = !exhaustedContinues && result == UnitCommand.ResultType.Success &&
                    inventory.Count(ReloadInventoryComponent.BlackPowderCharge) ==
                        before.BlackPowderCharges &&
                    inventory.Count(ReloadInventoryComponent.LeadBall) == before.LeadBalls;
                observed = nativeBoundary + ";repeated=" + repeated + ";autoOff=" + autoOff +
                    ";exhausted=" + exhausted + ";attempted=" +
                    FreeActionFullAttackReloadPatch.Attempted + ";succeeded=" +
                    FreeActionFullAttackReloadPatch.Succeeded;
            }
            finally
            {
                if (mode != null && mode.IsOn) mode.IsOn = false;
                if (unit != null) unit.AutoUseAbility = null;
                if (weapon != null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if (unit != null && unit.Body.PrimaryHand.MaybeItem != null)
                        unit.Body.PrimaryHand.RemoveItem(false);
                    weapon.Dispose();
                }
                new ReloadAmmunitionTransactionService().RestoreExact(inventory, before);
                if (unit != null) unit.Dispose();
                if (target != null) target.Dispose();
                cleaned = before.Equals(ReloadAmmunitionInventorySnapshot.Capture(inventory));
            }
            observed = (observed ?? "fixture-failed") + ";cleaned=" + cleaned;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("paper-full-attack-native-boundary",
                    "two planned iterations on one native UnitAttack reload the exact Pistol",
                    observed, repeated,
                    "UnitAttack IsFullAttack/LastAttackRule/PlannedAttack Harmony prefix boundary"),
                Assertion("paper-full-attack-auto-use-control",
                    "auto-use off ends remaining attacks without cartridge consumption",
                    observed, autoOff, "exact native AutoUseAbility identity"),
                Assertion("paper-full-attack-no-fallback",
                    "cartridge exhaustion ends before an empty shot despite loose stock",
                    observed, exhausted, "selected plan availability and no-fallback policy"),
                Assertion("request-local-cleanup", "exact inventory/unit/item restoration",
                    observed, cleaned, "finally restoration; no save API"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposableOverhaulMaintenance()
        {
            BlueprintAbility blueprint = BlueprintBootstrap.OverhaulTestMusketAbility;
            OverhaulTestMusketAbilityLogic logic = blueprint.ComponentsArray
                .OfType<OverhaulTestMusketAbilityLogic>().Single();
            BlueprintItemWeapon pistol = typeof(OverhaulTestMusketAbilityLogic)
                .GetField("m_TestMusket", BindingFlags.Instance |
                    BindingFlags.NonPublic).GetValue(logic) as BlueprintItemWeapon;
            if (pistol == null) throw new InvalidOperationException(
                "Overhaul ability exposed no exact configured firearm.");
            BlueprintItem overhaulKit = typeof(OverhaulTestMusketAbilityLogic)
                .GetField("m_RepairKit", BindingFlags.Instance |
                    BindingFlags.NonPublic).GetValue(logic) as BlueprintItem;
            if (overhaulKit == null) throw new InvalidOperationException(
                "Overhaul ability exposed no exact configured kit.");
            BlueprintItemWeapon magicPistol =
                BlueprintBootstrap.MagicFirearms.Entries[6].Item;
            BlueprintItem repairKit = BlueprintBootstrap.FirearmRepairKit;
            Player player = Game.Instance.Player;
            int kitsBefore = player.Inventory.Count(repairKit);
            int overhaulKitsBefore = player.Inventory.Count(overhaulKit);
            Kingmaker.EntitySystem.Entities.UnitEntityData unit = null;
            ItemEntityWeapon weapon = null;
            IEnumerator<AbilityDeliveryTarget> delivery = null;
            bool delayed = false, interruptionAtomic = false,
                combatBlocked = false, exactCompletion = false,
                repairCompletion = false, cleaned = false;
            int staticBefore = -1, staticAfterOverhaul = -1,
                staticAfterRepair = -1;
            long conditionLogsBefore = FirearmConditionCombatLog.Published;
            string overhaulLog = null, repairLog = null;
            try
            {
                object ignored;
                string method;
                if (!ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                    new[] { new object[] { repairKit, 2 }, new object[] { repairKit } },
                    out ignored, out method))
                    throw new InvalidOperationException(
                        "Temporary Firearm Repair Kit could not be added.");
                if (!ReflectionAccess.TryInvokeAny(player.Inventory, new[] { "Add" },
                    new[] { new object[] { overhaulKit, 1 },
                        new object[] { overhaulKit } }, out ignored, out method))
                    throw new InvalidOperationException(
                        "Temporary Overhaul Kit could not be added.");
                unit = new Kingmaker.UI.LevelUp.ChargenUnit(
                    BlueprintRoot.Instance.DefaultPlayerCharacter).Unit;
                weapon = new ItemEntityWeapon(pistol);
                unit.Body.PrimaryHand.InsertItem(weapon);
                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Wrecked));
                unit.Descriptor.AddFact(blueprint);
                Kingmaker.UnitLogic.Abilities.Ability granted =
                    unit.Descriptor.Abilities.GetAbility(blueprint);
                if (granted == null)
                    throw new InvalidOperationException(
                        "Kingmaker did not retain the granted Overhaul Firearm fact.");
                var data = new Kingmaker.UnitLogic.Abilities.AbilityData(granted);
                var context = new Kingmaker.UnitLogic.Abilities.AbilityExecutionContext(
                    data, new Kingmaker.UnitLogic.Abilities.AbilityParams(),
                    new TargetWrapper(unit), null);
                int kitsAtStart = player.Inventory.Count(repairKit);
                int overhaulKitsAtStart = player.Inventory.Count(overhaulKit);
                delivery = logic.Deliver(context, new TargetWrapper(unit));
                delayed = delivery.MoveNext() && delivery.Current == null;
                delivery.Dispose();
                delivery = null;
                interruptionAtomic = player.Inventory.Count(repairKit) == kitsAtStart &&
                    player.Inventory.Count(overhaulKit) == overhaulKitsAtStart &&
                    FirearmRuntimeState.Service.GetOrCreate(weapon).Repository.State
                        .Condition == FirearmCondition.Wrecked;

                var combat = new Kingmaker.Controllers.Combat.UnitCombatState(unit);
                SetExactField(combat, "m_InCombat", true);
                SetExactProperty(unit, "CombatState", combat);
                combatBlocked = unit.IsInCombat && !logic.IsAvailableFor(data) &&
                    OverhaulTestMusketRuntime.Evaluate(unit.Descriptor, pistol,
                        overhaulKit)
                        .Reason.IndexOf("out of combat",
                            StringComparison.OrdinalIgnoreCase) >= 0;
                SetExactProperty(unit, "CombatState", null);

                FirearmRuntimeState.Service.Forget(weapon);
                unit.Body.PrimaryHand.RemoveItem(false);
                weapon.Dispose();
                weapon = new ItemEntityWeapon(magicPistol);
                unit.Body.PrimaryHand.InsertItem(weapon);
                staticBefore = weapon.Enchantments.Count(value => value != null &&
                    entryBlueprint(weapon, value.Blueprint));
                FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Wrecked));

                FirearmOverhaulRuntimeResult completed =
                    OverhaulTestMusketRuntime.Execute(unit.Descriptor, magicPistol,
                        overhaulKit);
                exactCompletion = completed.Succeeded &&
                    completed.BeforeFirearm.Repository.State.Condition == FirearmCondition.Wrecked &&
                    completed.AfterFirearm.Repository.State.Condition == FirearmCondition.Broken &&
                    player.Inventory.Count(overhaulKit) == overhaulKitsAtStart - 1;
                staticAfterOverhaul = weapon.Enchantments.Count(value =>
                    value != null && entryBlueprint(weapon, value.Blueprint));
                overhaulLog = FirearmConditionCombatLog.LastMessage;
                FirearmRepairRuntimeResult repaired =
                    RepairTestMusketRuntime.Execute(
                        unit.Descriptor, magicPistol, repairKit);
                repairCompletion = repaired.Succeeded &&
                    repaired.BeforeFirearm.Repository.State.Condition ==
                        FirearmCondition.Broken &&
                    repaired.AfterFirearm.Repository.State.Condition ==
                        FirearmCondition.Normal &&
                    player.Inventory.Count(repairKit) == kitsAtStart - 1;
                staticAfterRepair = weapon.Enchantments.Count(value =>
                    value != null && entryBlueprint(weapon, value.Blueprint));
                repairLog = FirearmConditionCombatLog.LastMessage;
            }
            finally
            {
                if (delivery != null) delivery.Dispose();
                if (unit != null) SetExactProperty(unit, "CombatState", null);
                if (weapon != null)
                {
                    FirearmRuntimeState.Service.Forget(weapon);
                    if (unit != null && unit.Body.PrimaryHand.MaybeItem != null)
                        unit.Body.PrimaryHand.RemoveItem(false);
                    weapon.Dispose();
                }
                int excess = player.Inventory.Count(repairKit) - kitsBefore;
                if (excess > 0) player.Inventory.Remove(repairKit, excess);
                int overhaulExcess = player.Inventory.Count(overhaulKit) -
                    overhaulKitsBefore;
                if (overhaulExcess > 0)
                    player.Inventory.Remove(overhaulKit, overhaulExcess);
                if (unit != null) unit.Dispose();
                cleaned = player.Inventory.Count(repairKit) == kitsBefore &&
                    player.Inventory.Count(overhaulKit) == overhaulKitsBefore;
            }
            string observed = "duration=" + blueprint.LocalizedDuration +
                ";delayed=" + delayed + ";interruptionAtomic=" + interruptionAtomic +
                ";combatBlocked=" + combatBlocked + ";completed=" + exactCompletion +
                ";repaired=" + repairCompletion + ";cleaned=" + cleaned +
                ";static=" + staticBefore + "," + staticAfterOverhaul + "," +
                staticAfterRepair +
                ";conditionLogs=" +
                (FirearmConditionCombatLog.Published - conditionLogsBefore) +
                ";overhaulLog=" + overhaulLog + ";repairLog=" + repairLog;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("overhaul-one-minute-delay",
                    "duration=1 minute and first delivery tick mutates nothing",
                    observed, blueprint.LocalizedDuration.ToString() == "1 minute" && delayed &&
                        interruptionAtomic,
                    "game-time iterator before exact transaction"),
                Assertion("overhaul-combat-gate", "unavailable while unit is in combat",
                    observed, combatBlocked,
                    "UnitEntityData.IsInCombat availability and delivery recheck"),
                Assertion("overhaul-atomic-completion", "same item Wrecked->Broken; one kit",
                    observed, exactCompletion,
                    "existing exact-item atomic transaction after maintenance gate"),
                Assertion("magic-static-maintenance-lifecycle",
                    "The Last Word retains +5, Reliable, and Seeking through Overhaul and Repair",
                    observed, staticBefore == 3 && staticAfterOverhaul == 3 &&
                        staticAfterRepair == 3,
                    "exact runtime static-enchantment identities across state-token replacement"),
                Assertion("overhaul-condition-combat-log",
                    "one native player log only after completed Wrecked -> Broken",
                    observed,
                    overhaulLog != null && overhaulLog.Contains(
                        "Wrecked -> Broken (Overhaul Firearm)"),
                    "IWarningNotificationUIHandler event consumed by BattleLogManager"),
                Assertion("repair-condition-combat-log",
                    "completed Broken -> Normal consumes second kit and logs once",
                    observed,
                    repairCompletion &&
                    FirearmConditionCombatLog.Published == conditionLogsBefore + 2 &&
                    repairLog != null && repairLog.Contains(
                        "Broken -> Normal (Repair Firearm)"),
                    "exact repair transaction and native warning/log event"),
                Assertion("request-local-cleanup", "repair-kit inventory and fixture restored",
                    observed, cleaned, "guaranteed finally cleanup; no save API"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunVendorTableContractObservation()
        {
            string vendorLogicContract = DescribeCreationType(typeof(VendorLogic));
            const BindingFlags Flags = BindingFlags.Instance |
                BindingFlags.Public | BindingFlags.NonPublic;
            FieldInfo tableField = typeof(AddSharedVendor).GetField("m_Table", Flags);
            FieldInfo lootField = typeof(AddVendorItems).GetField("m_Loot", Flags);
            FieldInfo fixedItemField = typeof(LootItemsPackFixed).GetField("m_Item", Flags);
            FieldInfo fixedCountField = typeof(LootItemsPackFixed).GetField("m_Count", Flags);
            BlueprintSharedVendorTable[] tables = BlueprintBootstrap.Library
                .GetAllBlueprints().OfType<BlueprintSharedVendorTable>()
                .OrderBy(value => value.AssetGuid, StringComparer.Ordinal).ToArray();
            var tableSet = new HashSet<BlueprintSharedVendorTable>(tables);
            var records = new List<string>();
            var ownerRecords = new List<string>();
            var capitalEntries = new List<string>();
            var capitalReferenceContracts = new HashSet<string>(StringComparer.Ordinal);
            var fixedEntryPatterns = new Dictionary<string, int>(StringComparer.Ordinal);
            var enchantmentRecords = new List<string>();
            var lootCandidateRecords = new List<string>();
            int projectEntries = 0, invalidProjectCounts = 0, blunderbussEntries = 0;
            int btslTables = 0, btslEntries = 0, invalidBtslCounts = 0;
            int associations = 0, invalidAssociations = 0, supplementalLoot = 0;
            ProductionFirearmBlueprintCatalog production =
                BlueprintBootstrap.ProductionFirearms;
            string criticalProfiles = production == null ? "catalog-unavailable" :
                DescribeCriticalProfile("pistol", production.Pistol.WeaponType) + ";" +
                DescribeCriticalProfile("musket", production.Musket.WeaponType) + ";" +
                DescribeCriticalProfile("blunderbuss",
                    production.Blunderbuss.WeaponType) + ";" +
                DescribeCriticalProfile("rifle",
                    production.AdvancedRifle.WeaponType) + ";" +
                DescribeCriticalProfile("revolver",
                    production.AdvancedRevolver.WeaponType);
            foreach (BlueprintScriptableObject owner in BlueprintBootstrap.Library
                .GetAllBlueprints().Where(value => value != null))
            {
                foreach (AddSharedVendor component in (owner.ComponentsArray ??
                    Array.Empty<BlueprintComponent>()).OfType<AddSharedVendor>())
                {
                    var table = tableField == null ? null :
                        tableField.GetValue(component) as BlueprintSharedVendorTable;
                    ownerRecords.Add("owner=" + owner.GetType().FullName + ":" +
                        owner.name + ":" + owner.AssetGuid + ";table=" +
                        (table == null ? "<null>" : table.name + ":" +
                            table.AssetGuid));
                }
            }
            BlueprintScriptableObject[] allBlueprints = BlueprintBootstrap.Library
                .GetAllBlueprints().Where(value => value != null).ToArray();
            BlueprintWeaponEnchantment[] nativeEnchantments = allBlueprints
                .OfType<BlueprintWeaponEnchantment>()
                .Where(IsRareFirearmNativeEnchantmentCandidate)
                .OrderBy(value => value.name, StringComparer.Ordinal).ToArray();
            FieldInfo enchantmentsField = typeof(BlueprintItemWeapon).GetField(
                "m_Enchantments", Flags);
            foreach (BlueprintWeaponEnchantment enchantment in nativeEnchantments)
            {
                string[] donors = enchantmentsField == null ? Array.Empty<string>() :
                    allBlueprints.OfType<BlueprintItemWeapon>().Where(item =>
                    {
                        var values = enchantmentsField.GetValue(item) as
                            BlueprintWeaponEnchantment[];
                        return values != null && values.Any(value =>
                            ReferenceEquals(value, enchantment));
                    }).OrderBy(item => item.name, StringComparer.Ordinal)
                    .Take(12).Select(item => item.name + ":" + item.AssetGuid)
                    .ToArray();
                enchantmentRecords.Add("enchantment=" + enchantment.name + ":" +
                    enchantment.AssetGuid + ";display=" + enchantment.Name +
                    ";cost=" + enchantment.EnchantmentCost + ";components=" +
                    DescribeBlueprintComponents(enchantment) + ";componentValues=" +
                    DescribeComponentScalarContracts(enchantment.ComponentsArray) +
                    ";donors=" +
                    string.Join(",", donors));
            }
            BlueprintScriptableObject[] lootCandidates = allBlueprints.Where(value =>
                (value is BlueprintLoot || value is BlueprintUnitLoot) &&
                IsRareFirearmLootCandidate(value)).OrderBy(value => value.name,
                    StringComparer.Ordinal).ThenBy(value => value.AssetGuid,
                    StringComparer.Ordinal).ToArray();
            Dictionary<string, List<string>> lootReferences =
                BuildDirectBlueprintReferenceIndex(allBlueprints, lootCandidates);
            Dictionary<string, List<string>> vendorReferences =
                BuildDirectBlueprintReferenceIndex(allBlueprints, tables);
            foreach (BlueprintScriptableObject candidate in lootCandidates)
            {
                var loot = candidate as BlueprintLoot;
                string fixedItems = loot == null ? DescribeFixedLootComponents(candidate) :
                    string.Join(",", (loot.Items ?? Array.Empty<LootEntry>())
                        .Where(entry => entry != null).Select(entry =>
                            (entry.Item == null ? "<null>" : entry.Item.name + ":" +
                                entry.Item.AssetGuid) + "*" + entry.Count).ToArray());
                string area = loot == null || loot.Area == null ? "<none>" :
                    loot.Area.name + ":" + loot.Area.AssetGuid;
                string container = loot == null ? "<unit-loot>" :
                    loot.ContainerName ?? string.Empty;
                List<string> indexedReferences;
                string[] references = lootReferences.TryGetValue(candidate.AssetGuid,
                    out indexedReferences) ? indexedReferences.Take(20).ToArray() :
                    Array.Empty<string>();
                lootCandidateRecords.Add("loot=" + candidate.GetType().FullName +
                    ":" + candidate.name + ":" + candidate.AssetGuid + ";area=" +
                    area + ";container=" + container + ";setting=" +
                    (loot == null ? "<unit-loot>" : loot.Setting.ToString()) +
                    ";contents=" + fixedItems + ";components=" +
                    DescribeBlueprintComponents(candidate) + ";references=" +
                    references.Length + ":" + string.Join(",", references));
            }
            foreach (BlueprintUnit unit in BlueprintBootstrap.Library.GetAllBlueprints()
                .OfType<BlueprintUnit>().OrderBy(value => value.AssetGuid,
                    StringComparer.Ordinal))
            {
                BlueprintComponent[] components =
                    (unit.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .Concat((unit.AddFacts ?? Array.Empty<BlueprintUnitFact>())
                        .Where(value => value != null)
                        .SelectMany(value => value.ComponentsArray ??
                            Array.Empty<BlueprintComponent>())).ToArray();
                AddSharedVendor[] shared = components.OfType<AddSharedVendor>().ToArray();
                if (shared.Length == 0) continue;
                var linkedTables = new List<string>();
                foreach (AddSharedVendor component in shared)
                {
                    var table = tableField == null ? null :
                        tableField.GetValue(component) as BlueprintSharedVendorTable;
                    associations++;
                    if (table == null || !tableSet.Contains(table))
                        invalidAssociations++;
                    linkedTables.Add(table == null ? "<null>" :
                        table.name + ":" + table.AssetGuid + ":" +
                        DescribeBlueprintComponents(table));
                }
                var linkedLoot = new List<string>();
                foreach (AddVendorItems component in components.OfType<AddVendorItems>())
                {
                    var loot = lootField == null ? null :
                        lootField.GetValue(component) as BlueprintUnitLoot;
                    supplementalLoot++;
                    linkedLoot.Add(loot == null ? "<null>" :
                        loot.name + ":" + loot.AssetGuid + ":" +
                        DescribeBlueprintComponents(loot));
                }
                records.Add("unit=" + unit.name + ";display=" +
                    unit.CharacterName + ";guid=" + unit.AssetGuid + ";tables=" +
                    string.Join(",", linkedTables.ToArray()) + ";loot=" +
                    string.Join(",", linkedLoot.ToArray()));
            }
            records.Sort(StringComparer.Ordinal);
            ownerRecords.Sort(StringComparer.Ordinal);
            BlueprintSharedVendorTable capitalTable = tables.SingleOrDefault(value =>
                string.Equals(value.AssetGuid,
                    CapitalVendorBlueprints.TableGuid, StringComparison.Ordinal));
            if (capitalTable != null && fixedItemField != null && fixedCountField != null)
            {
                foreach (LootItemsPackFixed component in
                    (capitalTable.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<LootItemsPackFixed>())
                {
                    object itemReference = fixedItemField.GetValue(component);
                    object count = fixedCountField.GetValue(component);
                    Type referenceType = itemReference == null ? null :
                        itemReference.GetType();
                    PropertyInfo itemProperty = referenceType == null ? null :
                        referenceType.GetProperty("Item", Flags);
                    var item = itemProperty == null ? null :
                        itemProperty.GetValue(itemReference, null) as BlueprintItem;
                    capitalEntries.Add("item=" + (item == null ? "<null>" :
                        item.name + ":" + item.AssetGuid + ":cost=" + item.Cost +
                        ":stackable=" + item.IsActuallyStackable) + ":reference=" +
                        (referenceType == null ? "<null>" : referenceType.FullName) +
                        ":count=" + count);
                    if (referenceType != null)
                    {
                        capitalReferenceContracts.Add("declared=" +
                            fixedItemField.FieldType.FullName + ";runtime=" +
                            referenceType.FullName + ";properties=" + string.Join(",",
                                referenceType.GetProperties(Flags)
                                    .OrderBy(value => value.Name, StringComparer.Ordinal)
                                    .Select(value => value.Name + ":" +
                                        value.PropertyType.FullName).ToArray()) +
                            ";methods=" + string.Join(",",
                                referenceType.GetMethods(Flags)
                                    .Where(value => value.GetParameters().Length == 0)
                                    .OrderBy(value => value.Name, StringComparer.Ordinal)
                                    .Select(value => value.Name + ":" +
                                        value.ReturnType.FullName).ToArray()));
                    }
                }
                var expectedProjectItems = new Dictionary<BlueprintItem, int>
                {
                    { BlueprintBootstrap.ProductionFirearms.Pistol.Item, 1 },
                    { BlueprintBootstrap.ProductionFirearms.Musket.Item, 1 },
                    { BlueprintBootstrap.ProductionFirearms.Blunderbuss.Item, 1 },
                    { BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.PistolPlus1Symbol).Item, 1 },
                    { BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.MusketPlus1Symbol).Item, 1 },
                    { BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.BlunderbussPlus1Symbol).Item, 1 },
                    { BlueprintBootstrap.BasicAmmunition.BlackPowder, 200 },
                    { BlueprintBootstrap.BasicAmmunition.LeadBall, 200 },
                    { BlueprintBootstrap.BasicAmmunition.PaperCartridge, 200 },
                    { BlueprintBootstrap.FirearmRepairKit, 10 },
                    { BlueprintBootstrap.GunsmithingSupplies.OverhaulKit, 5 },
                    { BlueprintBootstrap.GunsmithingSupplies.GunsmithKit, 1 }
                };
                foreach (LootItemsPackFixed component in
                    (capitalTable.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<LootItemsPackFixed>())
                {
                    BlueprintItem item = CapitalVendorBlueprints.ReadItem(component);
                    int expectedCount;
                    if (item != null && expectedProjectItems.TryGetValue(item,
                        out expectedCount))
                    {
                        projectEntries++;
                        if (CapitalVendorBlueprints.ReadCount(component) != expectedCount)
                            invalidProjectCounts++;
                    }
                    if (ReferenceEquals(item,
                        BlueprintBootstrap.ProductionFirearms.Blunderbuss.Item))
                        blunderbussEntries++;
                }
            }
            var btslExpected = new Dictionary<BlueprintItem, int>
            {
                { production.Pistol.Item, 1 }, { production.Musket.Item, 1 },
                { production.Blunderbuss.Item, 1 },
                { BlueprintBootstrap.MagicFirearms.Require(
                    MagicFirearmBlueprints.PistolPlus1Symbol).Item, 1 },
                { BlueprintBootstrap.MagicFirearms.Require(
                    MagicFirearmBlueprints.MusketPlus1Symbol).Item, 1 },
                { BlueprintBootstrap.MagicFirearms.Require(
                    MagicFirearmBlueprints.BlunderbussPlus1Symbol).Item, 1 },
                { BlueprintBootstrap.BasicAmmunition.BlackPowder, 200 },
                { BlueprintBootstrap.BasicAmmunition.LeadBall, 200 },
                { BlueprintBootstrap.BasicAmmunition.PaperCartridge, 200 },
                { BlueprintBootstrap.FirearmRepairKit, 10 },
                { BlueprintBootstrap.GunsmithingSupplies.OverhaulKit, 5 },
                { BlueprintBootstrap.GunsmithingSupplies.GunsmithKit, 1 }
            };
            foreach (string guid in BeneathStolenLandsVendorBlueprints.TableGuids)
            {
                BlueprintSharedVendorTable table = tables.SingleOrDefault(value =>
                    string.Equals(value.AssetGuid, guid, StringComparison.Ordinal));
                if (table == null) continue;
                btslTables++;
                foreach (KeyValuePair<BlueprintItem, int> expected in btslExpected)
                {
                    LootItemsPackFixed[] matches = (table.ComponentsArray ??
                        Array.Empty<BlueprintComponent>()).OfType<LootItemsPackFixed>()
                        .Where(value => ReferenceEquals(
                            CapitalVendorBlueprints.ReadItem(value), expected.Key)).ToArray();
                    btslEntries += matches.Length;
                    if (matches.Length != 1 || CapitalVendorBlueprints.ReadCount(
                        matches[0]) != expected.Value) invalidBtslCounts++;
                }
            }
            BlueprintItem[] btslSpearItems = BlueprintBootstrap.ElvenBranchedSpears
                .Entries.Select(value => (BlueprintItem)value.Item).ToArray();
            int btslSpearTables = 0, btslSpearEntries = 0,
                invalidBtslSpearCounts = 0;
            var btslSpearRecords = new List<string>();
            for (int index = 0;
                index < BeneathStolenLandsVendorBlueprints.TableGuids.Length;
                index++)
            {
                BlueprintSharedVendorTable table = tables.SingleOrDefault(value =>
                    string.Equals(value.AssetGuid,
                        BeneathStolenLandsVendorBlueprints.TableGuids[index],
                        StringComparison.Ordinal));
                if (table == null) continue;
                btslSpearTables++;
                int validRows = 0;
                foreach (BlueprintItem item in btslSpearItems)
                {
                    LootItemsPackFixed[] matches = (table.ComponentsArray ??
                        Array.Empty<BlueprintComponent>()).OfType<LootItemsPackFixed>()
                        .Where(value => ReferenceEquals(
                            CapitalVendorBlueprints.ReadItem(value), item)).ToArray();
                    btslSpearEntries += matches.Length;
                    if (matches.Length == 1 &&
                        CapitalVendorBlueprints.ReadCount(matches[0]) == 1)
                        validRows++;
                    else invalidBtslSpearCounts++;
                }
                btslSpearRecords.Add(table.name + ":" + table.AssetGuid +
                    ";mode=" + (index < 2 ? "standalone" : "campaign") +
                    ";validRows=" + validRows + "/6");
            }
            EasternWeaponBlueprintSet eastern = BlueprintBootstrap.EasternWeapons;
            bool expectedEasternCommerce =
                _context.FeatureModules.Active.EasternWeapons;
            BlueprintItem[] easternOwned = eastern.Entries.Select(value =>
                    (BlueprintItem)value.Item).Concat(eastern.Named.Entries.Select(
                        value => (BlueprintItem)value.Item)).ToArray();
            var easternVendorRecords = new List<string>();
            var easternPlacedKinds = new List<EasternWeaponNamedKind>();
            int easternVendorTargets = 0, easternVendorRows = 0,
                invalidEasternVendorRows = 0, easternBtslTables = 0,
                easternBtslRows = 0, easternNamedBtslRows = 0;
            foreach (EasternVendorSpec spec in
                EasternWeaponCampaignBlueprints.VendorSpecs)
            {
                BlueprintSharedVendorTable table = tables.SingleOrDefault(value =>
                    string.Equals(value.AssetGuid, spec.Guid,
                        StringComparison.Ordinal));
                if (table == null && spec.Optional) continue;
                easternVendorTargets++;
                if (table == null || !string.Equals(table.name, spec.Name,
                        StringComparison.Ordinal))
                {
                    invalidEasternVendorRows++;
                    easternVendorRecords.Add(spec.Guid + ":identity-mismatch");
                    continue;
                }
                BlueprintItem[] desired = expectedEasternCommerce ?
                    EasternWeaponCatalog.AllGenericItems.Where(value =>
                        spec.GenericKinds.Contains(value.Kind)).Select(value =>
                            (BlueprintItem)eastern.Require(value.Family,
                                value.Kind).Item).Concat(spec.NamedKinds.Select(
                                    value => (BlueprintItem)eastern.Named.Require(
                                        value).Item)).ToArray() :
                    Array.Empty<BlueprintItem>();
                LootItemsPackFixed[] fixedRows = (table.ComponentsArray ??
                    Array.Empty<BlueprintComponent>()).OfType<
                        LootItemsPackFixed>().ToArray();
                int valid = 0;
                foreach (BlueprintItem item in desired)
                {
                    LootItemsPackFixed[] matches = fixedRows.Where(value =>
                        ReferenceEquals(CapitalVendorBlueprints.ReadItem(value),
                            item)).ToArray();
                    if (matches.Length == 1 &&
                        CapitalVendorBlueprints.ReadCount(matches[0]) == 1)
                        valid++;
                    else invalidEasternVendorRows++;
                }
                int unexpected = fixedRows.Count(value => easternOwned.Contains(
                    CapitalVendorBlueprints.ReadItem(value)) && !desired.Contains(
                        CapitalVendorBlueprints.ReadItem(value)));
                invalidEasternVendorRows += unexpected;
                easternVendorRows += valid;
                if (expectedEasternCommerce)
                    easternPlacedKinds.AddRange(spec.NamedKinds);
                if (spec.IsBtsl)
                {
                    easternBtslTables++;
                    easternBtslRows += valid;
                    easternNamedBtslRows += fixedRows.Count(value =>
                        eastern.Named.Entries.Any(named => ReferenceEquals(
                            named.Item, CapitalVendorBlueprints.ReadItem(value))));
                }
                easternVendorRecords.Add(spec.Name + ":" + spec.Guid +
                    ";mode=" + spec.Mode + ";valid=" + valid + "/" +
                    desired.Length + ";unexpected=" + unexpected);
            }
            var easternLootRecords = new List<string>();
            int easternLootTargets = 0, easternLootRows = 0,
                invalidEasternLootRows = 0;
            foreach (EasternLootSpec spec in EasternWeaponCampaignBlueprints.LootSpecs)
            {
                BlueprintLoot loot = allBlueprints.OfType<BlueprintLoot>()
                    .SingleOrDefault(value => string.Equals(value.AssetGuid,
                        spec.Guid, StringComparison.Ordinal));
                BlueprintItem[] desired = expectedEasternCommerce ?
                    spec.NamedKinds.Select(value => (BlueprintItem)eastern.Named
                        .Require(value).Item).ToArray() :
                    Array.Empty<BlueprintItem>();
                LootEntry[] rows = loot == null ? Array.Empty<LootEntry>() :
                    (loot.Items ?? Array.Empty<LootEntry>());
                int valid = 0;
                foreach (BlueprintItem item in desired)
                {
                    LootEntry[] matches = rows.Where(value => value != null &&
                        ReferenceEquals(value.Item, item)).ToArray();
                    if (matches.Length == 1 && matches[0].Count == 1) valid++;
                    else invalidEasternLootRows++;
                }
                int unexpected = rows.Count(value => value != null &&
                    easternOwned.Contains(value.Item) && !desired.Contains(value.Item));
                bool identity = loot != null && string.Equals(loot.name, spec.Name,
                    StringComparison.Ordinal) && loot.Area != null && string.Equals(
                        loot.Area.name, spec.AreaName, StringComparison.Ordinal);
                if (!identity) invalidEasternLootRows++;
                invalidEasternLootRows += unexpected;
                easternLootTargets++;
                easternLootRows += valid;
                if (expectedEasternCommerce)
                    easternPlacedKinds.AddRange(spec.NamedKinds);
                easternLootRecords.Add(spec.Name + ":" + spec.Guid + ":" +
                    spec.AreaName + ";band=" + spec.Band + ";valid=" + valid +
                    "/" + desired.Length + ";identity=" + identity +
                    ";unexpected=" + unexpected);
            }
            BlueprintItem[] namedItems = BlueprintBootstrap.MagicFirearms.Entries
                .Where(value => value.Spec.Symbol != MagicFirearmBlueprints.PistolPlus1Symbol &&
                    value.Spec.Symbol != MagicFirearmBlueprints.MusketPlus1Symbol &&
                    value.Spec.Symbol != MagicFirearmBlueprints.BlunderbussPlus1Symbol)
                .Select(value => (BlueprintItem)value.Item).ToArray();
            BlueprintItem[] bannedManaged = namedItems.Concat(new BlueprintItem[] {
                production.AdvancedRifle.Item, production.AdvancedRevolver.Item })
                .ToArray();
            BlueprintSharedVendorTable[] managedTables = tables.Where(value =>
                value.AssetGuid == CapitalVendorBlueprints.TableGuid ||
                BeneathStolenLandsVendorBlueprints.TableGuids.Contains(value.AssetGuid))
                .ToArray();
            int bannedManagedEntries = managedTables.Sum(table =>
                (table.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<LootItemsPackFixed>().Count(value =>
                        bannedManaged.Contains(CapitalVendorBlueprints.ReadItem(value))));
            BlueprintSharedVendorTable jhod = tables.SingleOrDefault(value =>
                value.AssetGuid == "afa2c7f292b8e1c4d9c835f0e8047dd3");
            BlueprintItem[] allProjectFirearms = production.Entries.Select(value =>
                (BlueprintItem)value.Item).Concat(BlueprintBootstrap.MagicFirearms.Entries
                    .Select(value => (BlueprintItem)value.Item)).ToArray();
            int jhodProjectEntries = jhod == null ? -1 :
                (jhod.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<LootItemsPackFixed>().Count(value => allProjectFirearms
                        .Contains(CapitalVendorBlueprints.ReadItem(value)));
            string[] rareLootGuids = { "193b1222846a0114197e716cb35d3ce8",
                "b34367a637010f743815aed5875152bd",
                "485300a2036a763499aa77ebac1f83c6",
                "36d315a81b36980438e2ef1a866791d1",
                "5a9b9e4b884ae064fa7caa5a13eab065" };
            string[] rareLootNames = { "Forest_cache",
                "PoorHuman_IrovettiChambers_ChestHuge_Outline (3)",
                "Forest_PoorLoot_PuzzleItem3_Instrument",
                "FirstWorld_BasementGoodLoot01",
                "FirstWorld_VeryGoodHiddenLoot02" };
            string[] rareLootAreas = { "VordakaiTombLevel2", "IrovettiPalace",
                "IrovettiPalace", "HouseAtTheEdgeOfTime_Basement",
                "HouseAtTheEdgeOfTime" };
            var rareLootRecords = new List<string>();
            int validRareLoot = 0;
            for (int index = 0; index < rareLootGuids.Length; index++)
            {
                BlueprintLoot loot = allBlueprints.OfType<BlueprintLoot>()
                    .SingleOrDefault(value => value.AssetGuid == rareLootGuids[index]);
                LootEntry[] matches = loot == null ? new LootEntry[0] :
                    (loot.Items ?? new LootEntry[0]).Where(value => value != null &&
                        ReferenceEquals(value.Item, namedItems[index])).ToArray();
                bool valid = loot != null && loot.name == rareLootNames[index] &&
                    loot.Area != null && loot.Area.name == rareLootAreas[index] &&
                    matches.Length == 1 && matches[0].Count == 1;
                if (valid) validRareLoot++;
                rareLootRecords.Add(rareLootGuids[index] + ":" +
                    (loot == null ? "<missing>" : loot.name + ":" +
                        (loot.Area == null ? "<no-area>" : loot.Area.name)) +
                    ":matches=" + matches.Length +
                    ":valid=" + valid);
            }
            if (fixedItemField != null && fixedCountField != null)
            {
                foreach (BlueprintSharedVendorTable table in tables)
                {
                    foreach (LootItemsPackFixed component in
                        (table.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                        .OfType<LootItemsPackFixed>())
                    {
                        object reference = fixedItemField.GetValue(component);
                        PropertyInfo property = reference == null ? null :
                            reference.GetType().GetProperty("Item", Flags);
                        var item = property == null ? null :
                            property.GetValue(reference, null) as BlueprintItem;
                        object count = fixedCountField.GetValue(component);
                        string key = item == null ? "<null>" :
                            "stackable=" + item.IsActuallyStackable + ":count=" + count;
                        int frequency;
                        fixedEntryPatterns.TryGetValue(key, out frequency);
                        fixedEntryPatterns[key] = frequency + 1;
                    }
                }
            }
            string catalog = string.Join(" | ", tables.Select(value =>
                value.name + ":" + value.AssetGuid + ":" +
                DescribeBlueprintComponents(value)).ToArray());
            string observed = vendorLogicContract + ";tables=" + tables.Length + ";associations=" +
                associations + ";invalid=" + invalidAssociations +
                ";supplementalLoot=" + supplementalLoot + ";projectEntries=" +
                projectEntries + ";invalidProjectCounts=" + invalidProjectCounts +
                ";blunderbussEntries=" + blunderbussEntries +
                ";btslTables=" + btslTables + ";btslEntries=" + btslEntries +
                    ";invalidBtslCounts=" + invalidBtslCounts +
                ";btslSpearTables=" + btslSpearTables +
                    ";btslSpearEntries=" + btslSpearEntries +
                    ";invalidBtslSpearCounts=" + invalidBtslSpearCounts +
                ";btslSpearRecords=" + string.Join(" | ",
                        btslSpearRecords.ToArray()) +
                ";expectedEasternCommerce=" + expectedEasternCommerce +
                    ";easternVendors=" + easternVendorRows + "/" +
                    easternVendorTargets + ";invalidEasternVendors=" +
                    invalidEasternVendorRows + ";easternBtsl=" +
                    easternBtslRows + "/" + easternBtslTables +
                    ";easternNamedBtsl=" + easternNamedBtslRows +
                    ";easternLoot=" + easternLootRows + "/" +
                    easternLootTargets + ";invalidEasternLoot=" +
                    invalidEasternLootRows + ";easternVendorRecords=" +
                    string.Join(" | ", easternVendorRecords.ToArray()) +
                    ";easternLootRecords=" + string.Join(" | ",
                        easternLootRecords.ToArray()) +
                ";bannedManagedEntries=" + bannedManagedEntries +
                ";jhodProjectEntries=" + jhodProjectEntries +
                ";validRareLoot=" + validRareLoot + ";rareLoot=" +
                    string.Join(" | ", rareLootRecords.ToArray()) +
                ";criticalProfiles=" + criticalProfiles + ";catalog=" + catalog +
                ";owners=" + string.Join(" | ",
                    ownerRecords.ToArray()) + ";capitalEntries=" + string.Join(" | ",
                    capitalEntries.ToArray()) + ";capitalReferenceContracts=" +
                    string.Join(" | ", capitalReferenceContracts.OrderBy(value => value,
                        StringComparer.Ordinal).ToArray()) + ";fixedEntryPatterns=" +
                    string.Join(" | ", fixedEntryPatterns.OrderBy(value => value.Key,
                        StringComparer.Ordinal).Select(value => value.Key + ":frequency=" +
                            value.Value).ToArray()) + ";records=" +
                    string.Join(" | ", records.ToArray());
            observed += ";nativeEnchantments=" + string.Join(" | ",
                enchantmentRecords.ToArray()) + ";lootCandidates=" + string.Join(
                    " | ", lootCandidateRecords.ToArray()) +
                ";vendorDirectReferences=" + string.Join(" | ", tables.Select(table =>
                {
                    List<string> references;
                    return table.name + ":" + table.AssetGuid + "=" +
                        (vendorReferences.TryGetValue(table.AssetGuid, out references) ?
                            string.Join(",", references.Take(30).ToArray()) : string.Empty);
                }).ToArray());
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("vendor-table-catalog",
                    "nonempty stable shared-vendor table catalog", observed,
                    tableField != null && lootField != null && tables.Length > 0 &&
                        tables.All(value => value != null &&
                            !string.IsNullOrWhiteSpace(value.AssetGuid) &&
                            !string.IsNullOrWhiteSpace(value.name)),
                    "BlueprintSharedVendorTable catalog and exact component fields"),
                Assertion("vendor-unit-associations",
                    "every observed vendor unit references an exact catalog table",
                    observed, associations > 0 && records.Count > 0 &&
                        invalidAssociations == 0,
                    "BlueprintUnit ComponentsArray AddSharedVendor graph"),
                Assertion("vendor-component-owners",
                    "nonempty exact AddSharedVendor component owner catalog",
                    observed, ownerRecords.Count > 0,
                    "all registered BlueprintScriptableObject component arrays"),
                Assertion("capital-vendor-fixed-entry-contract",
                    "exact capital table fixed-item count, cost, and stack contract",
                    observed, capitalTable != null && fixedItemField != null &&
                        fixedCountField != null && capitalEntries.Count ==
                            (expectedEasternCommerce ? 51 : 36) &&
                        capitalReferenceContracts.Count > 0 &&
                        !capitalEntries.Any(value => value.Contains("<null>")),
                    "SmithVendorTable LootItemsPackFixed fields"),
                Assertion("gunslinger-capital-vendor-publication",
                    "twelve exact early/+1/supply entries including Paper and one Blunderbuss",
                    observed, projectEntries == 12 && invalidProjectCounts == 0 &&
                        blunderbussEntries == 1,
                    "registered early and +1 firearms, ammunition, and supplies"),
                Assertion("btsl-vendor-publication",
                    "four exact standalone/campaign tables; twelve unique entries each",
                    observed, btslTables == 4 && btslEntries == 48 &&
                        invalidBtslCounts == 0,
                    "exact discovered DLC shared-vendor table GUID contracts"),
                Assertion("btsl-spear-vendor-publication",
                    "four exact standalone/campaign weapon tables; six singular generic spear entries each; existing firearm rows retained",
                    observed, btslSpearTables == 4 && btslSpearEntries == 24 &&
                        invalidBtslSpearCounts == 0 && btslEntries == 48 &&
                        invalidBtslCounts == 0,
                    "exact installed shared-vendor table identities and additive fixed-item rows"),
                Assertion("eastern-vendor-publication",
                    expectedEasternCommerce ?
                        "four required base merchants plus every installed BTSL table contain each exact desired Eastern item once at count one with no foreign Eastern row" :
                        "module OFF publishes zero Eastern vendor rows while retaining table identities",
                    observed, easternVendorTargets == 4 + easternBtslTables &&
                        easternVendorRows == (expectedEasternCommerce ?
                            49 + easternBtslTables * 12 : 0) &&
                        invalidEasternVendorRows == 0,
                    "exact Eastern vendor specs, names, item references, and fixed-entry counts"),
                Assertion("eastern-btsl-vendor-publication",
                    expectedEasternCommerce ?
                        "all four installed BTSL tables retain firearms and spears and contain exactly 48 singular generic Eastern rows with no named Eastern row" :
                        "module OFF publishes zero Eastern BTSL rows while retaining firearm and spear rows",
                    observed, easternBtslTables == 4 && easternBtslRows ==
                        (expectedEasternCommerce ? 48 : 0) &&
                        easternNamedBtslRows == 0 && btslEntries == 48 &&
                        invalidBtslCounts == 0 && btslSpearEntries == 24 &&
                        invalidBtslSpearCounts == 0,
                    "four exact DLC table identities and item-reference cardinality"),
                Assertion("eastern-named-campaign-publication",
                    expectedEasternCommerce ?
                        "all eighteen named Eastern weapons have one exact count-one merchant or fixed-loot placement; four loot targets contribute eleven rows" :
                        "module OFF publishes zero named Eastern merchant or fixed-loot rows",
                    observed, easternLootTargets == 4 && easternLootRows ==
                        (expectedEasternCommerce ? 11 : 0) &&
                        invalidEasternLootRows == 0 &&
                        easternPlacedKinds.Count == (expectedEasternCommerce ?
                            18 : 0) && easternPlacedKinds.Distinct().Count() ==
                            (expectedEasternCommerce ? 18 : 0),
                    "exact merchant specs plus BlueprintLoot name, area, item, and quantity contracts"),
                Assertion("rare-firearm-acquisition-exclusions",
                    "no named or modern firearms in managed vendors; no Jhod project firearms",
                    observed, bannedManagedEntries == 0 && jhodProjectEntries == 0,
                    "exact managed table and item identities"),
                Assertion("rare-firearm-fixed-loot",
                    "five distinct exact count-one BlueprintLoot targets with exact names and areas",
                    observed, validRareLoot == 5,
                    "installed live blueprint graph after transactional publication"),
                Assertion("production-critical-profiles",
                    "pistol=20/x4;musket=20/x4;blunderbuss=20/x2;" +
                        "rifle=20/x4;revolver=20/x4",
                    criticalProfiles,
                    production != null &&
                        HasCriticalProfile(production.Pistol.WeaponType, 20, 4) &&
                        HasCriticalProfile(production.Musket.WeaponType, 20, 4) &&
                        HasCriticalProfile(production.Blunderbuss.WeaponType, 20, 2) &&
                        HasCriticalProfile(production.AdvancedRifle.WeaponType, 20, 4) &&
                        HasCriticalProfile(production.AdvancedRevolver.WeaponType, 20, 4),
                    "registered BlueprintWeaponType native critical fields"),
                Assertion("vendor-fixed-entry-quantity-precedent",
                    "resolved native stackable and non-stackable count patterns",
                    observed, fixedEntryPatterns.Keys.Any(value =>
                        value.StartsWith("stackable=True:", StringComparison.Ordinal)) &&
                        fixedEntryPatterns.Keys.Any(value =>
                        value.StartsWith("stackable=False:", StringComparison.Ordinal)) &&
                        !fixedEntryPatterns.ContainsKey("<null>"),
                    "all BlueprintSharedVendorTable LootItemsPackFixed entries"),
                Assertion("vendor-observation-only",
                    "no vendor, table, loot, inventory, or save mutation",
                    "read-only blueprint enumeration", true,
                    "scenario contains no assignment, AddLoot, GetTable, shop, or save call"),
                Assertion("rare-firearm-native-enchantment-forensics",
                    "installed enhancement +1/+2/+4/+5, Seeking, Thundering, and Fey Bane candidates with exact contracts",
                    string.Join(" | ", enchantmentRecords.ToArray()),
                    enchantmentsField != null && enchantmentRecords.Count > 0,
                    "read-only BlueprintWeaponEnchantment and donor item graph"),
                Assertion("rare-firearm-loot-candidate-forensics",
                    "nonempty exact fixed campaign loot candidate inventory",
                    string.Join(" | ", lootCandidateRecords.ToArray()),
                    lootCandidateRecords.Count > 0,
                    "read-only BlueprintLoot/BlueprintUnitLoot graph and direct references"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail,
                assertions, null);
        }

        private RuntimeTestResult RunRareFirearmBlueprintContracts()
        {
            MagicFirearmBlueprintCatalog catalog = BlueprintBootstrap.MagicFirearms;
            var instances = new List<ItemEntityWeapon>();
            var assertions = new List<RuntimeTestAssertion>();
            string observed = string.Empty;
            try
            {
                FieldInfo field = typeof(BlueprintItemWeapon).GetField("m_Enchantments",
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                foreach (MagicFirearmBlueprintEntry entry in catalog.Entries)
                {
                    var instance = new ItemEntityWeapon(entry.Item);
                    instances.Add(instance);
                    BlueprintWeaponEnchantment[] staticValues = field == null ? null :
                        field.GetValue(entry.Item) as BlueprintWeaponEnchantment[];
                    bool exactStatic = staticValues != null &&
                        staticValues.SequenceEqual(entry.Spec.Enchantments) &&
                        instance.Enchantments.Count(value => value != null &&
                            staticValues.Contains(value.Blueprint as
                                BlueprintWeaponEnchantment)) == staticValues.Length;
                    assertions.Add(Assertion("item-" + entry.Spec.Symbol,
                        "exact identity/family/cost/weight/static enchantments",
                        entry.Spec.DisplayName + ":" + entry.Item.AssetGuid +
                        ":cost=" + entry.Item.Cost + ":weight=" + entry.Item.Weight +
                        ":static=" + (staticValues == null ? -1 : staticValues.Length),
                        entry.Item.AssetGuid.Length == 32 && entry.Item.Cost ==
                            entry.Spec.Cost && entry.Item.Weight.Equals(
                                entry.Family.Item.Weight) && exactStatic,
                        "live BlueprintItemWeapon and ItemEntityWeapon"));
                }
                ItemEntityWeapon reliable = instances[3];
                ItemEntityWeapon lastWord = instances[6];
                ItemEntityWeapon control = instances[0];
                int beforeStatic = lastWord.Enchantments.Count(value => value != null &&
                    entryBlueprint(lastWord, value.Blueprint));
                FirearmRuntimeState.Service.Set(lastWord, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 1,
                    FirearmStateTokenCatalog.DiagnosticLeadBall,
                    FirearmCondition.Normal));
                int loadedStatic = lastWord.Enchantments.Count(value => value != null &&
                    entryBlueprint(lastWord, value.Blueprint));
                FirearmRuntimeState.Service.Set(lastWord, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 0, null,
                    FirearmCondition.Broken));
                int brokenStatic = lastWord.Enchantments.Count(value => value != null &&
                    entryBlueprint(lastWord, value.Blueprint));
                int zero = global::KingmakerGunslinger.Misfires.EffectiveFirearmMisfirePolicy
                    .Evaluate(1, FirearmCondition.Normal, false, reliable);
                int trainedBroken = global::KingmakerGunslinger.Misfires
                    .EffectiveFirearmMisfirePolicy.Evaluate(1,
                        FirearmCondition.Broken, true, reliable);
                observed = "catalog=" + catalog.Entries.Length + ";reliable=" +
                    Enchantments.FirearmMisfireReductionResolver.Resolve(reliable) +
                    ";controlReliable=" +
                    Enchantments.FirearmMisfireReductionResolver.Resolve(control) +
                    ";seeking=" + Enchantments.SeekingExactItemResolver.IsAuthorized(lastWord) +
                    ";controlSeeking=" + Enchantments.SeekingExactItemResolver.IsAuthorized(control) +
                    ";thresholds=" + zero + "," + trainedBroken +
                    ";staticLifecycle=" + beforeStatic + "," + loadedStatic +
                    "," + brokenStatic;
                assertions.Add(Assertion("reliable-exact-item-threshold",
                    "exact Reliable item 1->0 and trained Broken 1+2-1=2; control none",
                    observed, zero == 0 && trainedBroken == 2 &&
                        Enchantments.FirearmMisfireReductionResolver.Resolve(reliable) == 1 &&
                        Enchantments.FirearmMisfireReductionResolver.Resolve(control) == 0,
                    "shared effective misfire service"));
                assertions.Add(Assertion("seeking-exact-item",
                    "The Last Word authorized; +1 control unauthorized", observed,
                    Enchantments.SeekingExactItemResolver.IsAuthorized(lastWord) &&
                        !Enchantments.SeekingExactItemResolver.IsAuthorized(control),
                    "exact runtime enchantment resolver"));
                assertions.Add(Assertion("static-state-token-coexistence",
                    "three Last Word static properties survive Loaded and Broken tokens",
                    observed, beforeStatic == 3 && loadedStatic == 3 &&
                        brokenStatic == 3 &&
                        FirearmRuntimeState.ReadStateTokenIds(lastWord).Count == 1,
                    "item-owned token repository"));
            }
            catch (Exception exception)
            {
                assertions.Add(Assertion("rare-firearm-blueprint-exception",
                    "no exception", exception.ToString(), false,
                    "exception-contained observer"));
            }
            finally
            {
                foreach (ItemEntityWeapon item in instances)
                    FirearmRuntimeState.Repository.Remove(item);
            }
            assertions.Add(Assertion("loaded-mod-version", _request.ExpectedModVersion,
                _context.ModEntry.Info.Version,
                _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                "Unity Mod Manager ModEntry.Info.Version"));
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS") ?
                RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunMagicFirearmNativeProperties()
        {
            BlueprintUnit source = BlueprintRoot.Instance.DefaultPlayerCharacter;
            UnitEntityData attacker = null;
            UnitEntityData target = null;
            ItemEntityWeapon control = null;
            ItemEntityWeapon seeking = null;
            ItemEntityWeapon watch = null;
            BlueprintFeature feyType = null;
            BlueprintBuff concealment = null;
            Kingmaker.UnitLogic.Buffs.Buff concealmentFact = null;
            RuleAttackRoll controlRoll = null;
            RuleAttackRoll seekingRoll = null;
            bool cleaned = false;
            var assertions = new List<RuntimeTestAssertion>();
            try
            {
                concealment = BlueprintBootstrap.Library.GetAllBlueprints()
                    .OfType<BlueprintBuff>()
                    .Where(value => value != null &&
                        (value.name ?? string.Empty).IndexOf("blur",
                            StringComparison.OrdinalIgnoreCase) >= 0 &&
                        DescribeComponents(value.ComponentsArray).IndexOf(
                            "conceal", StringComparison.OrdinalIgnoreCase) >= 0)
                    .OrderBy(value => value.AssetGuid, StringComparer.Ordinal)
                    .FirstOrDefault();
                if (concealment == null) throw new InvalidOperationException(
                    "No exact installed Blur concealment buff was found.");
                attacker = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                target = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                attacker.Descriptor.Stats.BaseAttackBonus.BaseValue = 20;
                attacker.Descriptor.Stats.Dexterity.BaseValue = 30;
                target.Descriptor.State.Immortality.Retain();
                concealmentFact = target.Descriptor.AddFact(concealment) as
                    Kingmaker.UnitLogic.Buffs.Buff;
                if (concealmentFact == null) throw new InvalidOperationException(
                    "The exact installed concealment buff was not applied.");

                control = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[0].Item);
                seeking = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[6].Item);

                attacker.Body.PrimaryHand.InsertItem(control);
                FirearmRuntimeState.Service.Set(control, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 1,
                    FirearmStateTokenCatalog.DiagnosticLeadBall,
                    FirearmCondition.Normal));
                controlRoll = new RuleAttackRoll(attacker, target, control, -100);
                Enchantments.SeekingConcealmentRuntime.QueueForcedRoll(control, 1);
                Rulebook.Trigger(controlRoll);
                Enchantments.SeekingConcealmentRuntime.CancelForcedRoll();
                attacker.Body.PrimaryHand.RemoveItem(false);

                attacker.Body.PrimaryHand.InsertItem(seeking);
                FirearmRuntimeState.Service.Set(seeking, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 1,
                    FirearmStateTokenCatalog.DiagnosticLeadBall,
                    FirearmCondition.Normal));
                seekingRoll = new RuleAttackRoll(attacker, target, seeking, -100);
                UnityEngine.Random.InitState(FindNativeD100ThenD20Seed(19));
                Enchantments.SeekingConcealmentRuntime.QueueForcedRoll(seeking, 1);
                Rulebook.Trigger(seekingRoll);

                string observed = "buff=" + concealment.name + ":" +
                    concealment.AssetGuid + ";control=" + controlRoll.Result +
                    ",success=" + controlRoll.IsHit + ",concealment=" +
                    (controlRoll.ConcealmentCheck == null ? "none" :
                        controlRoll.ConcealmentCheck.Concealment + ":" +
                        controlRoll.ConcealmentCheck.Roll) + ",roll=" +
                    controlRoll.Roll + ",bonus=" + controlRoll.AttackBonus +
                    ",ac=" + controlRoll.TargetAC + ";seeking=" +
                    seekingRoll.Result + ",success=" + seekingRoll.IsHit +
                    ",concealment=" + (seekingRoll.ConcealmentCheck == null ?
                        "none" : seekingRoll.ConcealmentCheck.Concealment + ":" +
                        seekingRoll.ConcealmentCheck.Roll) + ",roll=" +
                    seekingRoll.Roll + ",bonus=" + seekingRoll.AttackBonus +
                    ",ac=" + seekingRoll.TargetAC + ";discharge=" +
                    FirearmDischargeRuntimeDiagnostics.Describe() +
                    ";misfire=" + FirearmMisfireRuntime.Describe();
                bool sameNativeConcealment = controlRoll.ConcealmentCheck != null &&
                    seekingRoll.ConcealmentCheck != null &&
                    controlRoll.ConcealmentCheck.Concealment ==
                        seekingRoll.ConcealmentCheck.Concealment &&
                    !string.Equals(controlRoll.ConcealmentCheck.Concealment.ToString(),
                        "None", StringComparison.Ordinal);
                assertions.Add(Assertion("seeking-concealment-only-bypass",
                    "control misses the same forced concealment check; exact Seeking item hits",
                    observed, !controlRoll.IsHit && seekingRoll.IsHit &&
                        sameNativeConcealment,
                    "native RuleAttackRoll and RuleConcealmentCheck with exact-item Success postfix"));
                assertions.Add(Assertion("seeking-no-global-concealment-mutation",
                    "same native concealment classification and chance remain on both attacks",
                    observed, sameNativeConcealment,
                    "stored native RuleConcealmentCheck fields"));

                target.Descriptor.Buffs.RemoveFact(concealmentFact);
                concealmentFact = null;
                RuleAttackRoll plusOneAttack = TriggerReliableMatrixAttack(
                    attacker, target, control, 10, FirearmCondition.Normal);
                RuleAttackRoll plusFiveAttack = TriggerReliableMatrixAttack(
                    attacker, target, seeking, 10, FirearmCondition.Normal);
                string enhancementObserved = "plus1=" +
                    plusOneAttack.AttackBonus + ";plus5=" +
                    plusFiveAttack.AttackBonus + ";rolls=" + plusOneAttack.Roll +
                    "," + plusFiveAttack.Roll;
                assertions.Add(Assertion("native-enhancement-attack-bonus",
                    "+5 Pistol native attack bonus is exactly four above +1 Pistol",
                    enhancementObserved,
                    plusFiveAttack.AttackBonus - plusOneAttack.AttackBonus == 4 &&
                        plusOneAttack.Roll.Value == 10 &&
                        plusFiveAttack.Roll.Value == 10,
                    "native WeaponEnhancementBonus through RuleCalculateAttackBonus"));

                feyType = BlueprintBootstrap.Library.GetAllBlueprints()
                    .OfType<BlueprintFeature>()
                    .Single(value => string.Equals(value.name, "FeyType",
                        StringComparison.Ordinal));
                watch = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[7].Item);
                RuleAttackRoll nonFey = TriggerReliableMatrixAttack(
                    attacker, target, watch, 10, FirearmCondition.Normal);
                target.Descriptor.AddFact(feyType);
                RuleAttackRoll fey = TriggerReliableMatrixAttack(
                    attacker, target, watch, 10, FirearmCondition.Normal);
                string feyObserved = "feature=" + feyType.AssetGuid +
                    ";nonFey=" + nonFey.AttackBonus + ";fey=" +
                    fey.AttackBonus + ";rolls=" + nonFey.Roll + "," + fey.Roll;
                assertions.Add(Assertion("native-fey-bane-attack-bonus",
                    "Watch gains native +2 Bane attack bonus only against exact Fey",
                    feyObserved, fey.AttackBonus - nonFey.AttackBonus == 2 &&
                        nonFey.Roll.Value == 10 && fey.Roll.Value == 10,
                    "native WeaponConditionalEnhancementBonus and exact Fey type fact"));
                target.Descriptor.RemoveFact(feyType);
            }
            catch (Exception exception)
            {
                assertions.Add(Assertion("magic-property-exception", "no exception",
                    exception.ToString(), false, "exception-contained disposable fixture"));
            }
            finally
            {
                FirearmMisfireRuntime.CancelForcedNaturalRoll();
                Enchantments.SeekingConcealmentRuntime.CancelForcedRoll();
                if (attacker != null && attacker.Body.PrimaryHand.MaybeItem != null)
                    attacker.Body.PrimaryHand.RemoveItem(false);
                if (control != null) FirearmRuntimeState.Repository.Remove(control);
                if (seeking != null) FirearmRuntimeState.Repository.Remove(seeking);
                if (watch != null) FirearmRuntimeState.Repository.Remove(watch);
                if (feyType != null && target != null && target.Descriptor.HasFact(feyType))
                    target.Descriptor.RemoveFact(feyType);
                if (concealmentFact != null && target != null)
                    target.Descriptor.Buffs.RemoveFact(concealmentFact);
                if (target != null) target.Descriptor.State.Immortality.ReleaseAll();
                if (target != null) target.Dispose();
                if (attacker != null) attacker.Dispose();
                cleaned = true;
            }
            assertions.Add(Assertion("external-isolation",
                "disposable units, buff, items, tokens, and forced rolls removed",
                "cleaned=" + cleaned, cleaned, "bounded fixture cleanup"));
            assertions.Add(Assertion("loaded-mod-version", _request.ExpectedModVersion,
                _context.ModEntry.Info.Version,
                _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                "Unity Mod Manager ModEntry.Info.Version"));
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS") ?
                RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunReliableFirearmMisfireMatrix()
        {
            BlueprintUnit source = BlueprintRoot.Instance.DefaultPlayerCharacter;
            UnitEntityData attacker = null;
            UnitEntityData target = null;
            ItemEntityWeapon pistol = null;
            ItemEntityWeapon musket = null;
            ItemEntityWeapon control = null;
            var assertions = new List<RuntimeTestAssertion>();
            try
            {
                attacker = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                target = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                target.Descriptor.State.Immortality.Retain();
                pistol = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[3].Item);
                musket = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[4].Item);
                control = new ItemEntityWeapon(
                    BlueprintBootstrap.ProductionFirearms.Musket.Item);

                RuleAttackRoll pistolOne = TriggerReliableMatrixAttack(
                    attacker, target, pistol, 1, FirearmCondition.Normal);
                FirearmState pistolAfter = FirearmRuntimeState.Service
                    .GetOrCreate(pistol).Repository.State;
                RuleAttackRoll musketOne = TriggerReliableMatrixAttack(
                    attacker, target, musket, 1, FirearmCondition.Normal);
                FirearmState musketOneAfter = FirearmRuntimeState.Service
                    .GetOrCreate(musket).Repository.State;
                RuleAttackRoll musketTwo = TriggerReliableMatrixAttack(
                    attacker, target, musket, 2, FirearmCondition.Normal);
                FirearmState musketTwoAfter = FirearmRuntimeState.Service
                    .GetOrCreate(musket).Repository.State;
                RuleAttackRoll controlTwo = TriggerReliableMatrixAttack(
                    attacker, target, control, 2, FirearmCondition.Normal);
                FirearmState controlAfter = FirearmRuntimeState.Service
                    .GetOrCreate(control).Repository.State;

                int trainedBrokenPistol = EffectiveFirearmMisfirePolicy.Evaluate(
                    1, FirearmCondition.Broken, true, pistol);
                int untrainedBrokenPistol = EffectiveFirearmMisfirePolicy.Evaluate(
                    1, FirearmCondition.Broken, false, pistol);
                int trainedBrokenMusket = EffectiveFirearmMisfirePolicy.Evaluate(
                    2, FirearmCondition.Broken, true, musket);
                int untrainedBrokenMusket = EffectiveFirearmMisfirePolicy.Evaluate(
                    2, FirearmCondition.Broken, false, musket);
                string observed = "pistol1=" + pistolOne.Result + ":" +
                    pistolAfter.Condition + ";musket1=" + musketOne.Result +
                    ":" + musketOneAfter.Condition + ";musket2=" +
                    musketTwo.Result + ":" + musketTwoAfter.Condition +
                    ";control2=" + controlTwo.Result + ":" +
                    controlAfter.Condition + ";broken=" +
                    trainedBrokenPistol + "," + untrainedBrokenPistol + "," +
                    trainedBrokenMusket + "," + untrainedBrokenMusket +
                    ";diagnostics=" + FirearmMisfireRuntime.Describe();
                assertions.Add(Assertion("reliable-zero-natural-one",
                    "Reliable Pistol threshold 0: natural 1 misses without misfire or condition damage",
                    observed, !pistolOne.IsHit &&
                        pistolAfter.Condition == FirearmCondition.Normal,
                    "native RuleAttackRoll plus shared effective threshold"));
                assertions.Add(Assertion("reliable-musket-threshold-edge",
                    "Reliable Musket: roll 1 misfires; roll 2 is ordinary",
                    observed, musketOneAfter.Condition == FirearmCondition.Broken &&
                        musketTwoAfter.Condition == FirearmCondition.Normal,
                    "deterministic native d20 sequence and exact item condition"));
                assertions.Add(Assertion("mundane-musket-control",
                    "mundane Musket threshold 2: roll 2 misfires",
                    observed, controlAfter.Condition == FirearmCondition.Broken,
                    "non-Reliable exact-item control"));
                assertions.Add(Assertion("reliable-broken-training-order",
                    "trained/untrained Broken Pistol 2/4 and Musket 3/5",
                    observed, trainedBrokenPistol == 2 &&
                        untrainedBrokenPistol == 4 && trainedBrokenMusket == 3 &&
                        untrainedBrokenMusket == 5,
                    "Broken then central training then Reliable then clamp"));
            }
            catch (Exception exception)
            {
                assertions.Add(Assertion("reliable-matrix-exception", "no exception",
                    exception.ToString(), false, "exception-contained fixture"));
            }
            finally
            {
                FirearmMisfireRuntime.CancelForcedNaturalRoll();
                if (attacker != null && attacker.Body.PrimaryHand.MaybeItem != null)
                    attacker.Body.PrimaryHand.RemoveItem(false);
                foreach (ItemEntityWeapon item in new[] { pistol, musket, control })
                    if (item != null) FirearmRuntimeState.Repository.Remove(item);
                if (target != null) target.Descriptor.State.Immortality.ReleaseAll();
                if (target != null) target.Dispose();
                if (attacker != null) attacker.Dispose();
            }
            assertions.Add(Assertion("loaded-mod-version", _request.ExpectedModVersion,
                _context.ModEntry.Info.Version,
                _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                "Unity Mod Manager ModEntry.Info.Version"));
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS") ?
                RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private RuntimeTestResult RunDisposablePaperCartridgeMisfire()
        {
            BlueprintUnit source = BlueprintRoot.Instance.DefaultPlayerCharacter;
            UnitEntityData attacker = null, target = null;
            ItemEntityWeapon reliablePistol = null, reliableMusket = null,
                deadShotPistol = null;
            Deeds.DeadShotExecutionResult deadShot = null;
            bool cleaned = false;
            var assertions = new List<RuntimeTestAssertion>();
            try
            {
                attacker = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                target = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                attacker.Descriptor.Stats.BaseAttackBonus.BaseValue = 11;
                attacker.Descriptor.Stats.Wisdom.BaseValue = 18;
                attacker.Descriptor.AddFact(BlueprintBootstrap.GunslingerClass.Grit.Feature);
                attacker.Descriptor.Resources.Restore(
                    BlueprintBootstrap.GunslingerClass.Grit.Resource, 4);
                reliablePistol = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[3].Item);
                reliableMusket = new ItemEntityWeapon(
                    BlueprintBootstrap.MagicFirearms.Entries[4].Item);
                deadShotPistol = new ItemEntityWeapon(
                    BlueprintBootstrap.ProductionFirearms.Pistol.Item);
                AmmunitionId paper = ReloadAmmunitionProfileCatalog
                    .PaperCartridge.LoadedAmmunition;
                AmmunitionId loose = ReloadAmmunitionProfileCatalog
                    .LooseBasic.LoadedAmmunition;

                RuleAttackRoll pistolPaper = TriggerReliableMatrixAttack(
                    attacker, target, reliablePistol, 1,
                    FirearmCondition.Normal, paper);
                FirearmCondition pistolPaperAfter = FirearmRuntimeState.Service
                    .GetOrCreate(reliablePistol).Repository.State.Condition;
                RuleAttackRoll pistolLoose = TriggerReliableMatrixAttack(
                    attacker, target, reliablePistol, 1,
                    FirearmCondition.Normal, loose);
                FirearmCondition pistolLooseAfter = FirearmRuntimeState.Service
                    .GetOrCreate(reliablePistol).Repository.State.Condition;
                RuleAttackRoll musketPaper = TriggerReliableMatrixAttack(
                    attacker, target, reliableMusket, 2,
                    FirearmCondition.Normal, paper);
                FirearmCondition musketPaperAfter = FirearmRuntimeState.Service
                    .GetOrCreate(reliableMusket).Repository.State.Condition;

                if (attacker.Body.PrimaryHand.MaybeItem != null)
                    attacker.Body.PrimaryHand.RemoveItem(false);
                attacker.Body.PrimaryHand.InsertItem(deadShotPistol);
                FirearmRuntimeState.Service.Set(deadShotPistol, new FirearmState(
                    FirearmState.CurrentSchemaVersion, 1, paper,
                    FirearmCondition.Normal));
                deadShot = Deeds.DeadShotRuntime.ExecuteForRuntimeTest(
                    attacker, target, 2, 2, 2);

                string observed = "pistolPaper=" + pistolPaper.Result + ":" +
                    pistolPaperAfter + ";pistolLoose=" + pistolLoose.Result + ":" +
                    pistolLooseAfter + ";musketPaper=" + musketPaper.Result + ":" +
                    musketPaperAfter + ";deadShotThreshold=" +
                    (deadShot == null ? "missing" : string.Join(",",
                        deadShot.Probes.Select(value => value.Roll.Value))) +
                    ";deadShotCondition=" + (deadShot == null ? "missing" :
                        deadShot.After.Condition.ToString());
                assertions.Add(Assertion("paper-reliable-pistol-boundary",
                    "Reliable Pistol natural 1: paper misfires, next loose load does not",
                    observed, pistolPaperAfter == FirearmCondition.Broken &&
                        pistolLooseAfter == FirearmCondition.Normal,
                    "native ordinary attacks and exact pre-discharge ammunition"));
                assertions.Add(Assertion("paper-reliable-musket-boundary",
                    "Reliable Musket paper threshold includes +1 so natural 2 misfires",
                    observed, musketPaperAfter == FirearmCondition.Broken,
                    "central condition/ammunition/Reliable policy"));
                assertions.Add(Assertion("paper-dead-shot-shared-threshold",
                    "one paper chamber; natural 2 probes use its raised threshold and transition once",
                    observed, deadShot != null && deadShot.Before.LoadedAmmunition == paper &&
                        deadShot.Probes.Length == 3 && deadShot.Outcome.Misfires &&
                        deadShot.After.Condition == FirearmCondition.Broken,
                    "pre-discharge identity and shared Dead Shot threshold"));
            }
            catch (Exception exception)
            {
                assertions.Add(Assertion("paper-misfire-exception", "no exception",
                    exception.ToString(), false, "exception-contained fixture"));
            }
            finally
            {
                FirearmMisfireRuntime.CancelForcedNaturalRoll();
                if (attacker != null && attacker.Body.PrimaryHand.MaybeItem != null)
                    attacker.Body.PrimaryHand.RemoveItem(false);
                foreach (ItemEntityWeapon item in new[] {
                    reliablePistol, reliableMusket, deadShotPistol })
                    if (item != null) FirearmRuntimeState.Service.Forget(item);
                if (target != null) target.Dispose();
                if (attacker != null) attacker.Dispose();
                cleaned = true;
            }
            assertions.Add(Assertion("request-local-cleanup",
                "disposable units, items, tokens, grit, and forced rolls removed",
                "cleaned=" + cleaned, cleaned, "bounded fixture cleanup; no save API"));
            assertions.Add(Assertion("loaded-mod-version", _request.ExpectedModVersion,
                _context.ModEntry.Info.Version,
                _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                "Unity Mod Manager ModEntry.Info.Version"));
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS") ?
                RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private static RuleAttackRoll TriggerReliableMatrixAttack(
            UnitEntityData attacker, UnitEntityData target,
            ItemEntityWeapon weapon, int naturalRoll, FirearmCondition condition,
            AmmunitionId ammunition = null)
        {
            if (attacker.Body.PrimaryHand.MaybeItem != null)
                attacker.Body.PrimaryHand.RemoveItem(false);
            attacker.Body.PrimaryHand.InsertItem(weapon);
            FirearmRuntimeState.Service.Set(weapon, new FirearmState(
                FirearmState.CurrentSchemaVersion, 1,
                ammunition ?? FirearmStateTokenCatalog.DiagnosticLeadBall, condition));
            var attack = new RuleAttackRoll(attacker, target, weapon, -100);
            UnityEngine.Random.InitState(FindNativeD20Seed(naturalRoll));
            Rulebook.Trigger(attack);
            return attack;
        }

        private static bool entryBlueprint(ItemEntityWeapon item, object blueprint)
        {
            BlueprintWeaponEnchantment[] values = typeof(BlueprintItemWeapon)
                .GetField("m_Enchantments", BindingFlags.Instance |
                    BindingFlags.Public | BindingFlags.NonPublic)
                .GetValue(item.Blueprint) as BlueprintWeaponEnchantment[];
            return values != null && values.Contains(blueprint as BlueprintWeaponEnchantment);
        }

        private static int FindNativeD100ThenD20Seed(int expectedD20)
        {
            for (int seed = 1; seed <= 100000; seed++)
            {
                UnityEngine.Random.InitState(seed);
                int ignored = RulebookEvent.Dice.D100.Value;
                if (RulebookEvent.Dice.D20.Value == expectedD20) return seed;
            }
            throw new InvalidOperationException(
                "No deterministic native D100-to-D20 seed produced " +
                expectedD20 + ".");
        }

        private static bool IsRareFirearmNativeEnchantmentCandidate(
            BlueprintWeaponEnchantment enchantment)
        {
            string value = ((enchantment == null ? string.Empty : enchantment.name) +
                " " + (enchantment == null ? string.Empty : enchantment.Name))
                .ToLowerInvariant();
            bool concealmentComponent = enchantment != null &&
                (enchantment.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                .Any(component => component != null &&
                    (component.GetType().FullName ?? string.Empty).IndexOf(
                        "conceal", StringComparison.OrdinalIgnoreCase) >= 0);
            bool concealmentValue = enchantment != null &&
                DescribeComponentScalarContracts(enchantment.ComponentsArray)
                    .IndexOf("conceal", StringComparison.OrdinalIgnoreCase) >= 0;
            return concealmentComponent || concealmentValue ||
                value.Contains("enhancement1") ||
                value.Contains("enhancement2") ||
                value.Contains("enhancement4") || value.Contains("enhancement5") ||
                value.Contains("seeking") || value.Contains("thundering") ||
                (value.Contains("fey") && value.Contains("bane"));
        }

        private static string DescribeComponentScalarContracts(
            BlueprintComponent[] components)
        {
            var values = new List<string>();
            foreach (BlueprintComponent component in components ??
                Array.Empty<BlueprintComponent>())
            {
                if (component == null) continue;
                for (Type type = component.GetType(); type != null;
                    type = type.BaseType)
                {
                    foreach (FieldInfo field in type.GetFields(BindingFlags.Instance |
                        BindingFlags.Public | BindingFlags.NonPublic |
                        BindingFlags.DeclaredOnly))
                    {
                        Type fieldType = field.FieldType;
                        if (!(fieldType.IsEnum || fieldType.IsPrimitive ||
                            fieldType == typeof(string))) continue;
                        object fieldValue;
                        try { fieldValue = field.GetValue(component); }
                        catch { continue; }
                        values.Add(component.GetType().FullName + "." + field.Name +
                            "=" + (fieldValue == null ? "<null>" :
                                fieldValue.ToString()));
                    }
                }
            }
            return string.Join(",", values.OrderBy(entry => entry,
                StringComparer.Ordinal).ToArray());
        }

        private static bool IsRareFirearmLootCandidate(BlueprintScriptableObject value)
        {
            var loot = value as BlueprintLoot;
            string text = (value.name ?? string.Empty) + " " +
                (loot == null ? string.Empty : (loot.ContainerName ?? string.Empty) +
                    " " + (loot.Area == null ? string.Empty : loot.Area.name));
            string lower = text.ToLowerInvariant();
            string[] terms = { "pitax", "irovetti", "palace", "armory", "treasur",
                "duel", "officer", "noble", "cache", "academy", "bard", "opera",
                "houseattheedge", "house_at_the_edge", "hateot", "finaldungeon",
                "firstworld", "lanternking", "worldend" };
            return terms.Any(lower.Contains);
        }

        private static string DescribeFixedLootComponents(
            BlueprintScriptableObject blueprint)
        {
            return string.Join(",", (blueprint.ComponentsArray ??
                Array.Empty<BlueprintComponent>()).OfType<LootItemsPackFixed>()
                .Select(component =>
                {
                    BlueprintItem item = CapitalVendorBlueprints.ReadItem(component);
                    return (item == null ? "<null>" : item.name + ":" +
                        item.AssetGuid) + "*" + CapitalVendorBlueprints.ReadCount(component);
                }).ToArray());
        }

        private static Dictionary<string, List<string>>
            BuildDirectBlueprintReferenceIndex(BlueprintScriptableObject[] owners,
                BlueprintScriptableObject[] targets)
        {
            var targetGuids = new HashSet<string>(targets.Select(value =>
                value.AssetGuid), StringComparer.Ordinal);
            var result = targetGuids.ToDictionary(value => value,
                value => new List<string>(), StringComparer.Ordinal);
            foreach (BlueprintScriptableObject owner in owners)
            {
                var counts = new Dictionary<string, int>(StringComparer.Ordinal);
                CountSelectedDirectReferences(owner, targetGuids, counts);
                foreach (BlueprintComponent component in owner.ComponentsArray ??
                    Array.Empty<BlueprintComponent>())
                    CountSelectedDirectReferences(component, targetGuids, counts);
                foreach (KeyValuePair<string, int> match in counts)
                    result[match.Key].Add(owner.GetType().FullName + ":" +
                        owner.name + ":" + owner.AssetGuid + "*" + match.Value);
            }
            return result;
        }

        private static void CountSelectedDirectReferences(object owner,
            HashSet<string> targetGuids, Dictionary<string, int> counts)
        {
            if (owner == null) return;
            for (Type type = owner.GetType(); type != null; type = type.BaseType)
            {
                foreach (FieldInfo field in type.GetFields(BindingFlags.Instance |
                    BindingFlags.Public | BindingFlags.NonPublic |
                    BindingFlags.DeclaredOnly))
                {
                    object value;
                    try { value = field.GetValue(owner); }
                    catch { continue; }
                    var direct = value as BlueprintScriptableObject;
                    if (direct != null && targetGuids.Contains(direct.AssetGuid))
                        IncrementReferenceCount(counts, direct.AssetGuid);
                    var array = value as Array;
                    if (array == null) continue;
                    foreach (object element in array)
                    {
                        var referenced = element as BlueprintScriptableObject;
                        if (referenced != null &&
                            targetGuids.Contains(referenced.AssetGuid))
                            IncrementReferenceCount(counts, referenced.AssetGuid);
                    }
                }
            }
        }

        private static void IncrementReferenceCount(
            Dictionary<string, int> counts, string guid)
        {
            int current;
            counts.TryGetValue(guid, out current);
            counts[guid] = current + 1;
        }

        private RuntimeTestResult RunProductionFirearmFallbackObservation()
        {
