            AddFacts steadyGrant = musketMaster == null ? null :
                musketMaster.SteadyAim.ComponentsArray.OfType<AddFacts>()
                    .SingleOrDefault();
            bool steadyContract = steadyAbility != null && steadyLogic != null &&
                steadyHandler != null && steadyGrant != null &&
