        private static string DescribeNativeRig(GameObject instance,
            WeaponVisualParameters visual)
        {
            if (instance == null) return "instance=<null>";
            EquipmentOffsets offsets = instance.GetComponent<EquipmentOffsets>();
            string ik = offsets == null || offsets.IkTargetLeftHand == null
                ? "<null>" : TransformPath(offsets.IkTargetLeftHand,
                    instance.transform) + "@" +
                    offsets.IkTargetLeftHand.localPosition.ToString("R");
            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>(true);
            string hierarchy = string.Join(",", instance
                .GetComponentsInChildren<Transform>(true)
                .Select(value => TransformPath(value, instance.transform))
                .OrderBy(value => value, StringComparer.Ordinal).ToArray());
            return "model=" + visual.Model.name + ";anim=" + visual.AnimStyle +
                ";attachSlots=" + string.Join(",", visual.AttachSlots.Select(
                    value => value.ToString()).ToArray()) +
                ";projectiles=" + visual.Projectiles.Length +
                ";belt=" + (visual.BeltModel == null ? "<null>" :
                    visual.BeltModel.name) +
                ";sheath=" + (visual.SheathModel == null ? "<null>" :
                    visual.SheathModel.name) + ";renderers=" + renderers.Length +
                ";offsets=" + (offsets != null) + ";ikLeft=" + ik +
                ";hierarchy=" + hierarchy;
        }

        private static string TransformPath(Transform value, Transform root)
        {
            var names = new List<string>();
            for (Transform current = value; current != null;
                current = current.parent)
            {
                names.Add(current.name);
                if (ReferenceEquals(current, root)) break;
            }
            names.Reverse();
            return string.Join("/", names.ToArray());
        }

        private static string DescribeFirearmRenderers(Renderer[] renderers,
            out bool visiblyRenderable)
        {
            Renderer[] values = renderers ?? Array.Empty<Renderer>();
            int visible = values.Count(value => value != null && value.enabled &&
                value.gameObject.activeInHierarchy);
            bool materials = values.Length > 0 && values.All(value =>
                value != null && value.sharedMaterials != null &&
                value.sharedMaterials.Length > 0 &&
                value.sharedMaterials.All(material => material != null &&
                    material.shader != null && material.shader.name == "Standard"));
            Bounds bounds = values.Length == 0 ? new Bounds() : values[0].bounds;
            for (int index = 1; index < values.Length; index++)
                bounds.Encapsulate(values[index].bounds);
            string shaders = string.Join("|", values.SelectMany(value =>
                    value.sharedMaterials).Select(material => material.shader.name)
                .Distinct().OrderBy(value => value, StringComparer.Ordinal).ToArray());
            visiblyRenderable = visible == values.Length && materials &&
                bounds.size.sqrMagnitude > 0.01f;
            return "rendererCount=" + values.Length + ";visibleCount=" + visible +
                ";shaders=" + shaders + ";boundsCenter=" +
                bounds.center.ToString("R") + ";boundsSize=" +
                bounds.size.ToString("R");
        }

        private RuntimeTestResult RunDisposableFirearmVisualRigs()
        {
            var assertions = new List<RuntimeTestAssertion>();
            AppendLongGunRigAssertions(assertions, FirearmKind.Musket,
                BlueprintBootstrap.ProductionFirearms.Musket.Item);
            AppendLongGunRigAssertions(assertions, FirearmKind.Blunderbuss,
                BlueprintBootstrap.ProductionFirearms.Blunderbuss.Item);
            AppendLongGunRigAssertions(assertions, FirearmKind.Rifle,
                BlueprintBootstrap.ProductionFirearms.AdvancedRifle.Item);
            AppendShortGunRigAssertions(assertions, FirearmKind.Pistol,
                BlueprintBootstrap.ProductionFirearms.Pistol.Item);
            AppendShortGunRigAssertions(assertions, FirearmKind.Revolver,
                BlueprintBootstrap.ProductionFirearms.AdvancedRevolver.Item);
            AppendDiagnosticMusketRigAssertions(assertions, "MusketPassThrough");
            AppendDiagnosticMusketRigAssertions(assertions, "MusketMinimalControl");
            AppendDiagnosticMusketRigAssertions(assertions, "MusketClearanceStock");
            AppendFirearmItemVariantAssertions(assertions);
            FirearmRigCapability musketCapability = FirearmAssetRuntime.GetCapability(
                FirearmKind.Musket);
            FirearmRigCapability blunderbussCapability = FirearmAssetRuntime.GetCapability(
                FirearmKind.Blunderbuss);
            float musketLength = SemanticLength(musketCapability);
            float blunderbussLength = SemanticLength(blunderbussCapability);
            assertions.Add(Assertion("long-gun-relative-semantic-length",
                "Musket 1.25-1.45 and longer than Blunderbuss",
                "musket=" + musketLength.ToString("R") +
                ";blunderbuss=" + blunderbussLength.ToString("R"),
                musketLength >= 1.25f && musketLength <= 1.45f &&
                musketLength > blunderbussLength,
                "runtime-loaded semantic Butt/Muzzle anchors"));
            assertions.Add(Assertion("human-visual-gate", "not mechanically proven",
                "grip/clipping/scale/pose/animation require human review", true,
                "explicit evidence limitation"));
            assertions.Add(Assertion("loaded-mod-version", _request.ExpectedModVersion,
                _context.ModEntry.Info.Version,
                _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                "Unity Mod Manager ModEntry.Info.Version"));
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS")
                ? RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private static float SemanticLength(FirearmRigCapability capability)
        {
            return capability != null && capability.ButtPosition.HasValue &&
                capability.MuzzlePosition.HasValue
                ? Vector3.Distance(capability.ButtPosition.Value,
                    capability.MuzzlePosition.Value) : -1f;
        }

        private static void AppendFirearmItemVariantAssertions(
            List<RuntimeTestAssertion> assertions)
        {
            var items = new List<Tuple<string, FirearmKind,
                BlueprintItemWeapon>>
            {
                Tuple.Create(TestMusketBlueprints.ItemSymbol,
                    FirearmKind.Musket, BlueprintBootstrap.TestMusketItem),
                Tuple.Create(ProductionFirearmBlueprints.PistolItemSymbol,
                    FirearmKind.Pistol,
                    BlueprintBootstrap.ProductionFirearms.Pistol.Item),
                Tuple.Create(ProductionFirearmBlueprints.MusketItemSymbol,
                    FirearmKind.Musket,
                    BlueprintBootstrap.ProductionFirearms.Musket.Item),
                Tuple.Create(ProductionFirearmBlueprints.BlunderbussItemSymbol,
                    FirearmKind.Blunderbuss,
                    BlueprintBootstrap.ProductionFirearms.Blunderbuss.Item),
                Tuple.Create(ProductionFirearmBlueprints.AdvancedRifleItemSymbol,
                    FirearmKind.Rifle,
                    BlueprintBootstrap.ProductionFirearms.AdvancedRifle.Item),
                Tuple.Create(ProductionFirearmBlueprints.AdvancedRevolverItemSymbol,
                    FirearmKind.Revolver,
                    BlueprintBootstrap.ProductionFirearms.AdvancedRevolver.Item)
            };
            items.AddRange(BlueprintBootstrap.MagicFirearms.Entries.Select(entry =>
                Tuple.Create(entry.Spec.Symbol, entry.Spec.Kind, entry.Item)));
            string[] variants = items.Select(value =>
                    WeaponVisualVariantCatalog.Require(value.Item1))
                .Distinct(StringComparer.Ordinal).OrderBy(value => value,
                    StringComparer.Ordinal).ToArray();
            bool exactItems = items.Count == 14 && items.All(value =>
                FirearmWeaponPresentation.HasExactItemVariant(value.Item3,
                    value.Item1, value.Item2));
            bool pistolSeparation = !ReferenceEquals(
                    BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.DuelistsRebuttalSymbol).Item
                        .VisualParameters.Model,
                    BlueprintBootstrap.ProductionFirearms.Pistol.Item
                        .VisualParameters.Model) &&
                !ReferenceEquals(BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.TheLastWordSymbol).Item
                        .VisualParameters.Model,
                    BlueprintBootstrap.ProductionFirearms.Pistol.Item
                        .VisualParameters.Model) &&
                !ReferenceEquals(BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.DuelistsRebuttalSymbol).Item
                        .VisualParameters.Model,
                    BlueprintBootstrap.MagicFirearms.Require(
                        MagicFirearmBlueprints.TheLastWordSymbol).Item
                        .VisualParameters.Model);
            assertions.Add(Assertion("firearm-all-14-item-visual-identities",
                "14 exact symbol-approved variants; no FirearmKind-only selection",
                string.Join("|", items.Select(value => value.Item1 + "=" +
                    WeaponVisualVariantCatalog.Require(value.Item1)).ToArray()),
                exactItems, "exact inherited item visual/model reference"));
            assertions.Add(Assertion("pistol-three-variant-separation",
                "Service, Duelist, and LastWord are three distinct prefab references",
                "distinct=" + pistolSeparation, pistolSeparation,
                "exact item-level visual model reference identity"));

            var instances = new List<GameObject>();
            bool renderable = true;
            bool exactPistolMarkers = true;
            bool cleaned = false;
            try
            {
                foreach (string variant in variants)
                {
                    GameObject instance = FirearmAssetRuntime
                        .InstantiateItemVariantPrefab(variant);
                    instances.Add(instance);
                    Renderer[] renderers = instance == null
                        ? Array.Empty<Renderer>()
                        : instance.GetComponentsInChildren<Renderer>(true);
                    bool visible;
                    DescribeFirearmRenderers(renderers, out visible);
                    renderable &= instance != null && visible &&
                        FirearmAssetRuntime.HasValidatedItemVariant(variant);
                    if (variant == WeaponVisualVariantCatalog.PistolDuelist ||
                        variant == WeaponVisualVariantCatalog.PistolLastWord)
                    {
                        Transform visual = instance == null ? null :
                            instance.transform.Find("Visual");
                        Transform[] hierarchy = visual == null
                            ? Array.Empty<Transform>()
                            : visual.GetComponentsInChildren<Transform>(true);
                        exactPistolMarkers &= new[] { "KMG_Grip", "KMG_Support",
                            "KMG_Butt", "KMG_Muzzle" }.All(marker =>
                                hierarchy.Count(value => value.name == marker) == 1);
                        exactPistolMarkers &= instance != null &&
                            instance.transform.Find("SupportHandTarget") == null &&
                            instance.transform.Find("Muzzle") != null &&
                            Vector3.Distance(instance.transform.Find("Muzzle")
                                .localPosition, new Vector3(0f, 0f, 0.264f)) <
                                0.0001f;
                    }
                }
                assertions.Add(Assertion("firearm-seven-approved-variant-prefabs",
                    "seven exact reusable variants instantiate visibly",
                    "variants=" + string.Join("|", variants),
                    variants.Length == 7 && renderable,
                    "runtime-loaded exact variant prefab set"));
                assertions.Add(Assertion("pistol-authored-marker-contract",
                    "Duelist and LastWord retain exactly four authored markers, +Z muzzle, and no support IK",
                    "exact=" + exactPistolMarkers, exactPistolMarkers,
                    "runtime-loaded source marker hierarchy"));
            }
            finally
            {
                foreach (GameObject instance in instances)
                    if (instance != null) UnityEngine.Object.DestroyImmediate(instance);
                cleaned = instances.All(value => value == null ||
                    value.Equals(null));
            }
            assertions.Add(Assertion("firearm-item-variant-cleanup", "destroyed",
                cleaned.ToString(), cleaned,
                "finally-owned transient exact variant instances"));
        }

        private static void AppendDiagnosticMusketRigAssertions(
            List<RuntimeTestAssertion> assertions, string identity)
        {
            GameObject instance = null;
            bool cleaned = false;
            string id = "musket-diagnostic-" + identity.ToLowerInvariant();
            try
            {
                FirearmRigCapability capability =
                    FirearmAssetRuntime.GetDiagnosticCapability(identity);
                instance = FirearmAssetRuntime.InstantiateDiagnosticPrefab(identity);
                Transform muzzle = instance == null ? null : instance.transform.Find("Muzzle");
                Transform support = instance == null ? null : instance.transform.Find("SupportHandTarget");
                Transform butt = instance == null ? null : instance.transform.Find("Butt");
                Transform visual = instance == null ? null : instance.transform.Find("Visual");
                EquipmentOffsets offsets = instance == null ? null :
                    instance.GetComponent<EquipmentOffsets>();
                Transform[] hierarchy = visual == null ? Array.Empty<Transform>() :
                    visual.GetComponentsInChildren<Transform>(true);
                bool exactMarkerSet = new[] { "KMG_Grip", "KMG_Support",
                    "KMG_Butt", "KMG_Muzzle" }.All(marker =>
                        hierarchy.Count(value => value.name == marker) == 1);
                Renderer[] renderers = instance == null ? Array.Empty<Renderer>() :
                    instance.GetComponentsInChildren<Renderer>(true);
                bool visiblyRenderable;
                string rendererSummary = DescribeFirearmRenderers(renderers,
                    out visiblyRenderable);
                bool exactFrame = muzzle != null && support != null && butt != null &&
                    Vector3.Distance(muzzle.localPosition,
                        new Vector3(0f, 0f, 1.180452f)) < 0.0001f &&
                    Vector3.Distance(support.localPosition,
                        new Vector3(-0.030976f, -0.051069f, 0.586040f)) < 0.0001f &&
                    Vector3.Distance(butt.localPosition,
                        new Vector3(0f, 0f, -0.169533f)) < 0.0001f;
                assertions.Add(Assertion(id + "-contract",
                    "validated diagnostic-only rig; exact fixed Musket semantic frame",
                    capability.Describe() + ";" + rendererSummary,
                    FirearmAssetRuntime.HasValidatedDiagnosticPrefab(identity) &&
                    instance != null && exactFrame && visiblyRenderable &&
                    offsets != null && ReferenceEquals(offsets.IkTargetLeftHand,
                        support),
                    "runtime-loaded diagnostic prefab excluded from production binding"));
                assertions.Add(Assertion(id + "-authored-markers",
                    "exactly one of every KMG semantic marker under Visual",
                    "exactMarkerSet=" + exactMarkerSet,
                    exactMarkerSet,
                    "source-authored marker hierarchy retained through FBX and bundle"));
            }
            finally
            {
                if (instance != null) UnityEngine.Object.DestroyImmediate(instance);
                cleaned = instance == null || instance.Equals(null);
            }
            assertions.Add(Assertion(id + "-cleanup", "destroyed",
                cleaned.ToString(), cleaned,
                "finally-owned transient diagnostic GameObject"));
        }

