        private RuntimeTestResult RunDisposablePaperCartridgeCraftingVendors()
        {
            BlueprintUnit source = BlueprintRoot.Instance.DefaultPlayerCharacter;
            var player = Kingmaker.Game.Instance.Player;
            BasicAmmunitionBlueprintSet ammo = BlueprintBootstrap.BasicAmmunition;
            BlueprintItem tool = BlueprintBootstrap.GunsmithingSupplies.GunsmithKit;
            GunsmithingCraftingBlueprintSet crafting =
                BlueprintBootstrap.GunsmithingCrafting;
            CraftPaperCartridgesAbilityLogic paperLogic = crafting.PaperAbility
                .ComponentsArray.OfType<CraftPaperCartridgesAbilityLogic>().Single();
            CraftBasicAmmunitionAbilityLogic basicLogic = crafting.BasicAbility
                .ComponentsArray.OfType<CraftBasicAmmunitionAbilityLogic>().Single();
            int paperBefore = player.Inventory.Count(ammo.PaperCartridge);
            int powderBefore = player.Inventory.Count(ammo.BlackPowder);
            int ballsBefore = player.Inventory.Count(ammo.LeadBall);
            int toolsBefore = player.Inventory.Count(tool);
            long moneyBefore = player.Money;
            long seededMoney = moneyBefore < CraftPaperCartridgesAbilityLogic.GoldCost ?
                CraftPaperCartridgesAbilityLogic.GoldCost : 0;
            UnitEntityData unit = null;
            bool crafted = false, sharedBlocked = false, vendors = false,
                jhodPreserved = false, cleaned = false;
            string vendorObserved = string.Empty;
            try
            {
                if (toolsBefore == 0) player.Inventory.Add(tool, 1);
                if (seededMoney > 0) player.GainMoney(seededMoney);
                unit = new Kingmaker.UI.LevelUp.ChargenUnit(source).Unit;
                unit.Descriptor.AddFact(crafting.BasicAbility);
                unit.Descriptor.AddFact(crafting.PaperAbility);
                var paperFact = unit.Descriptor.Abilities.GetAbility(crafting.PaperAbility);
                var basicFact = unit.Descriptor.Abilities.GetAbility(crafting.BasicAbility);
                if (paperFact == null || basicFact == null)
                    throw new InvalidOperationException(
                        "Both Gunsmithing recipes were not granted.");
                var paperData = new AbilityData(paperFact);
                var basicData = new AbilityData(basicFact);
                var command = new UnitUseAbility(paperData, new TargetWrapper(unit));
                if (!command.CanStart || !paperData.IsAvailable || !basicData.IsAvailable)
                    throw new InvalidOperationException(
                        "Native Paper crafting command was unavailable before use.");
                paperLogic.Complete(unit.Descriptor);
                crafted = player.Inventory.Count(ammo.PaperCartridge) ==
                        paperBefore + CraftPaperCartridgesAbilityLogic.BatchSize &&
                    player.Inventory.Count(ammo.BlackPowder) == powderBefore &&
                    player.Inventory.Count(ammo.LeadBall) == ballsBefore &&
                    player.Money == moneyBefore + seededMoney -
                        CraftPaperCartridgesAbilityLogic.GoldCost &&
                    unit.Descriptor.HasFact(crafting.UsedMarker);
                sharedBlocked = !paperData.IsAvailable && !basicData.IsAvailable;

                BlueprintSharedVendorTable[] tables = BlueprintBootstrap.Library
                    .GetAllBlueprints().OfType<BlueprintSharedVendorTable>().ToArray();
                BlueprintSharedVendorTable smith = tables.Single(value =>
                    value.AssetGuid == CapitalVendorBlueprints.TableGuid &&
                    value.name == CapitalVendorBlueprints.ExpectedTableName);
                LootItemsPackFixed[] smithPaper = (smith.ComponentsArray ??
                    Array.Empty<BlueprintComponent>()).OfType<LootItemsPackFixed>()
                    .Where(value => ReferenceEquals(
                        CapitalVendorBlueprints.ReadItem(value), ammo.PaperCartridge))
                    .ToArray();
                int installedBtsl = 0, validBtsl = 0;
                foreach (string guid in BeneathStolenLandsVendorBlueprints.TableGuids)
                {
                    BlueprintSharedVendorTable table = tables.SingleOrDefault(value =>
                        value.AssetGuid == guid);
                    if (table == null) continue;
                    installedBtsl++;
                    LootItemsPackFixed[] matches = (table.ComponentsArray ??
                        Array.Empty<BlueprintComponent>()).OfType<LootItemsPackFixed>()
                        .Where(value => ReferenceEquals(
                            CapitalVendorBlueprints.ReadItem(value), ammo.PaperCartridge))
                        .ToArray();
                    if (matches.Length == 1 &&
                        CapitalVendorBlueprints.ReadCount(matches[0]) == 200)
                        validBtsl++;
                }
                BlueprintSharedVendorTable jhod = tables.Single(value =>
                    value.AssetGuid == "afa2c7f292b8e1c4d9c835f0e8047dd3");
                int jhodPaper = (jhod.ComponentsArray ?? Array.Empty<BlueprintComponent>())
                    .OfType<LootItemsPackFixed>().Count(value => ReferenceEquals(
                        CapitalVendorBlueprints.ReadItem(value), ammo.PaperCartridge));
                vendors = smithPaper.Length == 1 &&
                    CapitalVendorBlueprints.ReadCount(smithPaper[0]) == 200 &&
                    installedBtsl == validBtsl;
                jhodPreserved = jhodPaper == 0;
                vendorObserved = "smith=" + smithPaper.Length + ":" +
                    (smithPaper.Length == 0 ? -1 :
                        CapitalVendorBlueprints.ReadCount(smithPaper[0])) +
                    ";btsl=" + validBtsl + "/" + installedBtsl +
                    ";jhod=" + jhodPaper;
            }
            finally
            {
                if (unit != null && unit.Descriptor.HasFact(crafting.UsedMarker))
                    unit.Descriptor.RemoveFact(crafting.UsedMarker);
                int paperExtra = player.Inventory.Count(ammo.PaperCartridge) - paperBefore;
                int toolsExtra = player.Inventory.Count(tool) - toolsBefore;
                if (paperExtra > 0) player.Inventory.Remove(ammo.PaperCartridge, paperExtra);
                if (toolsExtra > 0) player.Inventory.Remove(tool, toolsExtra);
                long moneyDelta = player.Money - moneyBefore;
                if (moneyDelta < 0) player.GainMoney(-moneyDelta);
                else if (moneyDelta > 0) player.SpendMoney((int)moneyDelta);
                if (unit != null) unit.Dispose();
                cleaned = player.Inventory.Count(ammo.PaperCartridge) == paperBefore &&
                    player.Inventory.Count(ammo.BlackPowder) == powderBefore &&
                    player.Inventory.Count(ammo.LeadBall) == ballsBefore &&
                    player.Inventory.Count(tool) == toolsBefore &&
                    player.Money == moneyBefore;
            }
            string observed = "crafted=" + crafted + ";sharedBlocked=" +
                sharedBlocked + ";" + vendorObserved + ";cleaned=" + cleaned;
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("paper-crafting-transaction", "120 gp creates exactly 20 Paper Cartridges",
                    observed, crafted && paperLogic != null && basicLogic.GoldCost == 22,
                    "native ability command plus shared atomic transaction"),
                Assertion("paper-crafting-shared-marker", "either recipe blocks both until rest",
                    observed, sharedBlocked, "one exact persisted marker"),
                Assertion("paper-vendor-publication", "Smith and every installed BTSL table contain one exact count-200 entry",
                    observed, vendors, "bounded normalized live blueprint tables"),
                Assertion("paper-jhod-exclusion", "rejected Jhod table contains no Paper Cartridge",
                    observed, jhodPreserved, "exact rejected table identity"),
                Assertion("request-local-cleanup", "money, inventory, tool, marker, and unit restored exactly",
                    observed, cleaned, "finally cleanup; no save API"),
                Assertion("loaded-mod-version", _request.ExpectedModVersion,
                    _context.ModEntry.Info.Version,
                    _request.ExpectedModVersion == _context.ModEntry.Info.Version,
                    "Unity Mod Manager ModEntry.Info.Version")
            };
            return CreateResult(assertions.TrueForAll(value => value.Status == "PASS") ?
                RuntimeTestStatuses.Pass : RuntimeTestStatuses.Fail, assertions, null);
        }

        private void AppendAcceptanceSlice(List<RuntimeTestAssertion> assertions,
            string label, ref int slices, Func<RuntimeTestResult> execute)
        {
            slices++;
            try
            {
                RuntimeTestResult result = execute();
                if (result == null || result.Assertions == null)
                    throw new InvalidOperationException("Slice returned no assertions.");
                foreach (RuntimeTestAssertion assertion in result.Assertions)
                    assertions.Add(new RuntimeTestAssertion
                    {
                        Name = label + "." + assertion.Name,
                        Expected = assertion.Expected,
                        Observed = assertion.Observed,
                        Status = assertion.Status,
                        Evidence = assertion.Evidence
                    });
            }
            catch (Exception exception)
            {
                assertions.Add(Assertion(label + ".execution",
                    "qualified slice completes without exception",
                    exception.ToString(), false,
                    "slice-owned cleanup plus comprehensive fail-closed aggregation"));
            }
        }

        private static bool ObserveRepairedPresentation(string label,
            ProductionFirearmBlueprintEntry firearm, BlueprintWeaponType sourceType,
            BlueprintItemWeapon sourceItem, List<string> records)
        {
            string[] itemFields = { "m_EquipmentEntity", "m_EquipmentEntityAlternatives",
                "m_InventoryPutSound", "m_InventoryTakeSound" };
            bool itemMatch = itemFields.All(name => EquivalentPresentationValue(
                ReadField(firearm.Item, name), ReadField(sourceItem, name)));
            bool itemVisual = RepairedFirearmVisualParameters(firearm,
                ReadField(firearm.Item, "m_VisualParameters"),
                ReadField(sourceItem, "m_VisualParameters"));
            bool typeIcon = EquivalentPresentationValue(
                ReadField(firearm.WeaponType, "m_Icon"),
                ReadField(sourceType, "m_Icon"));
            object typeVisualValue = ReadField(firearm.WeaponType,
                "m_VisualParameters");
            object sourceVisualValue = ReadField(sourceType,
                "m_VisualParameters");
            bool typeVisual = RepairedFirearmVisualParameters(
                firearm, typeVisualValue, sourceVisualValue);
            bool itemIconDistinct = !EquivalentPresentationValue(
                ReadField(firearm.Item, "m_Icon"), ReadField(sourceItem, "m_Icon"));
            int projectiles = GetProjectileCount(firearm.WeaponType);
            records.Add("entry=" + label + ";item=" + itemMatch +
                ";itemVisual=" + itemVisual +
                ";typeIcon=" + typeIcon + ";typeVisual=" + typeVisual +
                ";itemIconDistinct=" + itemIconDistinct +
                ";projectiles=" + projectiles + ";icon=" +
                (firearm.Item.Icon != null));
            return itemMatch && itemVisual && itemIconDistinct && typeIcon && typeVisual;
        }

        private static bool RepairedFirearmVisualParameters(
            ProductionFirearmBlueprintEntry firearm, object visual,
            object source)
        {
            var repaired = visual as WeaponVisualParameters;
            var native = source as WeaponVisualParameters;
            if (repaired == null || native == null ||
                ReferenceEquals(repaired, native)) return false;
            Array projectiles = ReadField(repaired, "m_Projectiles") as Array;
            bool projectilesPreserved = projectiles != null &&
                projectiles.Length == 1 && ReferenceEquals(projectiles.GetValue(0),
                    FirearmProjectileBlueprints.Projectile);
            bool animationPreserved = repaired.AnimStyle == native.AnimStyle;
            bool attachSlotsPreserved = EquivalentPresentationValue(
                repaired.AttachSlots, native.AttachSlots);
            Assets.FirearmPresentationProfile profile =
                Assets.FirearmPresentationProfile.Require(
                    firearm.Spec.Definition.Kind);
            object customEquipped = profile.EquippedModel;
            bool equippedModelCoherent = customEquipped == null
                ? ReferenceEquals(repaired.Model, native.Model)
                : ReferenceEquals(repaired.Model, customEquipped);
            object customBelt = profile.BeltModel;
            bool beltModelCoherent = customBelt == null
                ? ReferenceEquals(repaired.BeltModel, native.BeltModel)
                : ReferenceEquals(repaired.BeltModel, customBelt);
            bool sheathModelCoherent = profile.SheathModel == null
                ? ReferenceEquals(repaired.SheathModel, native.SheathModel)
                : ReferenceEquals(repaired.SheathModel,
                    profile.SheathModel);
            bool nonReleaseSoundsPreserved =
                repaired.SoundSize == native.SoundSize &&
                repaired.SoundType == native.SoundType &&
                repaired.MissSoundType == native.MissSoundType &&
                string.IsNullOrEmpty(repaired.WhooshSound) &&
                string.Equals(repaired.EquipSound, native.EquipSound,
                    StringComparison.Ordinal) &&
                string.Equals(repaired.UnequipSound, native.UnequipSound,
                    StringComparison.Ordinal);
            bool prototypeSevered = repaired.Prototype == null;
            return projectilesPreserved && animationPreserved &&
                attachSlotsPreserved && equippedModelCoherent &&
                beltModelCoherent && sheathModelCoherent &&
                nonReleaseSoundsPreserved && prototypeSevered;
        }

        private static bool VisualParametersEqual(object left, object right)
        {
            if (left == null || right == null) return ReferenceEquals(left, right);
            string[] fields = { "m_Projectiles", "m_WeaponAnimationStyle",
                "m_SpecialAnimation", "m_WeaponModel", "m_WeaponBeltModel",
                "m_WeaponSheathModel", "m_OverrideAttachSlots",
                "m_PossibleAttachSlots", "m_ReachFXThresholdBonus",
                "m_SoundSize", "m_SoundType", "m_WhooshSound",
                "m_MissSoundType", "m_EquipSound", "m_UnequipSound",
                "m_InventoryEquipSound", "m_InventoryPutSound",
                "m_InventoryTakeSound" };
            return fields.All(name => EquivalentPresentationValue(
                ReadField(left, name), ReadField(right, name)));
        }

        private static int GetProjectileCount(BlueprintWeaponType type)
        {
            object visual = ReadField(type, "m_VisualParameters");
            Array projectiles = visual == null ? null :
                ReadField(visual, "m_Projectiles") as Array;
            return projectiles == null ? 0 : projectiles.Length;
        }

        private static object ReadField(object instance, string name)
        {
            if (instance == null) return null;
            for (Type type = instance.GetType(); type != null; type = type.BaseType)
            {
                FieldInfo field = type.GetField(name, BindingFlags.Instance |
                    BindingFlags.Public | BindingFlags.NonPublic |
                    BindingFlags.DeclaredOnly);
                if (field != null) return field.GetValue(instance);
            }
            throw new MissingFieldException(instance.GetType().FullName, name);
        }

        private static bool EquivalentPresentationValue(object left, object right)
        {
            if (left == null || right == null) return ReferenceEquals(left, right);
            Array leftArray = left as Array, rightArray = right as Array;
            if (leftArray != null || rightArray != null)
            {
                if (leftArray == null || rightArray == null ||
                    leftArray.Length != rightArray.Length) return false;
                for (int index = 0; index < leftArray.Length; index++)
                    if (!EquivalentPresentationValue(leftArray.GetValue(index),
                        rightArray.GetValue(index))) return false;
                return true;
            }
            Type type = left.GetType();
            if (type.IsValueType || left is string) return left.Equals(right);
            return ReferenceEquals(left, right);
        }

        private static string DescribeBlueprintComponents(
            BlueprintScriptableObject blueprint)
        {
            BlueprintComponent[] components = blueprint == null ? null :
                blueprint.ComponentsArray;
            return components == null ? "none" : string.Join(",",
                components.Where(value => value != null)
                    .GroupBy(value => value.GetType().FullName)
                    .OrderBy(value => value.Key, StringComparer.Ordinal)
                    .Select(value => value.Key + "*" + value.Count()).ToArray());
        }

        private RuntimeTestResult RunClassBlueprintContractObservation()
        {
            BlueprintRoot root = BlueprintRoot.Instance;
            BlueprintCharacterClass[] classes = root == null || root.Progression == null
                ? null : root.Progression.CharacterClasses;
            var records = new List<string>();
            bool complete = classes != null && classes.Length > 0;
            if (classes != null)
            {
                foreach (BlueprintCharacterClass characterClass in classes)
                {
                    if (characterClass == null || characterClass.Progression == null ||
                        characterClass.BaseAttackBonus == null ||
                        characterClass.FortitudeSave == null ||
                        characterClass.ReflexSave == null || characterClass.WillSave == null)
                    {
                        complete = false;
                        continue;
                    }
                    records.Add(string.Join(";", new[]
                    {
                        "name=" + characterClass.name,
                        "guid=" + characterClass.AssetGuid,
                        "progression=" + characterClass.Progression.AssetGuid,
                        "bab=" + characterClass.BaseAttackBonus.AssetGuid,
                        "fort=" + characterClass.FortitudeSave.AssetGuid,
                        "ref=" + characterClass.ReflexSave.AssetGuid,
                        "will=" + characterClass.WillSave.AssetGuid,
                        "hitDie=" + characterClass.HitDie,
                        "skills=" + string.Join(",", (characterClass.ClassSkills ??
                            new Kingmaker.EntitySystem.Stats.StatType[0])
                            .Select(value => value.ToString()).ToArray()),
                        "startingItems=" + DescribeStartingItems(characterClass),
                        "level1=" + DescribeLevelOneFeatures(characterClass.Progression)
                    }));
                }
            }
            records.Sort(StringComparer.Ordinal);
            string observed = string.Join(" | ", records.ToArray());
            var assertions = new List<RuntimeTestAssertion>
            {
                Assertion("native-class-root", "nonempty complete native class catalog",
                    "count=" + (classes == null ? -1 : classes.Length) + "; " + observed,
                    complete && records.Count == classes.Length,
                    "BlueprintRoot.Instance.Progression.CharacterClasses exact references"),
                Assertion("observation-only", "no native blueprint mutation",
